window.TADABBUR_GHAFIR = {"_meta":{"description":"تدبّر سورة غافر (٤٠)، وسورةٌ مكّيّةٌ أوّلُ الحواميمِ (السور المفتتحةِ بـ«حم»)، تُسمّى غافرَ والمؤمنَ والطول. محورُها تعظيمُ الله ذي الطولِ والمغفرة، والجدالُ في آياتِ الله وعاقبةُ المجادلين، وقصةُ مؤمنِ آلِ فرعونَ الذي كتم إيمانه ونصح قومه، والدعاءُ وسعةُ رحمةِ الله. تفتتح بوصفِ الله «غافر الذنب وقابل التوب شديد العقاب ذي الطول»، وفيها استغفارُ حملةِ العرشِ للمؤمنين، وقصةُ موسى مع فرعونَ وهامانَ وقارون، وموقفُ الرجلِ المؤمن، وآيةُ «ادعوني أستجب لكم»، وختامُها بأنّ سنّةَ الله في المكذّبين ألا ينفعهم الإيمانُ عند رؤيةِ البأس.","honesty":"كلُّ وقفةٍ مُسنَدةٌ إلى تفسيرٍ معتمد (ابن كثير/السعدي) وموسومةٌ بدرجتها. حالُ القلبِ والعملُ اجتهاديٌّ موسوم. لا يُقدَّم شيءٌ على أنه إعجازٌ مثبت."},"n":40,"name":"غافر","total_ayahs":85,"audio":[1,3,7,28,44,55,60,65,67,85],"passages":[{"title":"تنزيلُ الكتابِ وأوصافُ الله ذي الطول، والجدالُ في الآياتِ وعاقبةُ المكذّبين","range":[1,6],"theme":"افتتاحُ السورةِ بـ«حم» وأنّ القرآنَ تنزيلٌ من العزيزِ العليم، ووصفُ الله بغافرِ الذنبِ وقابلِ التوبِ شديدِ العقابِ ذي الطول، وأنّ الجدالَ في آياتِ الله بالباطلِ من صفةِ الكفّارِ فلا يُغترُّ بتقلّبهم في البلاد، وتكذيبُ الأممِ السابقةِ لرسلهم وجدالُهم بالباطلِ فأخذهم الله، وأنّ كلمةَ العذابِ حقّت على الكافرين","verses":[{"n":1,"reflection":{"text":"«حم»: حروفٌ مقطّعةٌ افتُتِحت بها السورةُ (كأوّلِ الحواميم)، من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه، ويُشار بها إلى إعجازِ القرآنِ المؤلَّفِ من جنسِ هذه الحروفِ التي يعرفونها؛ ففي هذا تنبيهٌ على عظمةِ القرآن؛ فسلّم لما استأثر الله بعلمه، وتدبّر ما بيّنه لك، فالإيمانُ بالمتشابهِ والعملُ بالمحكمِ من صفاتِ الراسخين، فاجعل تسليمك لله فيما لم تعلم علامةَ إيمانك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله فيما استأثر بعلمه، والتدبّرُ لما بيّن."},"action":{"text":"اعلم أنّ سورةَ غافرٍ افتُتِحت بـ«حم»، وهي من الحروفِ المقطّعةِ التي افتُتِحت بها السورُ السبعُ المسمّاةُ بالحواميم، من المتشابهِ الذي استأثر الله بعلمِ المرادِ منه على وجهِ اليقين «حم»؛ وأصحُّ ما قيل فيها أنها إشارةٌ إلى إعجازِ القرآنِ: فهذا الكتابُ المعجزُ مؤلَّفٌ من جنسِ هذه الحروفِ التي تنطقون بها وتعرفونها، ومع ذلك عجزتم عن معارضته؛ فسلّم لما استأثر الله بعلمه من المتشابه؛ وتدبّر واعمل بما بيّنه لك من المحكم؛ فالراسخون في العلمِ يقولون آمنّا به كلٌّ من عند ربنا؛ فاجعل تسليمك لله فيما لم تعلم علامةَ إيمانك ورسوخك؛ ولا تتكلّف الخوضَ فيما لا سبيلَ لك إلى علمه؛ بل آمن بالمتشابه، واعمل بالمحكم؛ فالإيمانُ بالكتابِ كلِّه محكمِه ومتشابهِه من صفاتِ أولي الألباب؛ فسلّم لله، واعمل بما علمت، وكِل ما لم تعلم إلى عالمه."}},{"n":2,"reflection":{"text":"«تنزيل الكتاب من الله العزيز العليم»: هذا القرآنُ منزّلٌ من الله العزيزِ الغالبِ العليمِ بكلِّ شيء؛ ففي هذا تعظيمُ القرآنِ وبيانُ مصدرِه؛ فعظّم القرآنَ لأنه من الله العزيزِ العليم، وتلقَّه بالقبولِ والتسليم، فما جاء من العليمِ بكلِّ شيءٍ فهو الحقُّ والعلمُ النافع، فأقبل عليه بالتعظيمِ والاتّباع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ القرآنِ لأنه من الله العزيزِ العليم، وتلقّيه بالقبول."},"action":{"text":"عظّم القرآنَ في قلبك، فهو منزّلٌ من الله العزيزِ الغالبِ الذي لا يُقهَر، العليمِ الذي أحاط علمه بكلِّ شيء «تنزيل الكتاب من الله العزيز العليم»؛ فمصدرُ القرآنِ إلهيٌّ عظيم؛ فما دام من الله العزيزِ العليم، فهو الحقُّ كلُّه، والعلمُ النافعُ كلُّه؛ فتلقَّه بالقبولِ والتسليمِ والتعظيم؛ وأقبل عليه بالتلاوةِ والتدبّرِ والعمل؛ فمن عرف أنّ القرآنَ من العليمِ بكلِّ شيءٍ علم أنّ فيه علمَ الأوّلين والآخرين، وشفاءَ القلوب، وهدايةَ الحيارى؛ فاجعل القرآنَ مصدرَ علمك وهدايتك؛ ولا تلتمس العلمَ النافعَ والهدى في غيره؛ فهو من العزيزِ العليم؛ فبتعظيمِ القرآنِ والعملِ به تُنال العزّةُ والعلمُ والهداية."}},{"n":3,"reflection":{"text":"«غافر الذنب وقابل التوب شديد العقاب ذي الطول لا إله إلا هو إليه المصير»: هو غافرُ الذنبِ لمن استغفر، قابلُ التوبِ لمن تاب، شديدُ العقابِ لمن أصرّ، ذو الطولِ والفضلِ الواسع، لا إله إلا هو، إليه المرجع؛ ففي هذا الجمعُ بين صفاتِ الرحمةِ والعقابِ ليُعبَد بالخوفِ والرجاء؛ فاعبد الله راجيًا مغفرته، خائفًا عقابه، شاكرًا فضله، فمن عرف أنه غافرُ الذنبِ شديدُ العقابِ جمع بين الخوفِ والرجاء.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"عبادةُ الله بالخوفِ والرجاء، الجمعُ بين رجاءِ مغفرتِه وخوفِ عقابه."},"action":{"text":"تأمّل أوصافَ الله العظيمةَ في مطلعِ السورة: هو غافرُ الذنبِ يمحوه لمن استغفر، وقابلُ التوبِ يقبلها من التائبين، وشديدُ العقابِ لمن أصرّ واستكبر، وذو الطولِ، أي الفضلِ والسعةِ والإنعامِ الواسع، لا إله إلا هو، إليه المصيرُ والمرجعُ فيجازي كلًّا بعمله «غافر الذنب وقابل التوب شديد العقاب ذي الطول لا إله إلا هو إليه المصير»؛ ففي هذا الجمعُ بين صفاتِ الرحمةِ (المغفرةِ وقبولِ التوبةِ والفضل) وصفةِ العقابِ الشديد؛ ليُعبَد الله بالخوفِ والرجاءِ معًا؛ فاعبد الله راجيًا مغفرته وقبولَ توبتك، خائفًا من شدّةِ عقابه، شاكرًا لسعةِ فضله وطوله؛ فمن عرف أنه غافرُ الذنبِ قابلُ التوبِ رجاه؛ ومن عرف أنه شديدُ العقابِ خافه؛ فاجمع في قلبك بين الخوفِ والرجاء؛ فلا تأمن مكرَ الله فتغترّ، ولا تيأس من رحمته فتقنط؛ فتب من ذنوبك راجيًا قبولها، واحذر المعاصيَ خائفًا عقابها، واشكر فضله ذا الطول؛ فبالخوفِ والرجاءِ يستقيم سيرك إلى الله؛ واعلم أنّ مصيرك إليه، فاستعدّ للقائه."}},{"n":4,"reflection":{"text":"«ما يجادل في آيات الله إلا الذين كفروا فلا يغررك تقلبهم في البلاد»: ما يجادل في آياتِ الله بالباطلِ لدفعِ الحقِّ إلا الكافرون، فلا يغرّنك تنقّلهم في البلادِ للتجارةِ والنعمة؛ ففي هذا ذمُّ الجدالِ بالباطلِ وعدمُ الاغترارِ بنعيمِ الكافرين؛ فاحذر الجدالَ في آياتِ الله بالباطل، ولا تغترّ بما فيه الكافرون من سعةِ الدنيا، فإنها متاعٌ قليلٌ زائل، فالعبرةُ بالعاقبةِ لا بمتاعِ الدنيا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الجدالِ بالباطل، وعدمُ الاغترارِ بنعيمِ الكافرين."},"action":{"text":"اعلم أنّ الله ذمّ الجدالَ في آياته بالباطل، فقال: ما يجادل في آياتِ الله لدفعها وردِّها بالباطلِ والشُّبَه إلا الذين كفروا، فلا يغرّنك يا محمدُ ومن اتّبعك تقلّبُ هؤلاء الكفّارِ وتنقّلهم في البلادِ آمنين متنعّمين في التجارةِ والرزق «ما يجادل في آيات الله إلا الذين كفروا فلا يغررك تقلبهم في البلاد»؛ ففي هذا ذمُّ الجدالِ بالباطلِ في آياتِ الله، والنهيُ عن الاغترارِ بنعيمِ الكافرين وسعةِ دنياهم؛ فاحذر الجدالَ في آياتِ الله بالباطلِ والشُّبَهِ لردِّها ودفعها؛ فهذا دأبُ الكفّار؛ أمّا الجدالُ بالحقِّ لإظهاره ونصرِه فمحمود؛ ولا تغترّ بما عليه الكافرون والفجّارُ من سعةِ الرزقِ والصحّةِ والأمنِ والتنعّم؛ لا يغرّنّك تقلّبُ الذين كفروا في البلاد، متاعٌ قليل؛ فإنّ ذلك متاعٌ قليلٌ زائل، ثم مأواهم جهنم؛ فالعبرةُ بالعاقبةِ لا بمتاعِ الدنيا العاجل؛ فكم من متنعّمٍ في الدنيا شقيٍّ في الآخرة؛ فلا تنظر إلى ظاهرِ نعيمهم، بل إلى عاقبتهم؛ فاجعل نظرك إلى الآخرةِ والعاقبة؛ ولا تغترّ بزخرفِ الدنيا وأهلها."}},{"n":5,"reflection":{"text":"«كذبت قبلهم قوم نوح والأحزاب من بعدهم وهمت كل أمة برسولهم ليأخذوه وجادلوا بالباطل ليدحضوا به الحق فأخذتهم فكيف كان عقاب»: كذّب قبلهم قومُ نوحٍ والأممُ من بعدهم، وهمّت كلُّ أمّةٍ بأخذِ رسولها وقتله، وجادلوا بالباطلِ ليبطلوا به الحق، فأخذتهم بالعذاب، فكيف كان عقابي؟ ففي هذا تسليةُ النبيِّ وبيانُ عاقبةِ المكذّبين المجادلين؛ فاعتبر بعاقبةِ من كذّب وجادل بالباطل، واصبر على أذى المكذّبين كما صبر الرسل، فعاقبةُ المكذّبين الأخذُ والهلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ المكذّبين المجادلين، والصبرُ على أذاهم."},"action":{"text":"اعلم أنّ التكذيبَ والجدالَ بالباطلِ سنّةٌ قديمةٌ في الأممِ المكذّبة: كذّب قبل مشركي قريشٍ قومُ نوح، والأحزابُ المكذّبةُ من بعدهم كعادٍ وثمودَ وقومِ لوطٍ وفرعون، وهمّت كلُّ أمّةٍ برسولهم ليأخذوه ويقتلوه، وجادلوا بالباطلِ والشُّبَهِ ليبطلوا به الحقَّ الذي جاء به الرسل، فأخذهم الله بالعذابِ والهلاك، فكيف كان عقابه لهم؟ كان عقابًا شديدًا «كذبت قبلهم قوم نوح والأحزاب من بعدهم... فأخذتهم فكيف كان عقاب»؛ ففي هذا تسليةٌ للنبيِّ ﷺ، وبيانُ عاقبةِ المكذّبين المجادلين بالباطل؛ فاعتبر بعاقبةِ من كذّب الرسلَ وجادل بالباطلِ ليدحض الحق؛ فمصيرهم الأخذُ والهلاك؛ واصبر على أذى المكذّبين وجدالهم كما صبر الرسلُ من قبلك؛ فما لقيت من أذًى فقد لقي الرسلُ أعظمَ منه؛ فتأسَّ بهم في الصبر؛ واعلم أنّ العاقبةَ للحقِّ وأهله، والهلاكَ للمكذّبين المجادلين؛ فلا يحزنك تكذيبُ المكذّبين ولا جدالهم بالباطل؛ فإنّ الله آخذُهم كما أخذ من قبلهم؛ فاثبت على الحقّ، واصبر، وانتظر عاقبةَ المكذّبين."}},{"n":6,"reflection":{"text":"«وكذلك حقت كلمت ربك على الذين كفروا أنهم أصحاب النار»، وكما حقّ العذابُ على الأممِ الماضية، حقّت كلمةُ ربّك على الكافرين المصرّين أنهم أصحابُ النار؛ ففي هذا بيانُ عدلِ الله في عقوبةِ المصرّين على الكفر؛ فاحذر أن تحقّ عليك كلمةُ العذابِ بالإصرارِ على الكفرِ والمعصية، فبادر بالإيمانِ والتوبةِ قبل أن تحقّ عليك، فالنارُ مصيرُ من أصرّ على الكفر.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن تحقّ كلمةُ العذابِ بالإصرار، والمبادرةُ بالتوبة."},"action":{"text":"اعلم أنّ الله كما حقّ العذابُ على الأممِ الماضيةِ المكذّبة، حقّت وثبتت كلمةُ ربّك، أي قضاؤه وحكمه العادل، على الذين كفروا وأصرّوا على كفرهم، أنهم أصحابُ النارِ الملازمون لها «وكذلك حقت كلمت ربك على الذين كفروا أنهم أصحاب النار»؛ ففي هذا بيانُ عدلِ الله في عقوبةِ المصرّين على الكفر؛ فمن أصرّ على الكفرِ حتى مات عليه حقّت عليه كلمةُ العذابِ فكان من أصحابِ النار؛ فاحذر أن تحقّ عليك كلمةُ العذابِ بالإصرارِ على الكفرِ أو المعصية؛ فبادر بالإيمانِ والتوحيدِ والتوبةِ قبل أن تحقّ عليك الكلمة وتُختَم لك بسوء؛ فالنارُ مصيرُ من أصرّ على الكفرِ ومات عليه؛ فلا تسوّف بالتوبةِ والإيمان؛ فإنّ الخاتمةَ بيدِ الله؛ فاسأل الله حسنَ الخاتمة؛ واعمل عملَ من يخشى أن تحقّ عليه كلمةُ العذاب؛ فبادر بالطاعةِ والتوبةِ والتوحيد؛ فمن بادر بالإيمانِ والتوبةِ نجا، ومن أصرّ حتى مات على الكفرِ حقّت عليه الكلمةُ وكان من أصحابِ النار."}}]},{"title":"استغفارُ حملةِ العرشِ للمؤمنين ودعاؤهم لهم","range":[7,9],"theme":"أنّ الملائكةَ حملةَ العرشِ ومن حولهم يسبّحون بحمدِ ربهم ويستغفرون للمؤمنين، ودعاؤهم بأن يغفر الله للتائبين المتّبعين سبيله ويقيهم عذابَ الجحيم، ويدخلهم جنّاتِ عدنٍ ومن صلح من آبائهم وأزواجهم وذرياتهم، ويقيهم السيّئاتِ فمن وُقِيها فقد رحمه الله وذلك الفوزُ العظيم","verses":[{"n":7,"reflection":{"text":"«الذين يحملون العرش ومن حوله يسبحون بحمد ربهم ويؤمنون به ويستغفرون للذين آمنوا ربنا وسعت كل شيء رحمة وعلما فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم»: الملائكةُ الذين يحملون العرشَ ومن حولهم يسبّحون بحمدِ ربّهم ويؤمنون به ويستغفرون للمؤمنين: ربّنا وسعت كلَّ شيءٍ رحمةً وعلمًا، فاغفر للتائبين المتّبعين سبيلك وقهم عذابَ الجحيم؛ ففي هذا بيانُ محبّةِ الملائكةِ للمؤمنين واستغفارهم لهم؛ فأبشر بأنّ الملائكةَ تستغفر لك إن كنت مؤمنًا تائبًا متّبعًا، فاحرص على الإيمانِ والتوبةِ واتّباعِ سبيلِ الله لتنال دعاءَ الملائكة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على الإيمانِ والتوبةِ واتّباعِ السبيلِ لتنال دعاءَ الملائكة."},"action":{"text":"تأمّل هذا المشهدَ العظيم: الملائكةُ الذين يحملون العرشَ، وهم من أعظمِ الملائكةِ خلقًا، ومن حولهم من الملائكةِ المقرّبين، يسبّحون بحمدِ ربّهم ويؤمنون به، ويستغفرون ويدعون للذين آمنوا من البشر، فيقولون: ربّنا وسعت كلَّ شيءٍ رحمةً وعلمًا، فاغفر للذين تابوا من ذنوبهم واتّبعوا سبيلك ودينك، وقهم عذابَ الجحيم «الذين يحملون العرش ومن حوله يسبحون بحمد ربهم... فاغفر للذين تابوا واتبعوا سبيلك وقهم عذاب الجحيم»؛ ففي هذا بيانُ محبّةِ الملائكةِ للمؤمنين واستغفارهم ودعائهم لهم؛ فما أعظمَ كرامةَ المؤمنِ أن تستغفر له ملائكةُ العرش! فأبشر أيها المؤمنُ التائبُ المتّبعُ لسبيلِ الله بأنّ الملائكةَ المقرّبين يدعون لك ويستغفرون؛ فاحرص على الإيمانِ الصادقِ والتوبةِ النصوحِ واتّباعِ سبيلِ الله وسنّةِ رسولِه؛ فبهذه الأوصافِ تستحقّ دعاءَ الملائكةِ واستغفارهم؛ فتوسّلوا إلى الله برحمته الواسعةِ وعلمه المحيط؛ فاجعل توسّلك إلى الله بصفاته كما توسّلت الملائكة؛ وحقّق أوصافَ من يُستَغفَر لهم: الإيمانَ، والتوبةَ، واتّباعَ سبيلِ الله؛ فمن حقّقها نال دعاءَ الملائكةِ ومغفرةَ الله ووقايةَ الجحيم."}},{"n":8,"reflection":{"text":"«ربنا وأدخلهم جنات عدن التي وعدتهم ومن صلح من آبائهم وأزواجهم وذرياتهم إنك أنت العزيز الحكيم»: يقولون: ربّنا وأدخلهم جنّاتِ عدنٍ التي وعدتهم، ومن صلح من آبائهم وأزواجهم وذرياتهم، إنك أنت العزيزُ الحكيم؛ ففي هذا دعاءُ الملائكةِ للمؤمنين بإدخالِ الجنّةِ ولمَّ شملهم بالصالحين؛ فاحرص على صلاحِ نفسك وأهلك لتُجمَعوا في الجنّة، فقرّةُ العينِ اجتماعُ الأهلِ الصالحين في الجنّة، فادعُ لأهلك بالصلاحِ واعمل على هدايتهم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحرصُ على صلاحِ النفسِ والأهلِ لاجتماعهم في الجنّة."},"action":{"text":"تأمّل تمامَ دعاءِ الملائكةِ للمؤمنين: ربّنا وأدخلهم جنّاتِ عدنٍ، جنّاتِ الإقامةِ الدائمة، التي وعدتهم بها على ألسنِ رسلك، وأدخل معهم من صلح من آبائهم وأزواجهم وذرياتهم؛ إنك أنت العزيزُ الغالبُ الحكيمُ في أفعالك «ربنا وأدخلهم جنات عدن التي وعدتهم ومن صلح من آبائهم وأزواجهم وذرياتهم إنك أنت العزيز الحكيم»؛ ففي هذا دعاءُ الملائكةِ للمؤمنين بإدخالِ الجنّةِ ولمِّ شملهم بمن صلح من أهليهم؛ فمن تمامِ نعيمِ الجنّةِ اجتماعُ المؤمنِ بأحبّائه الصالحين فيها، فتقرّ أعينهم بلقاءِ بعضهم؛ والذين آمنوا واتّبعتهم ذريّتهم بإيمانٍ ألحقنا بهم ذريّتهم؛ فاحرص على صلاحِ نفسك وأهلك لتُجمَعوا في الجنّة؛ فقرّةُ العينِ اجتماعُ الأهلِ الصالحين في دارِ النعيم؛ فادعُ لأهلك، آبائك وأزواجك وذريّتك، بالصلاحِ والهداية؛ ربّنا هب لنا من أزواجنا وذرياتنا قرّةَ أعين؛ واعمل على هدايتهم وتربيتهم على الإيمانِ والطاعة؛ فمن أصلح أهله جُمِع بهم في الجنّة؛ فاجعل همّك صلاحك وصلاحَ أهلك؛ فبالصلاحِ تُجمَعون في جنّاتِ عدن؛ فتوسّل إلى الله العزيزِ الحكيمِ أن يُصلحك ويُصلح أهلك ويجمعكم في جنّته."}},{"n":9,"reflection":{"text":"«وقهم السيئات ومن تق السيئات يومئذ فقد رحمته وذلك هو الفوز العظيم»، وقهم عقوباتِ السيّئاتِ (أو السيّئاتِ نفسها)، ومن تقِه السيّئاتِ يومئذٍ فقد رحمته، وذلك هو الفوزُ العظيم؛ ففي هذا دعاءُ الملائكةِ بالوقايةِ من السيّئاتِ وعاقبتها؛ فاسأل الله أن يقيك السيّئاتِ وعقوباتها، فالوقايةُ من السيّئاتِ رحمةٌ وفوزٌ عظيم، فادعُ الله أن يجنّبك السيّئاتِ ويقيك عاقبتها.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"سؤالُ الله الوقايةَ من السيّئاتِ وعاقبتها، فذلك الفوزُ العظيم."},"action":{"text":"تأمّل خاتمةَ دعاءِ الملائكة: وقهم، يا ربّنا، السيّئاتِ وعقوباتها، فلا يقعوا في السيّئاتِ في الدنيا، ولا تنالهم عقوباتها في الآخرة؛ ومن تقِه السيّئاتِ وعقوباتها يومَ القيامةِ فقد رحمته رحمةً عظيمة، وذلك الوقايةُ من السيّئاتِ هو الفوزُ العظيمُ الذي لا فوزَ بعده «وقهم السيئات ومن تق السيئات يومئذ فقد رحمته وذلك هو الفوز العظيم»؛ ففي هذا دعاءُ الملائكةِ للمؤمنين بالوقايةِ من السيّئاتِ في الدنيا ومن عقوباتها في الآخرة؛ فاسأل الله أن يقيك السيّئاتِ فلا تقع فيها، وأن يقيك عقوباتها فلا تنالك؛ فالوقايةُ من السيّئاتِ رحمةٌ من الله وفوزٌ عظيم؛ فمن وقاه الله السيّئاتِ وعقوباتها يومَ القيامةِ فقد فاز فوزًا لا خسارةَ بعده؛ فادعُ الله أن يجنّبك السيّئاتِ والمعاصي، ويعصمك منها؛ وأن يقيك عاقبتها وعقوبتها؛ اللهم قنا عذابَ النار؛ فالنجاةُ من السيّئاتِ وعقوباتها هي الفوزُ العظيم؛ فاجعل من دعائك: اللهم قني السيّئاتِ ومن تقِه السيّئاتِ يومئذٍ فقد رحمته؛ فبالوقايةِ من السيّئاتِ وعقوباتها تُنال الرحمةُ والفوزُ العظيم."}}]},{"title":"مقتُ الكافرين وندمُهم واعترافُهم، وسببُ عذابهم نفورُهم من التوحيد","range":[10,12],"theme":"أنّ الكافرين يُنادَون في النارِ بأنّ مقتَ الله لهم أكبرُ من مقتهم أنفسهم إذ دُعوا إلى الإيمانِ فكفروا، واعترافُهم بذنوبهم وطلبُهم الخروجَ فلا سبيل، وأنّ سببَ عذابهم أنهم كانوا إذا دُعِي الله وحده كفروا وإن أُشرِك به آمنوا، وأنّ الحكمَ لله العليِّ الكبير","verses":[{"n":10,"reflection":{"text":"«إن الذين كفروا ينادون لمقت الله أكبر من مقتكم أنفسكم إذ تدعون إلى الإيمان فتكفرون»: إنّ الكافرين يُنادَون في النار: لمقتُ الله لكم في الدنيا حين دُعِيتم إلى الإيمانِ فكفرتم أكبرُ من مقتكم اليومَ أنفسكم؛ ففي هذا بيانُ مقتِ الله للكافرين وندمهم على كفرهم؛ فاحذر أن يمقتك الله بردِّ دعوةِ الإيمان، فبادر بالاستجابةِ لدعوةِ الحقِّ، فمقتُ الله أعظمُ من كلِّ ندم، فأجب داعيَ الإيمان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالاستجابةِ لدعوةِ الإيمان، والحذرُ من مقتِ الله."},"action":{"text":"تأمّل حالَ الكافرين يومَ القيامة: إنّ الذين كفروا يُنادَون وهم في النارِ يمقتون أنفسهم ندمًا: لمقتُ الله إيّاكم في الدنيا حين كنتم تُدعَون إلى الإيمانِ فتكفرون وتأبون، أكبرُ وأعظمُ من مقتكم اليومَ أنفسكم «إن الذين كفروا ينادون لمقت الله أكبر من مقتكم أنفسكم إذ تدعون إلى الإيمان فتكفرون»؛ ففي هذا بيانُ مقتِ الله للكافرين، وندمهم يومَ القيامةِ ومقتهم لأنفسهم؛ فيمقتون أنفسهم أشدَّ المقتِ لمّا رأوا عاقبةَ كفرهم، ويُخبَرون أنّ مقتَ الله لهم أكبر؛ فاحذر أن يمقتك الله بردِّ دعوةِ الإيمانِ والإعراضِ عن الحق؛ فمقتُ الله أعظمُ عقوبةٍ وأكبرُ خسران؛ فبادر بالاستجابةِ لدعوةِ الإيمانِ والحقِّ إذا بلغتك؛ ولا تُعرِض عنها فتستحقّ مقتَ الله؛ فمن أجاب داعيَ الإيمانِ رضي الله عنه، ومن ردّه مقته الله؛ فأجب داعيَ الله، وبادر إلى الإيمانِ والطاعة؛ فلا تكن ممّن يُدعى إلى الإيمانِ فيكفر فيمقته الله؛ فاطلب رضا الله بالإيمانِ والاستجابة، واحذر مقته بالإعراضِ والكفر."}},{"n":11,"reflection":{"text":"«قالوا ربنا أمتنا اثنتين وأحييتنا اثنتين فاعترفنا بذنوبنا فهل إلى خروج من سبيل»: قالوا: ربّنا أمتّنا مرتين وأحييتنا مرتين، فاعترفنا بذنوبنا، فهل إلى خروجٍ من النارِ من سبيل؟ ففي هذا اعترافُ الكافرين بذنوبهم حين لا ينفع الاعتراف؛ فاعترف بذنوبك وتب منها في الدنيا حيث ينفع الاعتراف، فالاعترافُ في الآخرةِ لا يُخرِج من النار، فبادر بالتوبةِ والاعترافِ الآن.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعترافُ بالذنبِ والتوبةُ في الدنيا حيث ينفع، لا في الآخرة."},"action":{"text":"تأمّل ندمَ الكافرين واعترافهم يومَ القيامة: قالوا ربّنا أمتّنا اثنتين، كنّا أمواتًا نطفًا ثم أمتّنا بعد الحياة، وأحييتنا اثنتين، أحييتنا في الدنيا ثم بعثتنا للحساب، فأقررنا واعترفنا بذنوبنا وكفرنا، فهل إلى خروجٍ من النارِ من سبيلٍ ورجوعٍ إلى الدنيا لنعمل صالحًا؟ «قالوا ربنا أمتنا اثنتين وأحييتنا اثنتين فاعترفنا بذنوبنا فهل إلى خروج من سبيل»؛ ففي هذا اعترافُ الكافرين بذنوبهم حين لا ينفعهم الاعترافُ ولا الندم؛ فيعترفون ويطلبون الخروجَ فلا يُجابون؛ فاعترف أنت بذنوبك وتب منها في الدنيا حيث ينفع الاعترافُ والتوبة؛ فالاعترافُ بالذنبِ في الدنيا مع التوبةِ سببُ المغفرة؛ أمّا الاعترافُ في الآخرةِ فلا يُخرِج من النارِ ولا ينفع؛ فبادر بالتوبةِ والاعترافِ بذنوبك الآن، في زمنِ القبول؛ فمن اعترف بذنبه وتاب في الدنيا غفر الله له؛ ومن أخّر حتى الآخرةِ لم ينفعه اعترافه؛ اللهم إني ظلمت نفسي فاغفر لي؛ فاعترف بذنبك، وتب منه، واستغفر ربك؛ فالاعترافُ بالذنبِ والتوبةُ منه في الدنيا سبيلُ النجاة؛ فلا تسوّف حتى يأتيَ يومٌ لا ينفع فيه اعترافٌ ولا ندم."}},{"n":12,"reflection":{"text":"«ذلكم بأنه إذا دعي الله وحده كفرتم وإن يشرك به تؤمنوا فالحكم لله العلي الكبير»: ذلك العذابُ بسببِ أنه إذا دُعِي الله وحده في التوحيدِ كفرتم، وإن أُشرِك به صدّقتم، فالحكمُ لله العليِّ الكبير؛ ففي هذا بيانُ سببِ عذابهم: نفورهم من التوحيدِ وقبولهم الشرك؛ فاحذر أن تنفر من التوحيدِ أو تميل إلى الشرك، فالتوحيدُ سببُ النجاةِ والشركُ سببُ الهلاك، فالزم التوحيدَ الخالص، والحكمُ لله وحده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"لزومُ التوحيدِ الخالص، والحذرُ من النفورِ منه أو الميلِ للشرك."},"action":{"text":"تأمّل بيانَ سببِ عذابِ الكافرين: ذلكم العذابُ الذي أنتم فيه بسببِ أنكم كنتم في الدنيا إذا دُعِي الله وحده في مقامِ التوحيدِ ونُفِيت الآلهةُ سواه كفرتم ونفرتم، وإن أُشرِك بالله وذُكِرت آلهتكم آمنتم وصدّقتم؛ فالحكمُ اليومَ لله العليِّ على كلِّ شيء، الكبيرِ الذي كلُّ شيءٍ دونه «ذلكم بأنه إذا دعي الله وحده كفرتم وإن يشرك به تؤمنوا فالحكم لله العلي الكبير»؛ ففي هذا بيانُ سببِ عذابهم: نفورهم من التوحيدِ الخالصِ وقبولهم للشرك؛ فاحذر أن تكون فيك خصلةٌ من هذا؛ فاحذر أن تنفر من التوحيدِ الخالصِ إذا ذُكِر، أو تميل إلى الشركِ وأهله؛ فالتوحيدُ الخالصُ سببُ النجاةِ والفوز، والشركُ سببُ الهلاكِ والعذاب؛ فالزم التوحيدَ الخالصَ لله؛ وأخلص له العبادةَ والدعاء؛ وانفر من الشركِ وأهله؛ فمن أخلص التوحيدَ لله نجا، ومن مال إلى الشركِ هلك؛ واعلم أنّ الحكمَ لله العليِّ الكبيرِ وحده؛ فهو الذي يحكم بين عباده بالعدل؛ فسلّم لحكمه، والزم توحيده؛ فبالتوحيدِ الخالصِ تنجو، وبالشركِ تهلك؛ فاجعل قلبك موحّدًا خالصًا، نافرًا من الشرك، مطمئنًّا إلى التوحيد."}}]},{"title":"آياتُ الله والأمرُ بإخلاصِ الدعاء، ورفعةُ الله ويومُ التلاقِ والجزاءِ العادل","range":[13,17],"theme":"أنّ الله يري عباده آياته وينزل الرزق ولا يتذكّر إلا من ينيب، والأمرُ بدعائه مخلصين له الدين ولو كره الكافرون، وأنه رفيعُ الدرجاتِ ذو العرشِ يلقي الوحيَ لينذر يومَ التلاق، يومَ يبرزون لا يخفى على الله منهم شيء والملكُ فيه لله الواحدِ القهّار، وتُجزى كلُّ نفسٍ بما كسبت لا ظلمَ والله سريعُ الحساب","verses":[{"n":13,"reflection":{"text":"«هو الذي يريكم آياته وينزل لكم من السماء رزقا وما يتذكر إلا من ينيب»: هو الذي يريكم آياته في الآفاقِ والأنفس، وينزل لكم من السماءِ رزقًا (المطرَ الذي يخرج به الزرع)، وما يتذكّر بهذه الآياتِ إلا من يرجع إلى الله؛ ففي هذا أنّ التذكّرَ بالآياتِ من صفاتِ المنيبين؛ فتأمّل في آياتِ الله واتّعظ بها، وكن من المنيبين الذين يتذكّرون، فالإنابةُ إلى الله تفتح القلبَ للتذكّرِ بالآيات.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التذكّرُ بآياتِ الله والإنابةُ إليه، فالمنيبُ هو المتذكّر."},"action":{"text":"تأمّل نعمَ الله وآياته: هو الذي يريكم آياته الدالّةَ على وحدانيّته وقدرته في الآفاقِ والأنفس، وينزل لكم من السماءِ رزقًا، وهو المطرُ الذي يُخرِج به أنواعَ الرزقِ والزرعِ والثمار، وما يتذكّر بهذه الآياتِ ويتّعظ بها إلا من ينيب ويرجع إلى الله بقلبه «هو الذي يريكم آياته وينزل لكم من السماء رزقا وما يتذكر إلا من ينيب»؛ ففي هذا أنّ التذكّرَ والاتّعاظَ بآياتِ الله من صفاتِ المنيبين الراجعين إليه؛ فالآياتُ معروضةٌ للجميع، لكن لا ينتفع بها إلا من أناب إلى الله؛ فتأمّل في آياتِ الله الكونيةِ، في السماءِ والأرضِ والمطرِ والرزقِ والنفس، واتّعظ بها؛ وكن من المنيبين الراجعين إلى الله الذين يتذكّرون بآياته؛ فالإنابةُ إلى الله، بالإقبالِ عليه والرجوعِ إليه، تفتح القلبَ للتذكّرِ والاتّعاظِ بالآيات؛ فمن أناب إلى الله انتفع بآياته وتذكّر، ومن أعرض عنه لم ينتفع بها ولو رآها؛ فأنب إلى الله بقلبك وعملك؛ وتأمّل آياته بعينِ الاعتبار؛ واشكر رزقه الذي ينزله عليك؛ فبالإنابةِ والتذكّرِ تنتفع بآياتِ الله وتزداد إيمانًا."}},{"n":14,"reflection":{"text":"«فادعوا الله مخلصين له الدين ولو كره الكافرون»: فادعوا الله مخلصين له الطاعةَ والدين، ولو كره ذلك الكافرون؛ ففي هذا الأمرُ بإخلاصِ الدعاءِ والدينِ لله؛ فادعُ الله وأخلص له دينك، ولا تبالِ بكراهيةِ الكافرين، فالإخلاصُ حقُّ الله لا يُترَك لكراهيةِ أحد، فاجعل دعاءك وعبادتك خالصةً لله ولو خالفك الناس.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إخلاصُ الدعاءِ والدينِ لله، وعدمُ المبالاةِ بكراهيةِ الكافرين."},"action":{"text":"تأمّل الأمرَ الجامعَ بعد ذكرِ آياتِ الله: فادعوا الله وحده مخلصين له الطاعةَ والدينَ والعبادة، ولا تشركوا به شيئًا، ولو كره ذلك الكافرون وشقّ عليهم «فادعوا الله مخلصين له الدين ولو كره الكافرون»؛ ففي هذا الأمرُ بإخلاصِ الدعاءِ والعبادةِ والدينِ لله وحده؛ فادعُ الله وحده، وأخلص له دينك وعبادتك ودعاءك؛ ولا تصرف شيئًا منها لغيره؛ ولا تبالِ بكراهيةِ الكافرين والمشركين لتوحيدك وإخلاصك؛ فالإخلاصُ حقُّ الله الذي لا يُترَك لكراهيةِ أحدٍ أو مخالفته؛ فاثبت على إخلاصك وتوحيدك ولو خالفك الناسُ وكرهوا؛ فلا تُداهن في دينك، ولا تترك التوحيدَ والإخلاصَ إرضاءً للكافرين؛ فاجعل دعاءك وعبادتك خالصةً لله ولو خالفك الخلقُ كلُّهم؛ فرضا الله مقدّمٌ على رضا الناس؛ ومن التمس رضا الله بسخطِ الناسِ رضي الله عنه وأرضى عنه الناس؛ فأخلص لله، واثبت على توحيدك، ولا تبالِ بمن كره؛ فالإخلاصُ والثباتُ على الحقِّ سبيلُ النجاةِ والفوز، ولو كرهه الكافرون."}},{"n":15,"reflection":{"text":"«رفيع الدرجات ذو العرش يلقي الروح من أمره على من يشاء من عباده لينذر يوم التلاق»: هو رفيعُ الدرجاتِ (العليُّ في ذاته وصفاته)، صاحبُ العرشِ العظيم، يُنزِل الوحيَ بأمره على من يشاء من عباده (الأنبياء) لينذروا الناسَ يومَ يلتقي الخلائق؛ ففي هذا تعظيمُ الله وبيانُ رحمتِه بإرسالِ الوحي؛ فعظّم الله رفيعَ الدرجات، واستعدّ ليومِ التلاقِ الذي أُرسِل الرسلُ للإنذارِ به، فاتّعظ بالنذارةِ واستعدّ للقاءِ الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"تعظيمُ الله رفيعِ الدرجات، والاستعدادُ ليومِ التلاق."},"action":{"text":"تأمّل عظمةَ الله ورحمته: هو رفيعُ الدرجاتِ، العليُّ في ذاته وقدره وصفاته، رفيعُ الصفاتِ رافعُ درجاتِ أوليائه، ذو العرشِ العظيمِ الذي استوى عليه، يُلقي الوحيَ والرسالةَ بأمره على من يشاء من عباده المصطفَين، وهم الأنبياء، لينذروا الناسَ يومَ التلاقِ، يومَ يلتقي الخلقُ للحساب، ويلتقي أهلُ السماءِ وأهلُ الأرض، والعبادُ بأعمالهم «رفيع الدرجات ذو العرش يلقي الروح من أمره على من يشاء من عباده لينذر يوم التلاق»؛ ففي هذا تعظيمُ الله رفيعِ الدرجاتِ ذي العرش، وبيانُ رحمتِه بإرسالِ الوحيِ لإنذارِ العباد؛ فعظّم الله رفيعَ الدرجاتِ ذا العرشِ في قلبك؛ واعلم أنه من رحمته أرسل الرسلَ وأنزل الوحيَ لينذر عبادَه يومَ التلاق؛ فاستعدّ ليومِ التلاقِ الذي أُرسِل الرسلُ للإنذارِ منه؛ فيومئذٍ يلتقي الأوّلون والآخرون، ويلتقي كلُّ عاملٍ بعمله؛ فاتّعظ بالنذارةِ التي جاءت بها الرسل؛ واستعدّ للقاءِ الله بالإيمانِ والعملِ الصالح؛ فمن اتّعظ بالنذارةِ واستعدّ ليومِ التلاقِ نجا؛ فعظّم ربك، واستعدّ للقائه، واتّعظ بإنذارِ رسله."}},{"n":16,"reflection":{"text":"«يوم هم بارزون لا يخفى على الله منهم شيء لمن الملك اليوم لله الواحد القهار»: يومَ يبرزون من قبورهم ظاهرين لا يخفى على الله منهم شيء، يُقال: لمن الملكُ اليوم؟ فيُجاب: لله الواحدِ القهّار؛ ففي هذا بيانُ ظهورِ الخلقِ لله وتفرّدِه بالملكِ يومَ القيامة؛ فاستعدّ ليومٍ تبرز فيه لله لا يخفى عليه منك شيء، واعلم أنّ الملكَ يومئذٍ لله وحده، فاعمل لذلك اليومِ ولا تخفِ عن الله ما تعمل، فهو مطّلعٌ عليك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاستعدادُ ليومِ البروزِ لله، وإدراكُ تفرّدِه بالملك."},"action":{"text":"تأمّل مشهدَ يومِ القيامة: يومَ يبرز الخلقُ من قبورهم ظاهرين لله، لا يسترهم شيء، ولا يخفى على الله منهم شيءٌ من أعمالهم وأحوالهم؛ فيُنادى: لمن الملكُ اليوم؟ فلا يجيب أحد لهيبةِ الموقف، فيجيب الله نفسه: لله الواحدِ القهّارِ الذي قهر كلَّ شيء «يوم هم بارزون لا يخفى على الله منهم شيء لمن الملك اليوم لله الواحد القهار»؛ ففي هذا بيانُ بروزِ الخلقِ لله وظهورهم، وتفرّدِ الله بالملكِ يومَ القيامة؛ فاستعدّ ليومٍ تبرز فيه لله ظاهرًا لا يسترك ساتر، ولا يخفى على الله منك شيء؛ فراقب الله في سرّك وعلنك؛ فهو مطّلعٌ عليك، لا يخفى عليه شيءٌ من عملك؛ يومئذٍ تُعرَضون لا تخفى منكم خافية؛ فاعمل لذلك اليومِ عملًا صالحًا؛ ولا تخفِ عن الله ما تعمل، فهو يراك ويعلم سرّك؛ واعلم أنّ الملكَ يومئذٍ لله الواحدِ القهّارِ وحده، قد انقطعت دعاوى الملوكِ والمتكبّرين؛ فأخلص الملكَ والعبوديةَ لله في الدنيا، قبل أن يظهر تفرّدُه بالملكِ في الآخرة؛ فمن عبد الملكَ الحقَّ وأخلص له نجا يومَ البروز."}},{"n":17,"reflection":{"text":"«اليوم تجزى كل نفس بما كسبت لا ظلم اليوم إن الله سريع الحساب»: اليومَ تُجزى كلُّ نفسٍ بما كسبت من خيرٍ أو شرّ، لا ظلمَ اليوم، إنّ الله سريعُ الحساب؛ ففي هذا تقريرُ عدلِ الجزاءِ وسرعةِ الحساب؛ فاعمل صالحًا لتُجزى خيرًا، واعلم أنّ الجزاءَ بالعدلِ لا ظلمَ فيه، فراقب عملك فإنك مجزيٌّ به، وأنّ الحسابَ قريبٌ سريع، فاستعدّ له.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"العملُ الصالحُ رجاءَ الجزاءِ العادل، والاستعدادُ للحسابِ السريع."},"action":{"text":"تأمّل عدلَ الله يومَ القيامة: اليومَ تُجزى كلُّ نفسٍ بما كسبت من خيرٍ أو شرّ، فمن عمل خيرًا جُزِي خيرًا، ومن عمل شرًّا جُزِي شرًّا؛ لا ظلمَ اليوم، فلا تُنقَص حسنةٌ ولا تُزاد سيّئة؛ إنّ الله سريعُ الحساب، يحاسب الخلقَ كلَّهم في وقتٍ يسير «اليوم تجزى كل نفس بما كسبت لا ظلم اليوم إن الله سريع الحساب»؛ ففي هذا تقريرُ عدلِ الجزاءِ التامِّ وسرعةِ الحساب؛ فاعمل صالحًا لتُجزى خيرًا يومَ الجزاء؛ واجتنب السوءَ لئلا تُجزى شرًّا؛ واعلم أنّ الجزاءَ بالعدلِ التامِّ لا ظلمَ فيه؛ فلا يُظلَم أحدٌ مثقالَ ذرّة؛ فراقب عملك فإنك مجزيٌّ به كاملًا؛ ولا تحتقر من الخيرِ شيئًا ولو صغيرًا، فإنك مجزيٌّ به؛ ولا تستهن بالشرِّ ولو صغيرًا، فإنك مجزيٌّ به؛ واعلم أنّ الحسابَ قريبٌ سريع؛ اقترب للناسِ حسابهم وهم في غفلةٍ معرضون؛ فاستعدّ للحسابِ السريعِ العادل؛ فمن حاسب نفسه في الدنيا خفّ حسابه في الآخرة؛ فحاسب نفسك قبل أن تُحاسَب؛ واعمل عملَ من يعلم أنه مجزيٌّ بعمله في حسابٍ عادلٍ سريع."}}]},{"title":"إنذارُ يومِ الآزفة، وعلمُ الله الخفيّ، وقضاؤه بالحق، والاعتبارُ بالماضين","range":[18,22],"theme":"إنذارُ يومِ الآزفةِ حين القلوبُ لدى الحناجرِ ولا حميمَ للظالمين ولا شفيع، وأنّ الله يعلم خائنةَ الأعينِ وما تخفي الصدور، ويقضي بالحقِّ بخلافِ ما يُدعى من دونه، والحثُّ على السيرِ في الأرضِ للاعتبارِ بعاقبةِ الأممِ التي كانت أشدَّ قوّةً فأخذها الله بذنوبها لكفرها بالبيّناتِ التي جاءت بها الرسل","verses":[{"n":18,"reflection":{"text":"«وأنذرهم يوم الآزفة إذ القلوب لدى الحناجر كاظمين ما للظالمين من حميم ولا شفيع يطاع»، وأنذرهم يومَ القيامةِ القريبة، إذ القلوبُ تبلغ الحناجرَ من شدّةِ الخوفِ ممتلئةً بالكرب، ما للظالمين من قريبٍ ينفع ولا شفيعٍ يُطاع؛ ففي هذا تصويرُ هولِ يومِ القيامةِ للظالمين؛ فاحذر أن تكون من الظالمين الذين لا حميمَ لهم ولا شفيع، فاعمل لتنجو من هولِ ذلك اليوم، فلا ينفع الظالمَ يومئذٍ قريبٌ ولا شفيع.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من ظلمٍ يُفضي إلى يومٍ لا حميمَ فيه ولا شفيع."},"action":{"text":"تأمّل تصويرَ الله لهولِ يومِ القيامة: وأنذرهم يا محمدُ يومَ الآزفةِ، أي القيامةِ القريبةِ الدنوّ، إذ القلوبُ تبلغ الحناجرَ من شدّةِ الخوفِ والفزع، وهم كاظمون ممتلئون كربًا وغمًّا لا يقدرون على الكلام؛ ما للظالمين يومئذٍ من حميمٍ، قريبٍ أو صديقٍ، ينفعهم، ولا شفيعٍ تُقبَل شفاعته «وأنذرهم يوم الآزفة إذ القلوب لدى الحناجر كاظمين ما للظالمين من حميم ولا شفيع يطاع»؛ ففي هذا تصويرُ هولِ يومِ القيامةِ وشدّتِه على الظالمين؛ فتبلغ القلوبُ الحناجرَ فزعًا، ولا ينفع الظالمَ قريبٌ ولا شفيع؛ فاحذر أن تكون من الظالمين، لأنفسهم بالكفرِ والمعاصي، ولغيرهم بالتعدّي، الذين لا حميمَ لهم ولا شفيع؛ فاعمل لتنجو من هولِ ذلك اليومِ العظيم؛ فيومئذٍ لا ينفع مالٌ ولا بنون، ولا حميمٌ ولا شفيع؛ فلا تتّكل على أحدٍ ينجّيك يومئذٍ إلا عملك الصالحُ ورحمةُ الله؛ فبادر بالإيمانِ والتوبةِ والعملِ الصالحِ لتنجو؛ واجتنب الظلمَ الذي عاقبتُه هذا الهولُ العظيم؛ فمن اتّقى الله ولم يظلم نجا يومَ الآزفة، ومن ظلم وقع في الهولِ بلا حميمٍ ولا شفيع؛ فاستعدّ لذلك اليومِ بالتقوى واجتنابِ الظلم."}},{"n":19,"reflection":{"text":"«يعلم خائنة الأعين وما تخفي الصدور»: يعلم الله خيانةَ الأعينِ (النظرةَ المحرّمةَ الخفيّة) وما تخفيه الصدورُ من الأسرار؛ ففي هذا بيانُ إحاطةِ علمِ الله بالخفايا؛ فراقب الله في خفاياك حتى نظراتِ عينك وخواطرِ قلبك، فالله يعلم السرَّ وأخفى، فاستحِ من الله أن يراك حيث نهاك، فعلمُه محيطٌ بكلِّ خفيّ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"مراقبةُ الله في الخفايا حتى نظرةِ العينِ وخاطرِ القلب."},"action":{"text":"تأمّل إحاطةَ علمِ الله بالخفايا: يعلم الله خائنةَ الأعين، وهي النظرةُ المحرّمةُ الخفيّةُ التي يسترقها صاحبها خفيةً، ومسارقةُ النظرِ إلى ما لا يحلّ، ويعلم ما تخفيه الصدورُ وتكنّه من الأسرارِ والنيّاتِ والخواطر «يعلم خائنة الأعين وما تخفي الصدور»؛ ففي هذا بيانُ إحاطةِ علمِ الله بأدقِّ الخفايا وأخفاها؛ فهو يعلم النظرةَ المسترقةَ الخفيّة، وما يجول في الصدورِ من الخواطرِ والنيّات؛ فراقب الله في خفاياك، حتى في نظراتِ عينك وخواطرِ قلبك؛ فغُضّ بصرك عمّا حرّم الله، فإنه يعلم خائنةَ الأعين؛ وطهّر قلبك من النيّاتِ السيّئةِ والخواطرِ المحرّمة، فإنه يعلم ما تخفي الصدور؛ فالله يعلم السرَّ وأخفى؛ ويعلم خائنةَ الأعينِ وما تخفي الصدور؛ فاستحِ من الله أن يراك حيث نهاك، أو يفقدك حيث أمرك؛ فراقبه في السرِّ كما تراقبه في العلن؛ بل مراقبتُه في السرِّ أولى؛ فمن راقب الله في خفاياه استحيا منه فاجتنب المعاصيَ الخفيّة؛ فاجعل مراقبةَ الله رقيبًا على عينك وقلبك وجوارحك؛ فمن علم أنّ الله يطّلع على خائنةِ عينه وخفيّةِ صدره حفظ عينه وقلبه؛ فراقب الله في كلِّ خفيّ."}},{"n":20,"reflection":{"text":"«والله يقضي بالحق والذين يدعون من دونه لا يقضون بشيء إن الله هو السميع البصير»، والله يقضي بالحقِّ والعدل، والذين يدعونهم من دونه لا يقضون بشيءٍ لعجزهم، إنّ الله هو السميعُ البصير؛ ففي هذا تقريرُ أنّ القضاءَ لله وحده وعجزُ ما سواه؛ فاطلب القضاءَ والحاجةَ من الله الذي يقضي بالحقّ، ولا تدعُ من لا يقضي بشيء، فالله وحده السميعُ البصيرُ القادرُ، فأخلص له الدعاءَ والطلب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"طلبُ الحاجةِ من الله وحده، فهو القاضي بالحقِّ السميعُ البصير."},"action":{"text":"تأمّل تفرّدَ الله بالقضاء: والله يقضي بين خلقه بالحقِّ والعدلِ التامّ، والذين يدعونهم المشركون من دونِ الله من الأصنامِ والأوثانِ لا يقضون بشيءٍ ولا يملكون شيئًا لعجزهم التامّ، إنّ الله هو السميعُ لأقوالِ عباده، البصيرُ بأحوالهم وأعمالهم «والله يقضي بالحق والذين يدعون من دونه لا يقضون بشيء إن الله هو السميع البصير»؛ ففي هذا تقريرُ أنّ القضاءَ والحكمَ لله وحده، وعجزُ ما سواه عن القضاءِ بشيء؛ فإذا كان الله وحده يقضي بالحق، وآلهتهم لا تقضي بشيء، فكيف تُدعى وتُعبَد من دونِ الله؟ فاطلب القضاءَ والحاجةَ من الله الذي يقضي بالحقِّ ويملك كلَّ شيء؛ ولا تدعُ من دونه من لا يقضي بشيءٍ ولا يملك ضرًّا ولا نفعًا؛ فالله وحده السميعُ الذي يسمع دعاءك، البصيرُ الذي يرى حالك، القادرُ الذي يقضي حاجتك؛ فأخلص له الدعاءَ والطلبَ والرجاء؛ وادعه وحده، فهو السميعُ المجيب؛ ولا تصرف دعاءك لعاجزٍ لا يسمع ولا يقضي؛ فمن دعا الله السميعَ البصيرَ استجاب له، ومن دعا غيره خاب؛ فاجعل دعاءك وطلبك لله وحده القاضي بالحقِّ السميعِ البصير."}},{"n":21,"reflection":{"text":"«أولم يسيروا في الأرض فينظروا كيف كان عاقبة الذين كانوا من قبلهم كانوا هم أشد منهم قوة وآثارا في الأرض فأخذهم الله بذنوبهم وما كان لهم من الله من واق»: أولم يسيروا في الأرضِ فينظروا كيف كانت عاقبةُ الأممِ قبلهم، وكانوا أشدَّ منهم قوّةً وآثارًا، فأخذهم الله بذنوبهم وما كان لهم من الله واقٍ يقيهم؟ ففي هذا الحثُّ على الاعتبارِ بمصارعِ الأمم؛ فاعتبر بعاقبةِ الأممِ القويّةِ التي أهلكها الله بذنوبها، ولا تغترّ بقوّتك، فالقوّةُ لا تدفع عذابَ الله، فاتّق الله ولا تأمن أخذه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الأممِ القويّة، وعدمُ الاغترارِ بالقوّة."},"action":{"text":"تأمّل الحثَّ على الاعتبار: أولم يسر هؤلاء المكذّبون في الأرضِ فينظروا كيف كانت عاقبةُ الأممِ المكذّبةِ التي كانت قبلهم؟ كانوا هم أشدَّ منهم قوّةً وأكثرَ آثارًا في الأرضِ من العمارةِ والبناءِ والزرع، فأخذهم الله بذنوبهم وأهلكهم، وما كان لهم من الله من واقٍ يقيهم عذابه ويدفعه عنهم «أولم يسيروا في الأرض فينظروا كيف كان عاقبة الذين كانوا من قبلهم... فأخذهم الله بذنوبهم وما كان لهم من الله من واق»؛ ففي هذا الحثُّ على الاعتبارِ بمصارعِ الأممِ الماضية؛ فاعتبر بعاقبةِ الأممِ القويّةِ كعادٍ وثمودَ وفرعونَ التي أهلكها الله بذنوبها رغمَ قوّتها وآثارها؛ فسيروا في الأرضِ فانظروا كيف كان عاقبةُ المكذّبين؛ ولا تغترّ بقوّتك ومالك وجاهك؛ فإنّ القوّةَ والآثارَ لا تدفع عذابَ الله عمّن استحقّه؛ فمن أعظمُ منّا قوّة؟ أولم يروا أنّ الله الذي خلقهم هو أشدُّ منهم قوّة؟ فاتّق الله، ولا تأمن أخذه بذنوبك؛ فما أخذ الله الأممَ إلا بذنوبها؛ فاجتنب الذنوبَ التي أهلكت الأمم؛ واعتبر بمن قبلك؛ فمن اعتبر بغيره سلم، ومن اغترّ بقوّته أُخِذ بذنوبه؛ فاتّق الله، وتب من ذنوبك، ولا تغترّ بقوّةٍ ولا مال؛ فلا واقيَ من عذابِ الله إلا التقوى والتوبة."}},{"n":22,"reflection":{"text":"«ذلك بأنهم كانت تأتيهم رسلهم بالبينات فكفروا فأخذهم الله إنه قوي شديد العقاب»: ذلك الأخذُ بسببِ أنّ رسلهم كانت تأتيهم بالبيّناتِ الواضحةِ فكفروا بها، فأخذهم الله، إنه قويٌّ شديدُ العقاب؛ ففي هذا بيانُ سببِ هلاكهم: الكفرُ بعد البيّنات؛ فاحذر الكفرَ بالحقِّ بعد وضوحِ البيّنات، فإنه سببُ الأخذ، فآمن بما جاءت به الرسلُ من البيّنات، فالله قويٌّ شديدُ العقابِ لمن كفر بالحق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالبيّناتِ، والحذرُ من الكفرِ بها بعد وضوحها."},"action":{"text":"تأمّل بيانَ سببِ هلاكِ الأمم: ذلك الأخذُ والإهلاكُ الذي حلّ بهم بسببِ أنّ رسلهم كانت تأتيهم بالبيّناتِ والحججِ والمعجزاتِ الواضحاتِ الدالّةِ على صدقهم، فكفروا بها وكذّبوا رسلهم، فأخذهم الله بالعذابِ والهلاك، إنه قويٌّ لا يعجزه شيء، شديدُ العقابِ لمن كفر وعصى «ذلك بأنهم كانت تأتيهم رسلهم بالبينات فكفروا فأخذهم الله إنه قوي شديد العقاب»؛ ففي هذا بيانُ سببِ هلاكِ الأمم: الكفرُ بالحقِّ بعد قيامِ البيّناتِ والحجج؛ فما أُخِذوا إلا بعد أن جاءتهم الرسلُ بالبيّناتِ فكفروا؛ فاحذر الكفرَ بالحقِّ والإعراضَ عنه بعد وضوحِ البيّناتِ والأدلّة؛ فإنه سببُ الأخذِ والهلاك؛ فآمن بما جاءت به الرسلُ من البيّناتِ والحق؛ وصدّق بالقرآنِ والوحيِ الذي هو أعظمُ البيّنات؛ ولا تكن ممّن تأتيه البيّناتُ فيكفر بها فيأخذه الله؛ فالله قويٌّ لا يُعجِزه أحد، شديدُ العقابِ لمن كفر بالحقِّ بعد وضوحه؛ فمن آمن بالبيّناتِ نجا، ومن كفر بها بعد قيامِ الحجّةِ أُخِذ؛ فبادر بالإيمانِ والتصديقِ بالحقّ؛ واحذر الكفرَ والإعراضَ بعد البيان؛ فإنّ عاقبتَه الأخذُ من القويِّ شديدِ العقاب."}}]},{"title":"إرسالُ موسى إلى فرعونَ وملئِه وكيدُهم، واستعاذةُ موسى بالله","range":[23,27],"theme":"إرسالُ موسى بالآياتِ والسلطانِ المبين إلى فرعونَ وهامانَ وقارونَ فرموه بالسحرِ والكذب، وأمرُهم بقتلِ أبناءِ المؤمنين وأنّ كيدَ الكافرين في ضلال، وتوعّدُ فرعونَ بقتلِ موسى وتسميتُه الحقَّ فسادًا، واستعاذةُ موسى بربه من كلِّ متكبّرٍ لا يؤمن بيومِ الحساب","verses":[{"n":23,"reflection":{"text":"«ولقد أرسلنا موسى بآياتنا وسلطان مبين»، ولقد أرسلنا موسى بآياتنا (المعجزات) وحجّةٍ واضحةٍ بيّنة؛ ففي هذا بيانُ تأييدِ الله لرسله بالحجج؛ فاعلم أنّ الله يؤيّد رسله بالآياتِ والبراهين، فآمن بما جاء به الرسلُ من الآياتِ البيّنة، فالحقُّ مؤيّدٌ بالبرهان، فاتّبع الحقَّ المؤيّدَ بالحجّة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالحقِّ المؤيّدِ بالآياتِ والبراهين."},"action":{"text":"اعلم أنّ الله أرسل موسى بآياته العظيمةِ ومعجزاته الباهرةِ، كالعصا واليدِ وغيرها، وبسلطانٍ مبينٍ أي حجّةٍ واضحةٍ قاطعةٍ لا تُدفَع «ولقد أرسلنا موسى بآياتنا وسلطان مبين»؛ ففي هذا بيانُ أنّ الله يؤيّد رسله بالآياتِ والبراهينِ الدالّةِ على صدقهم؛ فاعلم أنّ رسلَ الله مؤيّدون بالحججِ والآيات؛ فالحقُّ الذي جاؤوا به مؤيّدٌ بالبرهان؛ فآمن بما جاء به الرسلُ من الآياتِ البيّنةِ والحججِ الواضحة؛ ولا تردّ الحقَّ المؤيّدَ بالبرهان؛ فمن ردّ الحقَّ بعد قيامِ الحجّةِ فهو معاند؛ فاتّبع الحقَّ المؤيّدَ بالآياتِ والدليل؛ فالإيمانُ يقوم على الحجّةِ والبرهان، لا على التقليدِ الأعمى؛ فتأمّل في آياتِ الله وبراهينِ رسله، لتزداد إيمانًا ويقينًا؛ فمن اتّبع الحقَّ ببرهانه اهتدى، ومن ردّه بعد وضوحه ضلّ."}},{"n":24,"reflection":{"text":"«إلى فرعون وهامان وقارون فقالوا ساحر كذاب»: أرسلناه إلى فرعونَ (الملك) وهامانَ (وزيره) وقارونَ (صاحبِ المال)، فقالوا: ساحرٌ كذّاب؛ ففي هذا أنّ أهلَ السلطةِ والمالِ أوّلُ من يعاند الحق؛ فاحذر أن يصدّك جاهٌ أو مالٌ عن قبولِ الحق، فالسلطةُ والمالُ قد يطغيان صاحبهما، فلا تجعل جاهك أو مالك حاجزًا عن الحقّ.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من أن يصدَّ الجاهُ والمالُ عن قبولِ الحق."},"action":{"text":"اعلم أنّ الله أرسل موسى إلى ثلاثةٍ يمثّلون أركانَ الطغيان: فرعونَ صاحبِ الملكِ والسلطان، وهامانَ وزيرِه وصاحبِ التدبير، وقارونَ صاحبِ المالِ والثروة، فقابلوا دعوته بالتكذيبِ والاستهزاء فقالوا: ساحرٌ كذّاب «إلى فرعون وهامان وقارون فقالوا ساحر كذاب»؛ ففي هذا أنّ أهلَ السلطةِ والجاهِ والمالِ كثيرًا ما يكونون أوّلَ من يعاند الحقَّ ويصدّ عنه، لأنّ الحقَّ يهدّد جاههم وسلطانهم؛ فاحذر أن يصدّك جاهٌ أو منصبٌ أو مالٌ عن قبولِ الحقِّ والانقيادِ له؛ فالسلطةُ والمالُ قد يطغيان صاحبهما ويحملانه على ردِّ الحق؛ كلا إنّ الإنسانَ ليطغى أن رآه استغنى؛ فلا تجعل جاهك أو مالك أو منصبك حاجزًا بينك وبين الحقّ؛ بل اجعلها معينةً لك على طاعةِ الله ونصرةِ الحق؛ فكم من صاحبِ جاهٍ ومالٍ ردّ الحقَّ كِبرًا وطغيانًا فهلك؛ فتواضع للحقِّ واقبله ولو كنت ذا سلطانٍ ومال؛ فالعزّةُ في اتّباعِ الحقِّ لا في الاستكبارِ عنه."}},{"n":25,"reflection":{"text":"«فلما جاءهم بالحق من عندنا قالوا اقتلوا أبناء الذين آمنوا معه واستحيوا نساءهم وما كيد الكافرين إلا في ضلال»: فلمّا جاءهم بالحقِّ قالوا: اقتلوا أبناءَ المؤمنين معه واستبقوا نساءهم، وما كيدُ الكافرين إلا في ضياعٍ وبطلان؛ ففي هذا بطشُ الطغاةِ بأهلِ الحقِّ وبطلانُ كيدهم؛ فاعلم أنّ كيدَ أعداءِ الحقِّ يبطل ويضيع، فلا تخف كيدهم، واثبت على الحقّ، فكيدُ الكافرين لا يضرّ أهلَ الحقِّ في النهاية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الثباتُ على الحق، واليقينُ بأنّ كيدَ الكافرين يضيع ويبطل."},"action":{"text":"اعلم أنّ فرعونَ وملأه لمّا جاءهم موسى بالحقِّ من عند الله لجؤوا إلى البطشِ والتنكيلِ بأهلِ الحق، فقالوا: اقتلوا أبناءَ الذين آمنوا مع موسى واستبقوا نساءهم للخدمةِ والإذلال؛ وما كيدُ الكافرين ومكرهم إلا في ضلالٍ وضياعٍ وبطلان، لا يبلغون به مرادهم «فلما جاءهم بالحق من عندنا قالوا اقتلوا أبناء الذين آمنوا معه واستحيوا نساءهم وما كيد الكافرين إلا في ضلال»؛ ففي هذا بطشُ الطغاةِ بأهلِ الحقِّ حين تعجزهم الحجّة، وبيانُ أنّ كيدهم يبطل ويضيع؛ فاعلم أنّ كيدَ أعداءِ الحقِّ ومكرهم يبطل ويضيع في النهاية، ولا يبلغون به ما أرادوا؛ ولا يحيق المكرُ السيّئُ إلا بأهله؛ فلا تخف كيدَ أعداءِ الحقِّ ومكرهم؛ واثبت على الحقِّ ولو آذاك أهلُ الباطلِ وكادوا لك؛ فكيدُ الكافرين لا يضرّ أهلَ الحقِّ في النهاية، بل يرتدّ عليهم؛ فتوكّل على الله، واثبت على الحق؛ فإنّ الله يبطل كيدَ الكائدين؛ فالعاقبةُ للحقِّ وأهله، والخيبةُ لأهلِ الكيدِ والمكر."}},{"n":26,"reflection":{"text":"«وقال فرعون ذروني أقتل موسى وليدع ربه إني أخاف أن يبدل دينكم أو أن يظهر في الأرض الفساد»، وقال فرعونُ: دعوني أقتل موسى وليدعُ ربه، إني أخاف أن يغيّر دينكم أو يظهر الفسادَ في الأرض؛ ففي هذا قلبُ فرعونَ الحقائقَ وتسميةُ الحقِّ فسادًا؛ فاحذر أن تسمّي الحقَّ فسادًا والباطلَ إصلاحًا، فأهلُ الباطلِ يقلبون الحقائق، فزِن الأمورَ بميزانِ الحقِّ لا بأهواءِ الطغاة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من قلبِ الحقائق، ووزنُ الأمورِ بميزانِ الحقّ."},"action":{"text":"تأمّل تلبيسَ فرعونَ وقلبَه للحقائق: قال متوعّدًا: دعوني أقتل موسى وليدعُ ربه الذي يزعم أن يمنعه مني، إني أخاف أن يبدّل دينكم الذي أنتم عليه، أو أن يظهر في الأرضِ الفسادَ «وقال فرعون ذروني أقتل موسى وليدع ربه إني أخاف أن يبدل دينكم أو أن يظهر في الأرض الفساد»؛ فسمّى دعوةَ التوحيدِ فسادًا، وسمّى كفره وطغيانه دينًا يجب حفظه؛ ففي هذا قلبُ فرعونَ للحقائق، وتسميتُه الحقَّ فسادًا والباطلَ صلاحًا؛ فهذا دأبُ أهلِ الباطل: يقلبون الحقائق، ويسمّون الأشياءَ بغيرِ أسمائها؛ فاحذر أن تسمّي الحقَّ فسادًا والباطلَ إصلاحًا؛ وإذا قيل لهم لا تفسدوا في الأرضِ قالوا إنما نحن مصلحون؛ فأهلُ الباطلِ يزيّنون باطلهم ويشوّهون الحق؛ فزِن الأمورَ بميزانِ الحقِّ والوحي، لا بأهواءِ الطغاةِ ودعاياتهم؛ فلا تنخدع بتسميةِ الباطلِ إصلاحًا أو الحقِّ فسادًا؛ بل اعرف الحقَّ بدليله، والباطلَ بضدّه؛ فمن قلب الحقائقَ فقد لبّس وأضلّ؛ فاجعل ميزانك الحقَّ والدليلَ، لا الدعاياتِ والأهواء؛ فبميزانِ الحقِّ تُعرَف الأشياءُ على حقيقتها."}},{"n":27,"reflection":{"text":"«وقال موسى إني عذت بربي وربكم من كل متكبر لا يؤمن بيوم الحساب»، وقال موسى: إني لجأت واستعذت بربي وربّكم من كلِّ متكبّرٍ لا يؤمن بيومِ الحساب؛ ففي هذا لجوءُ موسى إلى الله من كيدِ المتكبّرين؛ فالجأ إلى الله واستعذ به من شرِّ المتكبّرين والطغاة، فالله يعصم من التجأ إليه، فاجعل عياذك بالله من كلِّ شر، فمن عاذ بالله أعاذه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اللجوءُ إلى الله والاستعاذةُ به من شرِّ المتكبّرين."},"action":{"text":"تأمّل لجوءَ موسى إلى الله حين توعّده فرعون: قال إني عذت واعتصمت ولجأت بربي وربّكم من كلِّ متكبّرٍ متجبّرٍ لا يؤمن بيومِ الحساب ولا يخاف عقابَ الله «وقال موسى إني عذت بربي وربكم من كل متكبر لا يؤمن بيوم الحساب»؛ ففي هذا لجوءُ موسى إلى الله والاستعاذةُ به من كيدِ المتكبّرين وشرّهم؛ فلمّا توعّده فرعونُ بالقتلِ لجأ موسى إلى ربه واعتصم به؛ فالجأ أنت إلى الله واستعذ به من شرِّ المتكبّرين والطغاةِ والأشرار؛ فالله يعصم ويحفظ من التجأ إليه واعتصم به؛ فمن عاذ بالله أعاذه، ومن لجأ إليه حماه؛ فاجعل عياذك والتجاءك بالله من كلِّ شرٍّ ومن كلِّ متكبّرٍ باغٍ؛ فأعوذ بكلماتِ الله التامّاتِ من شرِّ ما خلق؛ فمن استعاذ بالله بصدقٍ كفاه شرَّ الأشرار؛ فلا تخف بطشَ المتكبّرين ما دمت معتصمًا بالله؛ فالله أقوى منهم وأعظم؛ فالجأ إليه، واعتصم به، واستعذ به؛ فهو خيرُ حافظٍ وهو أرحمُ الراحمين؛ فمن كان الله معاذه ومعتصمه لم يضرّه كيدُ المتكبّرين."}}]},{"title":"خطبةُ مؤمنِ آلِ فرعونَ الأولى: الدفاعُ عن موسى والتحذيرُ من عاقبةِ الأمم","range":[28,35],"theme":"دفاعُ الرجلِ المؤمنِ الكاتمِ إيمانه عن موسى بالحكمةِ والإنصاف، وتذكيرُه بزوالِ الملكِ ولا ناصرَ من بأسِ الله، وتخويفُه من مثلِ يومِ الأحزابِ ويومِ التنادِ الذي لا عاصمَ فيه، وتذكيرُه بشكّهم في يوسفَ من قبل، وذمُّ المجادلين في آياتِ الله بلا سلطانٍ وأنّ الله يطبع على قلبِ كلِّ متكبّرٍ جبّار","verses":[{"n":28,"reflection":{"text":"«وقال رجل مؤمن من آل فرعون يكتم إيمانه أتقتلون رجلا أن يقول ربي الله وقد جاءكم بالبينات من ربكم وإن يك كاذبا فعليه كذبه وإن يك صادقا يصبكم بعض الذي يعدكم إن الله لا يهدي من هو مسرف كذاب»، وقال رجلٌ مؤمنٌ من آلِ فرعونَ يكتم إيمانه: أتقتلون رجلًا لأن يقول ربي الله وقد جاءكم بالبيّنات؟ إن كان كاذبًا فعليه كذبه، وإن كان صادقًا يصبكم بعضُ ما يعدكم، إنّ الله لا يهدي من هو مسرفٌ كذّاب؛ ففي هذا نصرةُ المؤمنِ للحقِّ بالحكمةِ والحجّة؛ فانصر الحقَّ بالحكمةِ والحجّةِ البالغة، فالمؤمنُ يدافع عن الحقِّ بأحسنِ القول، فتعلّم من حكمتِه في الدفاعِ عن الحق.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"نصرةُ الحقِّ بالحكمةِ والحجّةِ البالغة."},"action":{"text":"تأمّل شجاعةَ مؤمنِ آلِ فرعونَ وحكمته: قال رجلٌ مؤمنٌ من آلِ فرعونَ كان يكتم إيمانه، لمّا عزموا على قتلِ موسى، محاجًّا لهم بالحكمة: أتقتلون رجلًا لمجرّدِ أن يقول ربي الله، وقد جاءكم بالبيّناتِ والحججِ من ربكم على صدقه؟ ثم أنصفهم فقال: إن يك كاذبًا فعليه وبالُ كذبه لا يضرّكم، وإن يك صادقًا يصبكم بعضُ الذي يعدكم من العذاب؛ إنّ الله لا يوفّق من هو مسرفٌ في الكذبِ والطغيان «وقال رجل مؤمن من آل فرعون يكتم إيمانه أتقتلون رجلا أن يقول ربي الله...»؛ ففي هذا نصرةُ المؤمنِ للحقِّ بالحكمةِ والحجّةِ البالغةِ والمنطقِ المنصف؛ فدافع عن موسى بأسلوبٍ حكيمٍ يقطع حجّتهم؛ فانصر الحقَّ بالحكمةِ والحجّةِ والبيانِ الحسن؛ فادعُ إلى سبيلِ ربك بالحكمةِ والموعظةِ الحسنةِ وجادلهم بالتي هي أحسن؛ فالمؤمنُ العاقلُ يدافع عن الحقِّ بأحسنِ القولِ وأقومِ الحجّة، لا بالتهوّرِ والسبّ؛ فتعلّم من حكمةِ هذا المؤمنِ في الدفاعِ عن الحقِّ وإقامةِ الحجّة؛ فانصر الحقَّ حيثما كنت بالحكمةِ والدليلِ والإنصاف؛ فمن نصر الحقَّ بحكمةٍ بلغ مقصده، ومن نصره بتهوّرٍ أفسد أكثرَ ممّا أصلح؛ فاجعل نصرتك للحقِّ بالحكمةِ والحجّةِ البالغة."}},{"n":29,"reflection":{"text":"«يا قوم لكم الملك اليوم ظاهرين في الأرض فمن ينصرنا من بأس الله إن جاءنا قال فرعون ما أريكم إلا ما أرى وما أهديكم إلا سبيل الرشاد»: يا قومِ لكم الملكُ اليومَ غالبين في الأرض، فمن ينصرنا من عذابِ الله إن جاءنا؟ قال فرعون: ما أريكم إلا ما أرى، وما أهديكم إلا سبيلَ الرشاد؛ ففي هذا تذكيرُ المؤمنِ بزوالِ الملكِ وحلولِ العذاب، وغرورُ فرعونَ برأيه؛ فاحذر الاغترارَ بالملكِ والدنيا، وتذكّر أنّ لا ناصرَ من عذابِ الله، ولا تغترّ برأيك كما اغترّ فرعون.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاغترارِ بالملكِ والرأي، وتذكّرُ زوالِ الدنيا والعذاب."},"action":{"text":"تأمّل تمامَ نصحِ المؤمن: يا قومِ لكم الملكُ والسلطانُ اليومَ غالبين ظاهرين في أرضِ مصر، ولكن فمن ينصرنا ويدفع عنّا بأسَ الله وعذابه إن جاءنا بسببِ ظلمنا وطغياننا؟ فذكّرهم بزوالِ الملكِ وحلولِ العذاب؛ فأجابه فرعونُ بغرورٍ واستبداد: ما أريكم من الرأي إلا ما أراه أنا صوابًا، وما أهديكم إلا طريقَ الصوابِ والرشاد «يا قوم لكم الملك اليوم ظاهرين في الأرض فمن ينصرنا من بأس الله إن جاءنا قال فرعون ما أريكم إلا ما أرى وما أهديكم إلا سبيل الرشاد»؛ ففي هذا تذكيرُ المؤمنِ لقومه بزوالِ الملكِ وأنه لا ناصرَ من عذابِ الله، وبيانُ غرورِ فرعونَ برأيه واستبداده؛ فاحذر الاغترارَ بالملكِ والجاهِ والدنيا؛ فإنها زائلةٌ ولا تدفع عذابَ الله؛ وتذكّر أنه لا ناصرَ لك من بأسِ الله إن حلّ بك؛ فمن ينصرك من الله إن أراد بك سوءًا؟ ولا تغترّ برأيك وتستبدّ به كما فعل فرعون؛ فالمستبدُّ برأيه المعجَبُ به هالك؛ بل شاور، واقبل الحقَّ ممّن جاء به؛ فالغرورُ بالرأيِ والملكِ من أسبابِ الهلاك؛ فتواضع، واحذر بأسَ الله، ولا تغترّ بدنياك ورأيك."}},{"n":30,"reflection":{"text":"«وقال الذي آمن يا قوم إني أخاف عليكم مثل يوم الأحزاب»، وقال المؤمنُ: يا قومِ إني أخاف عليكم مثلَ ما أصاب الأممَ المتحزّبةَ على رسلها من العذاب؛ ففي هذا تحذيرُ المؤمنِ قومه بعاقبةِ الأمم؛ فاحذر أن يصيبك ما أصاب المكذّبين، واتّعظ بعاقبةِ الأمم، فالتذكيرُ بعاقبةِ المكذّبين من أساليبِ النصح، فاعتبر بمن قبلك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بعاقبةِ الأممِ المكذّبة، والاتّعاظُ بها."},"action":{"text":"تأمّل استمرارَ نصحِ المؤمنِ لقومه بأسلوبِ التخويفِ والتذكير: قال يا قومِ إني أخاف عليكم إن كذّبتم موسى أن يصيبكم مثلُ يومِ الأحزابِ المكذّبةِ لرسلها من العذابِ والاستئصال «وقال الذي آمن يا قوم إني أخاف عليكم مثل يوم الأحزاب»؛ ففي هذا تحذيرُ المؤمنِ قومه بعاقبةِ الأممِ المكذّبةِ التي تحزّبت على رسلها؛ فخوّفهم بأن يصيبهم ما أصاب من قبلهم؛ فاحذر أنت أن يصيبك ما أصاب المكذّبين من العذابِ والهلاك؛ واتّعظ بعاقبةِ الأممِ المكذّبة؛ فالتذكيرُ بعاقبةِ المكذّبين وتخويفُ العصاةِ بها من أساليبِ النصحِ والدعوة؛ فاعتبر بمن قبلك من الأممِ التي كذّبت فأُهلِكت؛ ولا تسلك سبيلهم فيصيبك ما أصابهم؛ فمن اتّعظ بغيره سلم؛ فتأمّل في مصارعِ الأممِ الماضية، واجعلها عبرةً تحملك على الإيمانِ والطاعةِ واجتنابِ التكذيب؛ فالتاريخُ يعيد نفسه لمن سلك سبيلَ الهالكين؛ فاعتبر واتّعظ، ولا تكن ممّن يصيبه مثلُ يومِ الأحزاب."}},{"n":31,"reflection":{"text":"«مثل دأب قوم نوح وعاد وثمود والذين من بعدهم وما الله يريد ظلما للعباد»: مثلَ عادةِ قومِ نوحٍ وعادٍ وثمودَ ومن بعدهم في التكذيبِ والعقوبة، وما الله يريد ظلمًا للعباد؛ ففي هذا بيانُ أنّ عذابَ الأممِ بذنوبها لا ظلمًا؛ فاعلم أنّ الله لا يظلم عباده، وإنما يعذّبهم بذنوبهم، فاتّق الله ولا تعرّض نفسك للعذابِ بذنوبك، فما ظلمهم الله ولكن ظلموا أنفسهم.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ عدلِ الله، وأنّ العذابَ بالذنوبِ لا ظلمًا."},"action":{"text":"تأمّل تمامَ تحذيرِ المؤمن: أخاف عليكم مثلَ عادةِ وسنّةِ قومِ نوحٍ وعادٍ وثمودَ والأممِ من بعدهم في التكذيبِ فالعقوبة؛ وما الله يريد ظلمًا للعبادِ، بل يعاقبهم بذنوبهم عدلًا منه «مثل دأب قوم نوح وعاد وثمود والذين من بعدهم وما الله يريد ظلما للعباد»؛ ففي هذا بيانُ أنّ عذابَ الأممِ إنما هو بذنوبها لا ظلمًا من الله؛ فاعلم أنّ الله لا يظلم عباده مثقالَ ذرّة؛ إنّ الله لا يظلم الناسَ شيئًا ولكنّ الناسَ أنفسهم يظلمون؛ وما ظلمناهم ولكن كانوا أنفسهم يظلمون؛ فما عذّب الله أمّةً إلا بذنوبها وظلمها لنفسها؛ فاتّق الله، ولا تعرّض نفسك للعذابِ بذنوبك ومعاصيك؛ فإنّ العذابَ إنما ينزل بالذنوب؛ فما أصابك من سيّئةٍ فمن نفسك؛ وما أصابكم من مصيبةٍ فبما كسبت أيديكم؛ فاجتنب الذنوبَ التي تجلب العذاب؛ وتب مما اقترفت؛ واعلم أنّ الله عدلٌ لا يظلم، وإنما يعاقب بالذنب؛ فالسلامةُ في اجتنابِ الذنوبِ والتوبةِ منها؛ فمن اتّقى الله واجتنب معاصيه سلم، ومن أذنب وأصرّ عرّض نفسه للعقوبةِ بعدلِ الله."}},{"n":32,"reflection":{"text":"«ويا قوم إني أخاف عليكم يوم التناد»، ويا قومِ إني أخاف عليكم يومَ القيامةِ الذي يتنادى فيه الناس؛ ففي هذا تخويفُ المؤمنِ قومه بيومِ القيامة؛ فاحذر يومَ التنادِ الذي يتنادى فيه أهلُ الجنّةِ وأهلُ النار، فاستعدّ لذلك اليومِ بالإيمانِ والعمل، فالتذكيرُ بيومِ القيامةِ يبعث على الاستعداد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تذكّرُ يومِ التنادِ (القيامة)، والاستعدادُ له بالإيمانِ والعمل."},"action":{"text":"تأمّل انتقالَ المؤمنِ من التخويفِ بعذابِ الدنيا إلى التخويفِ بعذابِ الآخرة: قال ويا قومِ إني أخاف عليكم يومَ التنادِ، وهو يومُ القيامة، سُمّي بذلك لكثرةِ ما يقع فيه من النداء: ينادي أهلُ الجنّةِ أهلَ النار، وأهلُ النارِ أهلَ الجنّة، ويُنادى أهلُ كلِّ عملٍ بأعمالهم، وينادون بالويلِ والثبور «ويا قوم إني أخاف عليكم يوم التناد»؛ ففي هذا تخويفُ المؤمنِ قومه بيومِ القيامةِ وأهواله؛ فاحذر يومَ التنادِ الذي يتنادى فيه الخلائق؛ فيومئذٍ ينادي أصحابُ الأعرافِ رجالًا، وينادي أصحابُ النارِ أصحابَ الجنّةِ أن أفيضوا علينا من الماء؛ فاستعدّ لذلك اليومِ العظيمِ بالإيمانِ والعملِ الصالح؛ فالتذكيرُ بيومِ القيامةِ وأهواله يبعث القلبَ على الاستعدادِ والعمل؛ فتذكّر يومَ التنادِ وما فيه من الأهوالِ والشدائد؛ واعمل له عملًا ينجّيك؛ فمن خاف يومَ التنادِ استعدّ له، ومن غفل عنه فُوجِئ بأهواله؛ فاجعل خوفَ ذلك اليومِ حافزًا لك على الإيمانِ والطاعةِ والاستعداد."}},{"n":33,"reflection":{"text":"«يوم تولون مدبرين ما لكم من الله من عاصم ومن يضلل الله فما له من هاد»: يومَ تفرّون هاربين، ما لكم من الله من مانعٍ يمنعكم من عذابه، ومن يضلله الله فلا هاديَ له؛ ففي هذا بيانُ أنه لا مفرَّ من الله ولا عاصمَ من عذابه؛ فاعلم أنه لا ملجأ من الله إلا إليه، فالجأ إليه بالطاعةِ والتوبة، فلا عاصمَ من عذابِ الله إلا رحمته، فاطلب عصمته بالإيمانِ والعمل.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ أنه لا عاصمَ من عذابِ الله إلا اللجوءُ إليه بالطاعة."},"action":{"text":"تأمّل تصويرَ المؤمنِ لهولِ يومِ القيامة: يومَ تولّون هاربين فارّين من هولِ النارِ وموقفِ الحساب، ما لكم من الله من عاصمٍ يعصمكم ويمنعكم من عذابه، ومن يضلله الله بعدله فما له من هادٍ يهديه «يوم تولون مدبرين ما لكم من الله من عاصم ومن يضلل الله فما له من هاد»؛ ففي هذا بيانُ أنه لا مفرَّ من الله ولا عاصمَ من عذابه يومَ القيامة؛ فيومئذٍ يفرّ المرءُ ولا مهرب؛ يقول الإنسانُ يومئذٍ أين المفرّ؟ كلا لا وزر، إلى ربك يومئذٍ المستقر؛ فاعلم أنه لا ملجأ ولا منجا من الله إلا إليه؛ لا ملجأ من الله إلا إليه؛ فالجأ إلى الله بالطاعةِ والتوبةِ والإيمان؛ فلا عاصمَ من عذابِ الله إلا رحمته وطاعته؛ فاطلب عصمةَ الله ورحمته بالإيمانِ والعملِ الصالحِ والتوبة؛ فمن لجأ إلى الله عصمه، ومن فرّ منه فلا مفرّ؛ فاجعل فرارك إلى الله لا منه؛ ففرّوا إلى الله؛ فمن فرّ إلى الله بالطاعةِ نجا، ومن أعرض عنه فلا عاصمَ له يومَ التناد."}},{"n":34,"reflection":{"text":"«ولقد جاءكم يوسف من قبل بالبينات فما زلتم في شك مما جاءكم به حتى إذا هلك قلتم لن يبعث الله من بعده رسولا كذلك يضل الله من هو مسرف مرتاب»، ولقد جاءكم يوسفُ من قبلُ بالبيّناتِ فما زلتم في شكٍّ مما جاءكم به، حتى إذا مات قلتم لن يبعث الله بعده رسولًا، كذلك يضلّ الله المسرفَ الشاكّ؛ ففي هذا ذمُّ الشكِّ والإعراضِ عن الحق؛ فاحذر الشكَّ في الحقِّ بعد البيّنات، واقبل الحقَّ بيقين، فالشكُّ والارتيابُ سببُ الضلال، فاجعل إيمانك بالحقِّ يقينًا لا شكّ فيه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الشكِّ في الحقِّ بعد البيّنات، وقبولُه بيقين."},"action":{"text":"تأمّل تذكيرَ المؤمنِ قومه بتاريخهم مع الرسل: ولقد جاءكم يوسفُ عليه السلام من قبلِ موسى بالبيّناتِ والحججِ الواضحة، فما زلتم في شكٍّ وريبٍ مما جاءكم به مدّةَ حياته، حتى إذا مات قلتم يائسين: لن يبعث الله بعده رسولًا؛ كذلك يضلّ الله كلَّ مسرفٍ في المعاصي مرتابٍ شاكٍّ في الحق «ولقد جاءكم يوسف من قبل بالبينات... كذلك يضل الله من هو مسرف مرتاب»؛ ففي هذا ذمُّ الشكِّ والارتيابِ والإعراضِ عن الحقِّ رغمَ البيّنات؛ فاحذر الشكَّ والارتيابَ في الحقِّ بعد قيامِ البيّناتِ والأدلّة؛ فالشكُّ في الحقِّ الواضحِ من أسبابِ الضلال؛ فاقبل الحقَّ بيقينٍ وطمأنينة؛ ولا تجعل قلبك موطنًا للشكِّ والريبِ في دينِ الله؛ فالمؤمنون هم الذين آمنوا بالله ورسوله ثم لم يرتابوا؛ فالإيمانُ الصادقُ يقينٌ لا شكَّ فيه؛ فمن شكّ في الحقِّ بعد وضوحه أضلّه الله، ومن أيقن به اهتدى؛ فاجعل إيمانك بالحقِّ يقينًا راسخًا؛ واحذر الإسرافَ في المعاصي والارتيابَ في الدين؛ فإنهما سببُ الضلالِ والطبعِ على القلب؛ فالزم اليقينَ، واطرح الشكَّ والريب."}},{"n":35,"reflection":{"text":"«الذين يجادلون في آيات الله بغير سلطان أتاهم كبر مقتا عند الله وعند الذين آمنوا كذلك يطبع الله على كل قلب متكبر جبار»: الذين يجادلون في آياتِ الله بغيرِ حجّةٍ أتتهم، عظُم ذلك مقتًا عند الله وعند المؤمنين، كذلك يطبع الله على كلِّ قلبِ متكبّرٍ جبّار؛ ففي هذا ذمُّ الجدالِ في آياتِ الله بلا حجّة، وأنّ الكِبرَ سببُ الطبعِ على القلب؛ فاحذر الجدالَ بالباطلِ والكِبرَ الذي يُطبَع به على القلب، فتواضع للحقِّ واقبله، فالكِبرُ يقفل القلبَ عن الهداية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الجدالِ بالباطلِ والكِبرِ الذي يُطبَع به على القلب."},"action":{"text":"تأمّل ذمَّ الله للمجادلين المتكبّرين: الذين يجادلون في آياتِ الله لدفعها وردِّها بغيرِ حجّةٍ ولا برهانٍ أتاهم من الله، بل بمجرّدِ الهوى والكبر، كبُر ذلك الجدالُ مقتًا وبغضًا عند الله وعند الذين آمنوا؛ كذلك، بسببِ الكِبرِ والجدالِ بالباطل، يطبع الله ويختم على كلِّ قلبِ متكبّرٍ عن الحقِّ جبّارٍ متسلّطٍ ظالم «الذين يجادلون في آيات الله بغير سلطان أتاهم كبر مقتا عند الله وعند الذين آمنوا كذلك يطبع الله على كل قلب متكبر جبار»؛ ففي هذا ذمُّ الجدالِ في آياتِ الله بلا حجّة، وبيانُ أنّ الكِبرَ والجبروتَ سببُ الطبعِ على القلبِ وحرمانِه الهداية؛ فاحذر الجدالَ في آياتِ الله بالباطلِ بلا علمٍ ولا برهان؛ فإنه ممقوتٌ عند الله وعند المؤمنين؛ واحذر الكِبرَ والجبروتَ اللذين يُطبَع بهما على القلبِ فلا يقبل الحق؛ فالقلبُ المتكبّرُ الجبّارُ مطبوعٌ عليه، محرومٌ من الهداية؛ سأصرف عن آياتي الذين يتكبّرون في الأرضِ بغيرِ الحق؛ فتواضع للحقِّ واقبله بلا كبرٍ ولا جدالٍ بالباطل؛ فالتواضعُ يفتح القلبَ للهداية، والكِبرُ يقفله ويطبع عليه؛ فطهّر قلبك من الكِبرِ والجبروت؛ واقبل آياتِ الله بتواضعٍ وانقياد؛ فمن تواضع للحقِّ هُدي، ومن استكبر عنه طُبِع على قلبه."}}]},{"title":"كِبرُ فرعونَ وصرحُه، وخطبةُ المؤمنِ الثانية في الرشادِ والدارين، ونجاتُه","range":[36,46],"theme":"طلبُ فرعونَ من هامانَ بناءَ صرحٍ ليطّلع إلى إلهِ موسى تكبّرًا وأنّ كيده في تباب، ودعوةُ المؤمنِ إلى سبيلِ الرشادِ وبيانُ أنّ الدنيا متاعٌ والآخرةَ دارُ القرار، وأنّ جزاءَ السيّئةِ مثلها والعملِ الصالحِ مع الإيمانِ الجنّةُ بغيرِ حساب، وتعجّبُه من دعوتهم له إلى النارِ وهو يدعوهم إلى العزيزِ الغفّار، وتفويضُه أمره إلى الله فوقاه شرَّ مكرهم وحاق بآلِ فرعونَ سوءُ العذابِ يُعرَضون على النارِ غدوًّا وعشيًّا","verses":[{"n":36,"reflection":{"text":"«وقال فرعون يا هامان ابن لي صرحا لعلي أبلغ الأسباب»، وقال فرعونُ: يا هامانُ ابنِ لي بناءً عاليًا لعلّي أبلغ الطرقَ؛ ففي هذا كِبرُ فرعونَ وتحدّيه لله بجهله؛ فاحذر الكِبرَ والتحدّي لله بجهل، فإنّ فرعونَ بلغ به الكِبرُ أن يطلب الوصولَ إلى الله بصرح، فتواضع لله ولا تتحدّاه بجهلك وغرورك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكِبرِ والتحدّي لله بجهلٍ وغرور."},"action":{"text":"تأمّل بلوغَ الكِبرِ بفرعونَ مبلغه: قال يا هامانُ ابنِ لي صرحًا، بناءً عاليًا شامخًا، لعلّي أبلغ الأسباب «وقال فرعون يا هامان ابن لي صرحا لعلي أبلغ الأسباب»؛ فأراد أن يبني بناءً عاليًا ليصعد به، بزعمه، إلى إلهِ موسى، مكابرةً وتحدّيًا وتلبيسًا على قومه؛ ففي هذا بلوغُ الكِبرِ بفرعونَ أن يتحدّى الله بجهله وغروره؛ فاحذر الكِبرَ والتحدّي لله بجهلٍ وغرور؛ فإنّ فرعونَ بلغ به الكِبرُ والاستكبارُ أن يطلب الوصولَ إلى الله بصرحٍ يبنيه، ويزعم أنه سيطّلع على إلهِ موسى؛ فما أعظمَ جهله وكبره وغروره؛ فتواضع لله، ولا تتحدّاه بجهلك وغرورك؛ ولا تستكبر عن الحقِّ كما استكبر فرعون؛ فالكِبرُ يعمي البصيرةَ ويحمل على التحدّي والمكابرة؛ فاعرف قدرك وضعفك أمام عظمةِ الله؛ ولا تكابر الحقَّ ولا تتحدَّ الله؛ فمن تكبّر على الله أذلّه، ومن تواضع له رفعه؛ فاطرح الكِبرَ والغرور، وتواضع لله وللحق."}},{"n":37,"reflection":{"text":"«أسباب السماوات فأطلع إلى إله موسى وإني لأظنه كاذبا وكذلك زين لفرعون سوء عمله وصد عن السبيل وما كيد فرعون إلا في تباب»: طرقَ السماواتِ فأنظر إلى إلهِ موسى، وإني لأظنّه كاذبًا، وكذلك زُيّن لفرعونَ سوءُ عمله وصُدّ عن السبيل، وما كيدُ فرعونَ إلا في خسارٍ وهلاك؛ ففي هذا تزيينُ السوءِ لصاحبه وبطلانُ كيدِ الطغاة؛ فاحذر أن يُزيَّن لك سوءُ عملك فتراه حسنًا، فاطلب من الله أن يريك الحقَّ حقًّا، فتزيينُ السوءِ يصدّ عن الحقِّ ويورث الهلاك.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من تزيينِ السوءِ للنفس، وطلبُ رؤيةِ الحقِّ حقًّا."},"action":{"text":"تأمّل تمامَ غرورِ فرعونَ وعاقبته: أراد أن يبلغ أسبابَ السماواتِ وطرقها فيطّلع إلى إلهِ موسى، وقال متكبّرًا: وإني لأظنّه كاذبًا فيما يدّعيه؛ وكذلك زُيّن لفرعونَ سوءُ عمله فرآه حسنًا، وصُدّ عن سبيلِ الحقِّ والهدى، وما كيدُ فرعونَ ومكره إلا في خسارٍ وهلاكٍ وتباب «أسباب السماوات فأطلع إلى إله موسى وإني لأظنه كاذبا وكذلك زين لفرعون سوء عمله وصد عن السبيل وما كيد فرعون إلا في تباب»؛ ففي هذا بيانُ خطرِ تزيينِ السوءِ لصاحبه، وبطلانِ كيدِ الطغاة؛ فأعظمُ عقوبةٍ أن يُزيَّن للعبدِ سوءُ عمله فيراه حسنًا؛ أفمن زُيّن له سوءُ عمله فرآه حسنًا؛ فاحذر أن يُزيَّن لك سوءُ عملك فتحسبه حسنًا وأنت مسيء؛ فمن أخطرِ الآفاتِ أن يفعل الإنسانُ المنكرَ وهو يظنّه معروفًا؛ قل هل ننبّئكم بالأخسرين أعمالًا الذين ضلّ سعيهم في الحياةِ الدنيا وهم يحسبون أنهم يحسنون صنعًا؛ فاطلب من الله أن يريك الحقَّ حقًّا ويرزقك اتّباعه، والباطلَ باطلًا ويرزقك اجتنابه؛ فتزيينُ السوءِ يصدّ عن سبيلِ الحقِّ ويورث الهلاك؛ فراقب عملك بميزانِ الشرع، لا بهوى نفسك؛ واعلم أنّ كيدَ الطغاةِ وأهلِ الباطلِ في خسارٍ وتباب؛ فلا تغترّ بكيدك وتدبيرك إن كان في باطل؛ فالعاقبةُ خسارٌ وهلاك."}},{"n":38,"reflection":{"text":"«وقال الذي آمن يا قوم اتبعون أهدكم سبيل الرشاد»، وقال المؤمنُ: يا قومِ اتّبعوني أرشدكم إلى سبيلِ الحقِّ والصواب؛ ففي هذا دعوةُ المؤمنِ قومه إلى الرشاد؛ فادعُ إلى سبيلِ الرشادِ من عرفت الحق، واتّبع من يدلّك على الحق، فالدعوةُ إلى الرشادِ من صفاتِ المؤمنين، فكن داعيًا إلى الحقِّ ومتّبعًا له.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ إلى سبيلِ الرشاد، واتّباعُ من يدلّ على الحق."},"action":{"text":"تأمّل ثباتَ المؤمنِ ومواصلتَه الدعوة: قال يا قومِ اتّبعوني فيما أدعوكم إليه من الإيمانِ والتوحيد، أهدكم وأرشدكم إلى سبيلِ الرشادِ والحقِّ والصواب «وقال الذي آمن يا قوم اتبعون أهدكم سبيل الرشاد»؛ ففي هذا دعوةُ المؤمنِ قومه إلى سبيلِ الرشادِ باللينِ والنصح؛ فقابل دعوى فرعونَ الكاذبةَ «وما أهديكم إلا سبيل الرشاد» بالدعوةِ الصادقةِ إلى الرشادِ الحقيقي؛ فادعُ إلى سبيلِ الرشادِ والحقِّ من عرفت الحقَّ وأيقنت به؛ فالدعوةُ إلى الله وإلى سبيلِ الرشادِ من صفاتِ المؤمنين الصادقين؛ ومن أحسنُ قولًا ممّن دعا إلى الله وعمل صالحًا؛ واتّبع من يدلّك على الحقِّ والرشاد؛ فاتّبع أهلَ العلمِ والإيمانِ الذين يهدون إلى الحق؛ فكن داعيًا إلى الحقِّ ومتّبعًا له؛ فادعُ الناسَ إلى ما تعتقده حقًّا بالحكمةِ والنصح؛ وانصح لهم كما نصح هذا المؤمنُ لقومه؛ فمن دعا إلى الرشادِ واتّبعه فقد جمع بين الخيرين؛ فاجعل همّك الدعوةَ إلى الحقِّ واتّباعه؛ فبالدعوةِ إلى الرشادِ واتّباعه تنفع نفسك وغيرك."}},{"n":39,"reflection":{"text":"«يا قوم إنما هذه الحياة الدنيا متاع وإن الآخرة هي دار القرار»: يا قومِ إنما هذه الحياةُ الدنيا متاعٌ زائلٌ قليل، وإنّ الآخرةَ هي دارُ الإقامةِ والاستقرار؛ ففي هذا بيانُ حقيقةِ الدنيا والآخرة؛ فاعلم أنّ الدنيا متاعٌ زائل، والآخرةَ دارُ القرار، فاعمل للآخرةِ الباقية، ولا تؤثر الدنيا الفانيةَ على الآخرةِ الدائمة، فالعاقلُ يعمل لدارِ القرار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"إيثارُ الآخرةِ الباقيةِ على الدنيا الفانية، والعملُ لدارِ القرار."},"action":{"text":"تأمّل موعظةَ المؤمنِ البليغةَ في حقيقةِ الدارين: يا قومِ إنما هذه الحياةُ الدنيا متاعٌ قليلٌ زائلٌ يُتمتّع به قليلًا ثم يزول، وإنّ الآخرةَ هي دارُ القرارِ والإقامةِ الدائمةِ التي لا زوالَ لها «يا قوم إنما هذه الحياة الدنيا متاع وإن الآخرة هي دار القرار»؛ ففي هذا بيانُ حقيقةِ الدنيا والآخرة: الدنيا متاعٌ فانٍ، والآخرةُ دارُ قرارٍ باقية؛ فاعلم أنّ الدنيا مهما طالت وتنعّمت فهي متاعٌ زائلٌ قليل؛ وما الحياةُ الدنيا إلا متاعُ الغرور؛ وأنّ الآخرةَ هي دارُ القرارِ والخلودِ والبقاء؛ فاعمل للآخرةِ الباقيةِ لا للدنيا الفانية؛ ولا تؤثر الدنيا العاجلةَ الزائلةَ على الآخرةِ الآجلةِ الباقية؛ بل تؤثرون الحياةَ الدنيا والآخرةُ خيرٌ وأبقى؛ فالعاقلُ يعمل لدارِ القرارِ والخلود، لا لدارِ الفناءِ والزوال؛ فاجعل الدنيا مزرعةً للآخرة، ووسيلةً لا غاية؛ واعمل فيها لما يبقى لك في دارِ القرار؛ فمن آثر الآخرةَ على الدنيا ربح، ومن آثر الدنيا على الآخرةِ خسر؛ فاجعل همّك دارَ القرار؛ فإليها المصير، وفيها الخلود."}},{"n":40,"reflection":{"text":"«من عمل سيئة فلا يجزى إلا مثلها ومن عمل صالحا من ذكر أو أنثى وهو مؤمن فأولئك يدخلون الجنة يرزقون فيها بغير حساب»: من عمل سيّئةً فلا يُجزى إلا مثلها، ومن عمل صالحًا من ذكرٍ أو أنثى وهو مؤمنٌ فأولئك يدخلون الجنّةَ يُرزَقون فيها بغيرِ حساب؛ ففي هذا عدلُ الله في جزاءِ السيّئةِ وفضلُه في جزاءِ الحسنة؛ فاعمل صالحًا مؤمنًا لتدخل الجنّةَ وتُرزَق بغيرِ حساب، فجزاءُ الحسنةِ بفضلٍ لا حساب، وجزاءُ السيّئةِ بعدلٍ مثلها، فأكثر من الصالحات.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من العملِ الصالحِ مع الإيمان، رجاءَ الرزقِ بغيرِ حساب."},"action":{"text":"تأمّل عدلَ الله وفضله في الجزاء الذي ذكّر به المؤمن: من عمل سيّئةً فلا يُجزى إلا مثلها عدلًا، لا يُزاد على سيّئته؛ ومن عمل صالحًا من ذكرٍ أو أنثى، فالجزاءُ لا يختصّ بجنس، وهو مؤمنٌ بالله، فأولئك يدخلون الجنّةَ يُرزَقون فيها بغيرِ حسابٍ ولا عدّ، فضلًا من الله «من عمل سيئة فلا يجزى إلا مثلها ومن عمل صالحا من ذكر أو أنثى وهو مؤمن فأولئك يدخلون الجنة يرزقون فيها بغير حساب»؛ ففي هذا عدلُ الله في جزاءِ السيّئةِ بمثلها، وفضلُه العظيمُ في جزاءِ الحسنةِ بغيرِ حساب؛ فالسيّئةُ تُجزى بمثلها عدلًا، والحسنةُ تُضاعَف أضعافًا كثيرةً فضلًا، حتى يدخل المؤمنُ العاملُ الجنّةَ ويُرزَق فيها بلا حساب؛ فاعمل صالحًا مع الإيمانِ لتدخل الجنّةَ وتُرزَق فيها بغيرِ حساب؛ فشرطُ قبولِ العملِ الصالحِ الإيمان؛ فمن عمل صالحًا وهو مؤمنٌ فله الجنّةُ والرزقُ الواسع؛ فأكثر من الأعمالِ الصالحةِ مع تحقيقِ الإيمان؛ ولا تحتقر من الحسناتِ شيئًا؛ فجزاءُ الحسنةِ بفضلِ الله لا حسابَ له؛ وجزاءُ السيّئةِ بعدلِ الله مثلها؛ فاجتنب السيّئات، وأكثر من الحسنات؛ فبالإيمانِ والعملِ الصالحِ تُنال الجنّةُ والرزقُ بغيرِ حساب."}},{"n":41,"reflection":{"text":"«ويا قوم ما لي أدعوكم إلى النجاة وتدعونني إلى النار»، ويا قومِ ما لي أدعوكم إلى النجاةِ وأنتم تدعونني إلى النار؟ ففي هذا تعجّبُ المؤمنِ من دعوتهم له إلى الهلاك؛ فتعجّب من حالِ من يدعوك إلى النارِ وأنت تدعوه إلى النجاة، ولا تستجب لمن يدعوك إلى الهلاك، بل ادعُ إلى النجاة، فالداعي إلى الحقِّ يدعو إلى النجاة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ إلى النجاة، ورفضُ من يدعو إلى الهلاك."},"action":{"text":"تأمّل تعجّبَ المؤمنِ من قومه: يا قومِ ما شأني وما بالي أدعوكم إلى النجاةِ من النارِ بالإيمانِ والتوحيد، وأنتم تدعونني إلى النارِ بالكفرِ والشرك؟ «ويا قوم ما لي أدعوكم إلى النجاة وتدعونني إلى النار»؛ ففي هذا تعجّبُ المؤمنِ من حالِ قومه الذين يقابلون دعوته إلى النجاةِ بدعوتهم له إلى الهلاك؛ فما أعجبَ حالَ من يُنصَح فيقابل الناصحَ بدعوته إلى الشر؛ فتعجّب أنت من حالِ من يدعوك إلى النارِ والهلاكِ وأنت تدعوه إلى النجاةِ والفلاح؛ ولا تستجب لمن يدعوك إلى الهلاكِ والمعصيةِ والشرك؛ بل ادعُ أنت إلى النجاةِ والحقِّ والخير؛ فالداعي إلى الله والحقِّ يدعو إلى النجاة، والداعي إلى الكفرِ والمعصيةِ يدعو إلى النار؛ فميّز بين الداعيَين؛ واستجب لمن يدعوك إلى النجاة، وأعرض عمّن يدعوك إلى النار؛ ولا يغرّنك كثرةُ الداعين إلى الشر؛ فكن داعيًا إلى النجاة، رافضًا دعوةَ أهلِ النار؛ فمن دعا إلى النجاةِ ونصح فقد أحسن، ومن دعا إلى النارِ فقد ظلم؛ فاختر لنفسك دعوةَ النجاة، وادعُ إليها."}},{"n":42,"reflection":{"text":"«تدعونني لأكفر بالله وأشرك به ما ليس لي به علم وأنا أدعوكم إلى العزيز الغفار»: تدعونني لأكفر بالله وأشرك به ما لا علمَ لي بألوهيّته، وأنا أدعوكم إلى العزيزِ الغفّار؛ ففي هذا مقابلةُ دعوةِ الشركِ بدعوةِ التوحيد؛ فاعلم أنّ الشركَ عبادةٌ بلا علمٍ ولا برهان، وأنّ التوحيدَ دعوةٌ إلى العزيزِ الغفّار، فادعُ إلى الله العزيزِ الغفّار، ولا تشرك به ما لا برهانَ عليه.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الدعوةُ إلى الله العزيزِ الغفّار، ونبذُ الشركِ الذي لا علمَ فيه."},"action":{"text":"تأمّل حجّةَ المؤمنِ في مقابلةِ الدعوتين: تدعونني لأكفر بالله وأشرك به آلهةً لا علمَ لي بأنها تستحقّ العبادة، بل أعلم يقينًا بطلانها؛ وأنا أدعوكم إلى عبادةِ الله العزيزِ الغالبِ الغفّارِ لمن تاب «تدعونني لأكفر بالله وأشرك به ما ليس لي به علم وأنا أدعوكم إلى العزيز الغفار»؛ ففي هذا مقابلةُ دعوةِ الشركِ الباطلةِ بدعوةِ التوحيدِ الحقّة؛ فبيّن الفرقَ بين الدعوتين: دعوتهم إلى شركٍ لا علمَ فيه ولا برهان، ودعوته إلى توحيدِ العزيزِ الغفّار؛ فاعلم أنّ الشركَ عبادةٌ بلا علمٍ ولا حجّةٍ ولا برهان؛ فما يعبد المشركون إلا ظنًّا وتقليدًا وهوًى؛ وأنّ التوحيدَ دعوةٌ إلى الله العزيزِ الغالبِ القادر، الغفّارِ الذي يغفر لمن تاب؛ فادعُ إلى الله العزيزِ الغفّار؛ وأخلص له العبادة؛ ولا تشرك به ما لا برهانَ عليه ولا علمَ لك بألوهيّته؛ فالتوحيدُ قائمٌ على العلمِ والبرهان، والشركُ قائمٌ على الظنِّ والتقليد؛ فاطلب معبودك بالعلمِ والدليل؛ فلا تجد إلا الله وحده مستحقًّا للعبادة؛ فادعُ إليه، واعبده، ولا تشرك به شيئًا؛ فهو العزيزُ الغفّار، الجديرُ وحده بالعبادة."}},{"n":43,"reflection":{"text":"«لا جرم أنما تدعونني إليه ليس له دعوة في الدنيا ولا في الآخرة وأن مردنا إلى الله وأن المسرفين هم أصحاب النار»: حقًّا أنّ ما تدعونني إليه (الأصنام) ليس له استجابةُ دعوةٍ في الدنيا ولا في الآخرة، وأنّ مرجعنا إلى الله، وأنّ المسرفين هم أصحابُ النار؛ ففي هذا بيانُ عجزِ المعبوداتِ الباطلةِ وحتميّةِ المرجعِ إلى الله؛ فلا تدعُ ما لا يستجيب، وادعُ الله الذي إليه المرجع، واحذر الإسرافَ في المعاصي الذي يورد النار.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"دعاءُ الله وحده الذي إليه المرجع، ونبذُ ما لا يستجيب."},"action":{"text":"تأمّل تمامَ حجّةِ المؤمن: حقًّا وصدقًا أنّ ما تدعونني إلى عبادته من الأصنامِ والآلهةِ الباطلةِ ليس له استجابةُ دعوةٍ لأحدٍ في الدنيا ولا في الآخرة، لعجزه وبطلانه؛ وأنّ مرجعنا ومردّنا جميعًا إلى الله فيجازينا؛ وأنّ المسرفين المتجاوزين حدودَ الله بالكفرِ والمعاصي هم أصحابُ النار «لا جرم أنما تدعونني إليه ليس له دعوة في الدنيا ولا في الآخرة وأن مردنا إلى الله وأن المسرفين هم أصحاب النار»؛ ففي هذا بيانُ عجزِ المعبوداتِ الباطلةِ عن الاستجابة، وحتميّةِ المرجعِ إلى الله، وعاقبةِ المسرفين؛ فلا تدعُ ما لا يستجيب لك من الأصنامِ والأمواتِ والمخلوقات؛ فمن أضلُّ ممّن يدعو من دونِ الله من لا يستجيب له إلى يومِ القيامة؟ وادعُ الله وحده الذي إليه مرجعك ومصيرك؛ فمردّنا إلى الله؛ فاستعدّ للقائه بالإيمانِ والعملِ الصالح؛ واحذر الإسرافَ في المعاصي والكفرِ الذي يجعل صاحبه من أصحابِ النار؛ فالمسرفون في الذنوبِ والكفرِ هم أصحابُ النار؛ فأخلص الدعاءَ لله، واستعدّ للمرجعِ إليه، واجتنب الإسرافَ في المعاصي؛ فبذلك تنجو من النار."}},{"n":44,"reflection":{"text":"«فستذكرون ما أقول لكم وأفوض أمري إلى الله إن الله بصير بالعباد»: فستذكرون ما أقول لكم حين ينفعكم الذكر، وأفوّض أمري إلى الله، إنّ الله بصيرٌ بالعباد؛ ففي هذا تفويضُ المؤمنِ أمره إلى الله؛ ففوّض أمرك إلى الله واعتمد عليه، فالتفويضُ إلى الله راحةٌ وثقة، فمن فوّض أمره إلى الله كفاه، فاجعل تفويضك وتوكّلك على الله البصيرِ بعباده.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تفويضُ الأمرِ إلى الله والاعتمادُ عليه، فهو البصيرُ بالعباد."},"action":{"text":"تأمّل خاتمةَ موقفِ المؤمنِ العظيم: قال فستذكرون ما أقول لكم من النصحِ حين تعاينون العذابَ ولا ينفعكم الذكر؛ وأفوّض أمري كلَّه إلى الله وأعتمد عليه في دفعِ شرّكم، إنّ الله بصيرٌ بالعبادِ لا يخفى عليه شيءٌ من أحوالهم «فستذكرون ما أقول لكم وأفوض أمري إلى الله إن الله بصير بالعباد»؛ ففي هذا تفويضُ المؤمنِ أمره إلى الله واعتمادُه عليه عند مواجهةِ الطغاة؛ فلمّا بلّغ النصحَ فوّض أمره إلى الله وتوكّل عليه؛ ففوّض أمرك كلَّه إلى الله، واعتمد عليه في جميعِ شؤونك؛ فالتفويضُ إلى الله، وهو ردُّ الأمورِ إليه والاعتمادُ عليه في جلبِ النفعِ ودفعِ الضرّ، راحةٌ للقلبِ وثقةٌ بالله؛ فمن فوّض أمره إلى الله كفاه وحماه؛ ومن يتوكّل على الله فهو حسبه؛ فاجعل تفويضك وتوكّلك على الله البصيرِ بعباده وأحوالهم؛ فهو يعلم حالك ويكفيك ما أهمّك؛ فبلّغ ما عليك من الحقِّ والنصح، ثم فوّض الأمرَ إلى الله؛ فإذا فعلت ما عليك فوّض النتائجَ إلى الله؛ فمن فوّض أمره إلى الله بعد بذلِ السببِ كفاه الله وتولّاه؛ فالتفويضُ إلى الله من أعلى مقاماتِ التوكّل؛ فاجعله دأبك بعد بذلِ ما تقدر عليه."}},{"n":45,"reflection":{"text":"«فوقاه الله سيئات ما مكروا وحاق بآل فرعون سوء العذاب»: فوقاه الله شرَّ مكرهم، وأحاط بآلِ فرعونَ سوءُ العذاب؛ ففي هذا ثمرةُ التفويضِ إلى الله: الوقايةُ من المكر، وعاقبةُ الماكرين؛ فاعلم أنّ من فوّض أمره إلى الله وقاه شرَّ الماكرين، فتوكّل على الله يقك شرّهم، فالله يحفظ من التجأ إليه ويحيق المكرُ بأهله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بأنّ التفويضَ إلى الله يقي شرَّ الماكرين."},"action":{"text":"تأمّل ثمرةَ تفويضِ المؤمنِ أمره إلى الله: فوقاه الله وحفظه من سيّئاتِ ما مكروا به وأرادوا من الشرّ، فنجّاه من كيدهم؛ وأحاط بآلِ فرعونَ سوءُ العذابِ فأغرقهم الله جميعًا «فوقاه الله سيئات ما مكروا وحاق بآل فرعون سوء العذاب»؛ ففي هذا ثمرةُ التفويضِ إلى الله: الوقايةُ من مكرِ الماكرين، وحلولُ العذابِ بأهلِ المكر؛ فلمّا فوّض المؤمنُ أمره إلى الله وقاه الله شرَّ مكرهم؛ فاعلم أنّ من فوّض أمره إلى الله واعتمد عليه وقاه الله شرَّ الماكرين والكائدين؛ ومن يتوكّل على الله فهو حسبه؛ فتوكّل على الله وفوّض أمرك إليه يقك شرَّ من يمكر بك؛ فالله يحفظ من التجأ إليه واعتمد عليه؛ ويحيق المكرُ السيّئُ بأهله؛ ولا يحيق المكرُ السيّئُ إلا بأهله؛ فلا تخف مكرَ الماكرين ما دمت متوكّلًا على الله؛ فإنّ الله يقيك شرّهم، ويردّ كيدهم في نحورهم؛ فمن توكّل على الله وقاه ونجّاه، وأحاط بأعدائه العذاب؛ فاجعل توكّلك وتفويضك على الله؛ فبه تُوقى شرَّ الأشرارِ ومكرَ الماكرين."}},{"n":46,"reflection":{"text":"«النار يعرضون عليها غدوا وعشيا ويوم تقوم الساعة أدخلوا آل فرعون أشد العذاب»: النارُ يُعرَضون عليها صباحًا ومساءً (في البرزخ)، ويومَ القيامةِ يُقال: أدخلوا آلَ فرعونَ أشدَّ العذاب؛ ففي هذا إثباتُ عذابِ القبرِ وتصاعدِ العذاب؛ فاحذر عذابَ القبرِ والآخرة، واستعذ بالله منهما، فعذابُ آلِ فرعونَ يتصاعد من البرزخِ إلى أشدِّ العذابِ يومَ القيامة، فاعمل لتنجو من العذابين.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ القبرِ والآخرة، والاستعاذةُ بالله منهما."},"action":{"text":"تأمّل عاقبةَ آلِ فرعونَ في البرزخِ والآخرة: النارُ يُعرَضون عليها غدوًّا وعشيًّا، صباحًا ومساءً، في قبورهم وبرزخهم، تُعرَض عليهم أرواحهم؛ ويومَ تقوم الساعةُ يُقال: أدخلوا آلَ فرعونَ أشدَّ العذابِ وأعظمه «النار يعرضون عليها غدوا وعشيا ويوم تقوم الساعة أدخلوا آل فرعون أشد العذاب»؛ ففي هذا إثباتُ عذابِ القبرِ والبرزخ، وتصاعدِ العذابِ من البرزخِ إلى أشدِّ العذابِ يومَ القيامة؛ فهذه الآيةُ من أدلّةِ عذابِ القبر؛ فاحذر عذابَ القبرِ والبرزخ، وعذابَ الآخرةِ الأشدّ؛ واستعذ بالله منهما؛ فكان النبيُّ ﷺ يستعيذ من عذابِ القبرِ ومن عذابِ النار؛ اللهم إني أعوذ بك من عذابِ القبر ومن عذابِ جهنم؛ فاعمل لتنجو من العذابين: عذابِ القبرِ وعذابِ الآخرة؛ فإنّ عذابَ آلِ فرعونَ يتصاعد من عرضِ النارِ في البرزخِ إلى أشدِّ العذابِ يومَ القيامة؛ فبادر بالإيمانِ والعملِ الصالحِ والتوبةِ لتنجو من عذابِ القبرِ والآخرة؛ وأكثر من الاستعاذةِ بالله منهما؛ وثبّت نفسك بالإيمانِ والعملِ الصالحِ ليثبّتك الله عند السؤالِ في القبر؛ فمن نجا من عذابِ القبرِ فما بعده أيسر، ومن وقع فيه فما بعده أشدّ؛ فاستعدّ للقبرِ وما بعده بالتقوى والعمل."}}]},{"title":"تحاجُّ أهلِ النارِ وذلُّهم، ونصرُ الله رسلَه والمؤمنين","range":[47,52],"theme":"تخاصمُ أهلِ النارِ وطلبُ الضعفاءِ من المستكبرين أن يدفعوا عنهم العذاب، وطلبُهم من خزنةِ جهنمَ الدعاءَ بتخفيفِ يومٍ فيُبكَّتون بقيامِ الحجّةِ وأنّ دعاءهم في ضلال، ووعدُ الله بنصرِ رسلِه والمؤمنين في الدنيا ويومَ يقوم الأشهاد، وأنّ الظالمين لا ينفعهم اعتذارهم ولهم اللعنةُ وسوءُ الدار","verses":[{"n":47,"reflection":{"text":"«وإذ يتحاجون في النار فيقول الضعفاء للذين استكبروا إنا كنا لكم تبعا فهل أنتم مغنون عنا نصيبا من النار»، واذكر إذ يتخاصمون في النار، فيقول الأتباعُ الضعفاءُ للمستكبرين: إنا كنا لكم أتباعًا، فهل تدفعون عنّا نصيبًا من النار؟ ففي هذا تخاصمُ أهلِ النارِ وتبرّؤُ المتبوعين؛ فاحذر أن تتّبع المستكبرين في الباطل فيتبرّؤوا منك، ولا تتّبع أحدًا في معصيةِ الله، فالتبعيةُ في الباطلِ لا تنفع يومَ القيامة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من التبعيةِ في الباطل، فالمتبوعون يتبرّؤون في النار."},"action":{"text":"تأمّل مشهدَ تخاصمِ أهلِ النار: واذكر إذ يتحاجّون ويتخاصمون في النار، فيقول الأتباعُ الضعفاءُ للذين استكبروا وأضلّوهم: إنا كنا لكم في الدنيا أتباعًا نطيعكم، فهل أنتم اليومَ دافعون عنّا ومغنون عنّا نصيبًا وجزءًا من النار؟ «وإذ يتحاجون في النار فيقول الضعفاء للذين استكبروا إنا كنا لكم تبعا فهل أنتم مغنون عنا نصيبا من النار»؛ ففي هذا تخاصمُ أهلِ النار، وطلبُ الأتباعِ من المتبوعين أن يدفعوا عنهم بعضَ العذاب؛ فاحذر أن تتّبع المستكبرين وأئمّةَ الضلالِ في الباطل، فيتبرّؤوا منك يومَ القيامةِ ولا يغنوا عنك شيئًا؛ إذ تبرّأ الذين اتُّبِعوا من الذين اتّبعوا ورأوا العذاب؛ فلا تتّبع أحدًا في معصيةِ الله؛ لا طاعةَ لمخلوقٍ في معصيةِ الخالق؛ فالتبعيةُ في الباطلِ لا تنفع يومَ القيامة، بل تضرّ؛ فينقلب الأخلّاءُ يومئذٍ بعضهم لبعضٍ عدوًّا إلا المتّقين؛ فاتّبع الحقَّ وحده، ولا تقلّد أحدًا على الباطل؛ فمن اتّبع الحقَّ نجا، ومن اتّبع المستكبرين في الباطلِ هلك معهم؛ فتبرّأ من الباطلِ وأهله في الدنيا، قبل أن يتبرّؤوا منك في الآخرة."}},{"n":48,"reflection":{"text":"«قال الذين استكبروا إنا كل فيها إن الله قد حكم بين العباد»: قال المستكبرون: إنا جميعًا في النار، إنّ الله قد حكم بين العبادِ فلا مردَّ لحكمه؛ ففي هذا يأسُ أهلِ النارِ وتقريرُ نفوذِ حكمِ الله؛ فاعلم أنّ حكمَ الله نافذٌ لا يُردّ، فبادر بالعملِ قبل أن يُحكَم عليك، فيومَ القيامةِ لا يغني أحدٌ عن أحد، فاعمل لنفسك قبل نفوذِ الحكم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ نفوذِ حكمِ الله، والعملُ قبل صدورِ الحكمِ يومَ القيامة."},"action":{"text":"تأمّل ردَّ المستكبرين على أتباعهم في النار: قالوا يائسين: إنا كلُّنا، أتباعًا ومتبوعين، في النار، لا يقدر أحدٌ منّا أن يدفع عن الآخرِ شيئًا؛ إنّ الله قد حكم بين العبادِ حكمًا نافذًا، فلكلٍّ نصيبه من العذاب، لا مردَّ لحكمه «قال الذين استكبروا إنا كل فيها إن الله قد حكم بين العباد»؛ ففي هذا يأسُ أهلِ النارِ من التخفيف، وتقريرُ نفوذِ حكمِ الله وعدلِه؛ فاعلم أنّ حكمَ الله نافذٌ لا يُردّ ولا يُبدَّل؛ فإذا حكم الله بين العبادِ يومَ القيامةِ فلا معقّبَ لحكمه؛ فبادر بالعملِ الصالحِ والتوبةِ قبل أن يُحكَم عليك ويُقضى في أمرك؛ فيومَ القيامةِ لا يغني أحدٌ عن أحدٍ شيئًا؛ لا تملك نفسٌ لنفسٍ شيئًا والأمرُ يومئذٍ لله؛ فاعمل لنفسك في الدنيا قبل نفوذِ الحكمِ في الآخرة؛ فلن ينفعك أحدٌ يومئذٍ، ولن تدفع عنك تبعيّةٌ ولا نسبٌ ولا مال؛ فقدّم لنفسك عملًا صالحًا ينجّيك؛ فمن قدّم لنفسه نجا، ومن فرّط ندم حين لا ينفع الندم؛ فاستعدّ ليومٍ يُحكَم فيه بين العبادِ بالعدل، ولا يُغني فيه أحدٌ عن أحد."}},{"n":49,"reflection":{"text":"«وقال الذين في النار لخزنة جهنم ادعوا ربكم يخفف عنا يوما من العذاب»، وقال أهلُ النارِ لخزنتها: ادعوا ربّكم يخفّف عنّا يومًا واحدًا من العذاب؛ ففي هذا ذلُّ أهلِ النارِ وطلبهم التخفيفَ ولو يومًا؛ فاحذر أن تصير إلى حالٍ تسأل فيه تخفيفَ يومٍ واحد، فاعمل الآن لتنجو، فالعذابُ في الآخرةِ لا تخفيفَ فيه، فبادر بالطاعةِ قبل فواتِ الأوان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابٍ لا تخفيفَ فيه، والمبادرةُ بالعملِ للنجاة."},"action":{"text":"تأمّل ذلَّ أهلِ النارِ وشدّةَ حالهم: وقال الذين في النار لخزنةِ جهنمَ من الملائكةِ الموكّلين بها: ادعوا ربّكم أن يخفّف عنّا يومًا واحدًا من العذاب، لا رفعه بالكلّية، بل تخفيفه يومًا واحدًا؛ فبلغ بهم العذابُ أن يسألوا تخفيفَ يومٍ فقط «وقال الذين في النار لخزنة جهنم ادعوا ربكم يخفف عنا يوما من العذاب»؛ ففي هذا بيانُ ذلِّ أهلِ النارِ وشدّةِ عذابهم، حتى يسألوا تخفيفَ يومٍ واحد، ولا يجرؤون أن يسألوا الرفع؛ فاحذر أن تصير إلى حالٍ تسأل فيه تخفيفَ يومٍ واحدٍ من العذابِ فلا تُجاب؛ فاعمل الآن في زمنِ المهلةِ لتنجو من ذلك العذاب؛ فالعذابُ في الآخرةِ لا تخفيفَ فيه ولا انقطاع؛ لا يُفتَّر عنهم وهم فيه مبلسون؛ كلّما خبت زدناهم سعيرًا؛ فبادر بالإيمانِ والطاعةِ والتوبةِ قبل فواتِ الأوان؛ فمن عمل في الدنيا نجا من عذابِ الآخرة؛ ومن فرّط صار إلى عذابٍ لا تخفيفَ فيه ولا مهرب؛ فاجعل من هذا المشهدِ المؤلمِ حافزًا للعملِ والتوبةِ قبل أن يأتيَ يومٌ لا ينفع فيه سؤالُ التخفيف."}},{"n":50,"reflection":{"text":"«قالوا أولم تك تأتيكم رسلكم بالبينات قالوا بلى قالوا فادعوا وما دعاء الكافرين إلا في ضلال»: قالت الخزنة: أولم تأتكم رسلكم بالبيّنات؟ قالوا: بلى، قالوا: فادعوا أنتم، وما دعاءُ الكافرين إلا في ضياعٍ وبطلان؛ ففي هذا تبكيتُ أهلِ النارِ وأنّ دعاءهم لا يُقبَل؛ فاعلم أنّ الحجّةَ قامت على الكافرين بالرسل، وأنّ دعاءهم في الآخرةِ لا ينفع، فاغتنم إجابةَ الدعاءِ في الدنيا، واتّبع الرسلَ قبل فواتِ الأوان.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"اغتنامُ إجابةِ الدعاءِ في الدنيا، واتّباعُ الرسلِ قبل فواتِ الأوان."},"action":{"text":"تأمّل تبكيتَ خزنةِ النارِ لأهلها: قالت الخزنةُ للكافرين لمّا طلبوا الدعاءَ لهم: أولم تكن تأتيكم رسلكم في الدنيا بالبيّناتِ والحججِ الواضحةِ فتعرضوا عنها؟ قالوا: بلى قد جاؤونا؛ قالت الخزنةُ: فادعوا أنتم إذًا، فلسنا نشفع لكم؛ وما دعاءُ الكافرين إلا في ضلالٍ وضياعٍ لا يُقبَل ولا ينفع «قالوا أولم تك تأتيكم رسلكم بالبينات قالوا بلى قالوا فادعوا وما دعاء الكافرين إلا في ضلال»؛ ففي هذا تبكيتُ أهلِ النارِ وتقريرُ قيامِ الحجّةِ عليهم، وأنّ دعاءهم في الآخرةِ لا يُقبَل؛ فاعلم أنّ الحجّةَ قد قامت على الكافرين بإرسالِ الرسلِ بالبيّنات؛ فما عُذّبوا إلا بعد قيامِ الحجّة؛ وأنّ دعاءهم في الآخرةِ ضائعٌ لا يُستجاب؛ فاغتنم أنت إجابةَ الدعاءِ في الدنيا، حيث بابُ الدعاءِ مفتوحٌ والإجابةُ مرجوّة؛ ادعوني أستجب لكم؛ واتّبع الرسلَ وما جاؤوا به من البيّناتِ قبل فواتِ الأوان؛ فمن اتّبع الرسلَ في الدنيا واغتنم الدعاءَ نجا، ومن أعرض عنهم صار دعاؤه في الآخرةِ ضلالًا؛ فبادر بالإيمانِ والدعاءِ والاتّباعِ في زمنِ القبول."}},{"n":51,"reflection":{"text":"«إنا لننصر رسلنا والذين آمنوا في الحياة الدنيا ويوم يقوم الأشهاد»: إنا لننصر رسلنا والمؤمنين في الحياةِ الدنيا ويومَ يقوم الشهداء (يومَ القيامة)؛ ففي هذا وعدُ الله بنصرِ رسلِه والمؤمنين؛ فأبشر بنصرِ الله لك إن كنت من المؤمنين المتّبعين للرسل، فاثبت على الحقِّ وانصر دينَ الله، فوعدُ الله بالنصرِ حقٌّ في الدنيا والآخرة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بنصرِ الله لرسلِه والمؤمنين في الدنيا والآخرة."},"action":{"text":"تأمّل وعدَ الله العظيمَ بنصرِ أوليائه: إنا لننصر رسلنا والذين آمنوا معهم في الحياةِ الدنيا بالحجّةِ والتأييدِ والغلبةِ في عاقبةِ الأمر، ويومَ يقوم الأشهادُ، يومَ القيامةِ حين يشهد الأنبياءُ والملائكةُ والمؤمنون، بإعلاءِ درجاتهم ونصرهم على من ظلمهم «إنا لننصر رسلنا والذين آمنوا في الحياة الدنيا ويوم يقوم الأشهاد»؛ ففي هذا وعدُ الله المؤكّدُ بنصرِ رسلِه والمؤمنين في الدارين؛ فأبشر بنصرِ الله لك إن كنت من المؤمنين الصادقين المتّبعين للرسل؛ فالنصرُ حليفُ أهلِ الإيمانِ والحقّ؛ والعاقبةُ لهم في الدنيا والآخرة؛ فاثبت على الحقِّ وانصر دينَ الله؛ فمن نصر الله نصره؛ ولو تأخّر النصرُ في الدنيا لحكمةٍ فهو آتٍ، والعاقبةُ للمتّقين؛ ونصرُ الآخرةِ محقّقٌ لا يتخلّف؛ فوعدُ الله بالنصرِ حقٌّ لا يُخلَف؛ فاجتهد في أسبابِ النصرِ من الإيمانِ والتقوى والصبرِ والإعداد؛ ثم ثق بوعدِ الله؛ فاثبت واصبر وانصر الحقّ؛ فإنّ الله ناصرك في الدنيا ويومَ يقوم الأشهاد؛ فالنصرُ من عند الله لأوليائه المؤمنين."}},{"n":52,"reflection":{"text":"«يوم لا ينفع الظالمين معذرتهم ولهم اللعنة ولهم سوء الدار»: يومَ لا ينفع الظالمين اعتذارهم، ولهم الطردُ من الرحمة، ولهم سوءُ الدارِ (النار)؛ ففي هذا أنّ الاعتذارَ في الآخرةِ لا ينفع الظالمين؛ فاحذر الظلمَ الذي لا ينفع معه اعتذارٌ يومَ القيامة، فقدّم التوبةَ والاعتذارَ في الدنيا حيث ينفع، فالاعتذارُ يومئذٍ لا يدفع اللعنةَ وسوءَ الدار.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"تقديمُ التوبةِ في الدنيا، فاعتذارُ الظالمين في الآخرةِ لا ينفع."},"action":{"text":"تأمّل عاقبةَ الظالمين يومَ يقوم الأشهاد: يومَ لا ينفع الظالمين اعتذارهم عمّا فعلوا، فلا تُقبَل معذرتهم؛ ولهم اللعنةُ والطردُ من رحمةِ الله؛ ولهم سوءُ الدارِ ومنتهاها، وهي جهنم «يوم لا ينفع الظالمين معذرتهم ولهم اللعنة ولهم سوء الدار»؛ ففي هذا أنّ الاعتذارَ يومَ القيامةِ لا ينفع الظالمين؛ فيومئذٍ لا يُؤذَن لهم فيعتذرون؛ ولا يُقبَل منهم عدلٌ ولا اعتذار؛ فاحذر الظلمَ، ظلمَ النفسِ بالكفرِ والمعاصي، وظلمَ الغيرِ بالتعدّي، الذي لا ينفع معه اعتذارٌ يومَ القيامة؛ فقدّم التوبةَ والاعتذارَ إلى الله في الدنيا حيث ينفعان ويُقبَلان؛ فالتوبةُ في الدنيا مقبولة، والاعتذارُ في الآخرةِ لا ينفع؛ فبادر بالتوبةِ من الظلمِ والمعاصي؛ وردَّ المظالمَ إلى أهلها، واستحلّهم؛ فمن اعتذر وتاب في الدنيا نفعه، ومن أخّر حتى الآخرةِ لم ينفعه اعتذاره؛ فاجتنب الظلمَ الذي عاقبتُه اللعنةُ وسوءُ الدار؛ واعمل عملَ من يخشى يومًا لا ينفع فيه اعتذار؛ فالسلامةُ في التقوى واجتنابِ الظلمِ والتوبةِ في الدنيا."}}]},{"title":"إيتاءُ موسى الهدى، والأمرُ بالصبرِ والاستغفارِ والتسبيح، والاستعاذةُ من الكِبر","range":[53,56],"theme":"إيتاءُ موسى الهدى وإيراثُ بني إسرائيلَ الكتابَ هدًى وذكرى لأولي الألباب، والأمرُ للنبيِّ بالصبرِ لأنّ وعدَ الله حقٌّ والاستغفارِ لذنبه والتسبيحِ بالعشيِّ والإبكار، وأنّ باعثَ المجادلين في آياتِ الله الكِبرُ الذي لا يبلغونه فأُمِر بالاستعاذةِ بالله السميعِ البصير","verses":[{"n":53,"reflection":{"text":"«ولقد آتينا موسى الهدى وأورثنا بني إسرائيل الكتاب»، ولقد آتينا موسى الهدى (النبوّةَ والشريعة) وأورثنا بني إسرائيلَ الكتابَ (التوراة)؛ ففي هذا نعمةُ الهدى والكتابِ على موسى وقومه؛ فاعلم أنّ الهدى والكتابَ نعمةٌ عظيمة، فاشكر نعمةَ الهدى والقرآنِ الذي أُنزِل إليك، واهتدِ به، فمن أُوتِي الهدى والكتابَ فليشكر بالعملِ به.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الهدى والكتاب، والاهتداءُ به والعملُ بمقتضاه."},"action":{"text":"تأمّل نعمةَ الله على موسى وقومه: ولقد آتينا موسى الهدى، النبوّةَ والشريعةَ والبيان، وأورثنا بني إسرائيلَ الكتابَ وهو التوراة، ينتفعون به ويتوارثونه «ولقد آتينا موسى الهدى وأورثنا بني إسرائيل الكتاب»؛ ففي هذا بيانُ نعمةِ الهدى والكتابِ على موسى وقومه؛ فاعلم أنّ الهدى والكتابَ من أعظمِ نعمِ الله؛ فبهما يُعرَف الحقُّ من الباطل، والهدى من الضلال؛ فاشكر نعمةَ الهدى والكتاب الذي أنعم الله بها عليك، وهو القرآنُ أعظمُ الكتب؛ واهتدِ به، واعمل بمقتضاه؛ فمن أُوتِي الهدى والكتابَ فليشكر النعمةَ بالعملِ به والاهتداءِ بهديه؛ فالكتابُ نعمةٌ تُشكَر بالتلاوةِ والتدبّرِ والعملِ والتحكيم؛ فلا تكفر نعمةَ الكتابِ بالإعراضِ عنه؛ بل اشكرها بالإقبالِ عليه والاهتداءِ به؛ فمن اهتدى بكتابِ الله فقد شكر النعمة، ومن أعرض عنه فقد كفرها؛ فاجعل القرآنَ إمامك وهديك؛ واشكر نعمةَ الله عليك بإنزاله بالعملِ به؛ فبالاهتداءِ بالكتابِ تُشكَر نعمةُ الهدى."}},{"n":54,"reflection":{"text":"«هدى وذكرى لأولي الألباب»: الكتابُ هدًى إلى الحقِّ وتذكرةٌ لأصحابِ العقولِ السليمة؛ ففي هذا بيانُ أنّ الانتفاعَ بالكتابِ لأولي الألباب؛ فكن من أولي الألبابِ الذين يهتدون بالكتابِ ويتذكّرون به، فالكتابُ هدًى وذكرى لمن عقل، فأعمل عقلك في الاهتداءِ بالكتابِ والتذكّرِ به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاهتداءُ بالكتابِ والتذكّرُ به، فذلك دأبُ أولي الألباب."},"action":{"text":"تأمّل وصفَ الكتابِ بأنه هدًى وذكرى: كان الكتابُ الذي أورثه الله بني إسرائيلَ هدًى يهديهم إلى الحقِّ والصراطِ المستقيم، وذكرى وتذكرةً لأولي الألبابِ أصحابِ العقولِ السليمةِ الذين ينتفعون به «هدى وذكرى لأولي الألباب»؛ ففي هذا بيانُ أنّ الكتابَ هدًى وتذكرة، وأنّ المنتفعين به هم أولو الألباب؛ فالكتابُ معروضٌ للجميع، لكن لا يهتدي به ويتذكّر إلا أصحابُ العقولِ الراجحة؛ فكن من أولي الألبابِ الذين يهتدون بكتابِ الله ويتذكّرون به؛ فأعمل عقلك في الاهتداءِ بالكتابِ والتذكّرِ به والعملِ بمقتضاه؛ إنما يتذكّر أولو الألباب؛ فالعاقلُ من انتفع بالكتابِ فاهتدى به وتذكّر؛ والأحمقُ من أعرض عنه فلم ينتفع به؛ فاجعل قلبك وعقلك متذكّرًا متدبّرًا بكتابِ الله؛ وتذكّر بمواعظه، واهتدِ بهداياته؛ فمن كان من أولي الألبابِ اهتدى بالكتابِ وتذكّر؛ فكن منهم؛ فبإعمالِ العقلِ في كتابِ الله تُنال الهدايةُ والذكرى."}},{"n":55,"reflection":{"text":"«فاصبر إن وعد الله حق واستغفر لذنبك وسبح بحمد ربك بالعشي والإبكار»: فاصبر يا محمدُ إنّ وعدَ الله بنصرك حقٌّ، واستغفر لذنبك، وسبّح بحمدِ ربّك مساءً وصباحًا؛ ففي هذا الأمرُ بالصبرِ والاستغفارِ والتسبيح؛ فاصبر على ما أصابك واثق بوعدِ الله، وأكثر من الاستغفارِ والتسبيحِ في طرفيِ النهار، فالصبرُ والاستغفارُ والتسبيحُ زادُ المؤمنِ في طريقه.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ والثقةُ بوعدِ الله، والإكثارُ من الاستغفارِ والتسبيح."},"action":{"text":"تأمّل الوصايا الجامعةَ للنبيِّ ﷺ ولكلِّ مؤمن: فاصبر يا محمدُ على أذى المكذّبين وعلى تكاليفِ الدعوة، إنّ وعدَ الله بنصرك وإظهارِ دينك حقٌّ لا يتخلّف؛ واستغفر لذنبك تواضعًا وعبوديةً؛ وسبّح بحمدِ ربّك ونزّهه في العشيِّ، آخرِ النهار، والإبكارِ، أوّله «فاصبر إن وعد الله حق واستغفر لذنبك وسبح بحمد ربك بالعشي والإبكار»؛ ففي هذا الأمرُ بثلاثِ وصايا: الصبرِ، والاستغفارِ، والتسبيح؛ فاصبر على ما أصابك من الأذى والابتلاء، واثقًا بوعدِ الله؛ فالصبرُ مفتاحُ الفرج، وعاقبتُه حميدة؛ وأكثر من الاستغفارِ لذنوبك؛ فالاستغفارُ يمحو الذنوبَ ويجلب الرحمة؛ وأكثر من تسبيحِ الله وتحميده في طرفيِ النهار: صباحًا ومساءً؛ فسبّح بحمدِ ربك قبل طلوعِ الشمسِ وقبل الغروب؛ فالتسبيحُ عبادةٌ عظيمة، وذكرُ الله حياةُ القلوب؛ فاجعل هذه الثلاثَ زادك: الصبرَ على البلاءِ والطاعة، والاستغفارَ من الذنوب، والتسبيحَ والذكرَ في الصباحِ والمساء؛ فبالصبرِ والاستغفارِ والتسبيحِ يستقيم سيرُ المؤمنِ إلى ربه؛ فمن صبر واستغفر وسبّح فاز بمعيّةِ الله ونصره ومغفرته."}},{"n":56,"reflection":{"text":"«إن الذين يجادلون في آيات الله بغير سلطان أتاهم إن في صدورهم إلا كبر ما هم ببالغيه فاستعذ بالله إنه هو السميع البصير»: إنّ الذين يجادلون في آياتِ الله بلا حجّةٍ ما في صدورهم إلا كِبرٌ لن يبلغوا مرادهم منه، فاستعذ بالله، إنه السميعُ البصير؛ ففي هذا أنّ باعثَ الجدالِ الكِبر، والأمرُ بالاستعاذة؛ فاحذر الكِبرَ الباعثَ على ردِّ الحق، واستعذ بالله من كيدِ المستكبرين، فالله يكفيك السميعُ البصيرُ لكلِّ شيء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكِبرِ الباعثِ على ردِّ الحق، والاستعاذةُ بالله."},"action":{"text":"تأمّل بيانَ الله لباعثِ المجادلين بالباطل: إنّ الذين يجادلون في آياتِ الله لدفعها وردِّها بغيرِ حجّةٍ ولا برهانٍ أتاهم من الله، ما في صدورهم إلا كِبرٌ وطلبٌ للعلوِّ والرياسة، لن يبلغوا مرادهم منه، فسيخزيهم الله؛ فاستعذ بالله من شرّهم ومن كِبرهم، إنه هو السميعُ لأقوالهم، البصيرُ بأحوالهم «إن الذين يجادلون في آيات الله بغير سلطان أتاهم إن في صدورهم إلا كبر ما هم ببالغيه فاستعذ بالله إنه هو السميع البصير»؛ ففي هذا أنّ باعثَ الجدالِ في آياتِ الله بالباطلِ هو الكِبرُ وطلبُ العلوّ؛ فاحذر الكِبرَ الذي يحمل على ردِّ الحقِّ والجدالِ فيه بالباطل؛ فما جادل أحدٌ في الحقِّ بالباطلِ إلا كِبرًا وطلبًا للعلو؛ فطهّر قلبك من الكِبر؛ واقبل الحقَّ بتواضعٍ وانقياد؛ واستعذ بالله من شرِّ المستكبرين المجادلين ومن كيدهم؛ فمن استعاذ بالله أعاذه؛ فالله كافيك وحافظك، وهو السميعُ البصيرُ الذي لا يخفى عليه شيء؛ فالجأ إليه، واستعذ به، وتوكّل عليه؛ فهو يكفيك شرَّ أهلِ الكِبرِ والباطل؛ فاجعل استعاذتك بالله عند مواجهةِ أهلِ الجدالِ والكِبر؛ فالله يعصمك ويكفيك."}}]},{"title":"عظمةُ الخلق، والموازنةُ بين الأعمى والبصير، وآيةُ ادعوني أستجب لكم، وتوحيدُ الخالق","range":[57,68],"theme":"أنّ خلقَ السماواتِ والأرضِ أكبرُ من خلقِ الناسِ دليلًا على البعث، وأنّ الأعمى والبصيرَ والمؤمنَ المحسنَ والمسيءَ لا يستوون، وأنّ الساعةَ آتيةٌ لا ريب، وآيةُ «ادعوني أستجب لكم» ووعيدُ المستكبرين عن الدعاء، وتعدادُ نعمِ الليلِ والنهارِ والأرضِ والسماءِ وحسنِ الصورةِ والطيّبات، وأنه الحيُّ فادعوه مخلصين، ونهيُ النبيِّ عن عبادةِ غيرِ الله، وخلقُ الإنسانِ أطوارًا، وأنه يحيي ويميت وأمره كن فيكون","verses":[{"n":57,"reflection":{"text":"«لخلق السماوات والأرض أكبر من خلق الناس ولكن أكثر الناس لا يعلمون»: لخلقُ السماواتِ والأرضِ أعظمُ من خلقِ الناس، ولكنّ أكثرَ الناسِ لا يعلمون؛ ففي هذا الاستدلالُ على البعثِ بعظمةِ خلقِ السماوات؛ فاعلم أنّ من خلق السماواتِ والأرضَ العظيمةَ قادرٌ على بعثك أهونَ منها، فأيقن بالبعث، ولا تستبعده، فمن خلق الأعظمَ يقدر على إعادةِ الأدنى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بالبعثِ استدلالًا بعظمةِ خلقِ السماواتِ والأرض."},"action":{"text":"تأمّل الاستدلالَ على قدرةِ الله والبعث: لخلقُ السماواتِ والأرضِ، على عظمها وسعتها وإحكامها، أكبرُ وأعظمُ من خلقِ الناسِ وبعثهم، ولكنّ أكثرَ الناسِ لا يعلمون هذه الحقيقةَ فيستبعدون البعث «لخلق السماوات والأرض أكبر من خلق الناس ولكن أكثر الناس لا يعلمون»؛ ففي هذا الاستدلالُ على قدرةِ الله على البعثِ بعظمةِ خلقِ السماواتِ والأرض؛ فاعلم أنّ من خلق السماواتِ والأرضَ العظيمتين قادرٌ على أن يبعثك بعد موتك، بل بعثك أهونُ من خلقهما؛ أوليس الذي خلق السماواتِ والأرضَ بقادرٍ على أن يخلق مثلهم؟ بلى؛ فأيقن بالبعثِ ولا تستبعده؛ فمن قدر على خلقِ الأعظمِ فهو على خلقِ الأدنى أقدر؛ لخلقُ السماواتِ والأرضِ أكبرُ من خلقِ الناس؛ فتأمّل في عظمةِ خلقِ السماواتِ والأرض، لتزداد يقينًا بقدرةِ الله على البعث؛ فمن تفكّر في خلقِ الله العظيمِ أيقن بقدرته على كلِّ شيء؛ فلا تكن من الغافلين الذين لا يعلمون فيستبعدون البعث؛ بل كن من الموقنين الذين يستدلّون بعظيمِ الخلقِ على قدرةِ الخالقِ على البعثِ والإعادة؛ فاستعدّ للبعثِ الذي هو حقٌّ لا ريبَ فيه."}},{"n":58,"reflection":{"text":"«وما يستوي الأعمى والبصير والذين آمنوا وعملوا الصالحات ولا المسيء قليلا ما تتذكرون»، وما يستوي الأعمى والبصير، ولا المؤمنون العاملون الصالحاتِ والمسيء، قليلًا ما تتذكّرون؛ ففي هذا الموازنةُ بين المؤمنِ والكافرِ والمحسنِ والمسيء؛ فاعلم أنّ المؤمنَ المحسنَ لا يستوي مع الكافرِ المسيء، فكن من المؤمنين المحسنين، فالتفاوتُ بين الفريقين عظيمٌ كالتفاوتِ بين الأعمى والبصير.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"إدراكُ التفاوتِ بين المؤمنِ المحسنِ والكافرِ المسيء، وطلبُ الإحسان."},"action":{"text":"تأمّل الموازناتِ التي ضربها الله: وما يستوي الأعمى الذي لا يبصر والبصيرُ الذي يبصر، فكذلك لا يستوي الكافرُ الأعمى عن الحقِّ والمؤمنُ البصيرُ به؛ ولا يستوي الذين آمنوا وعملوا الصالحاتِ والمسيءُ بالكفرِ والمعاصي؛ قليلًا ما تتذكّرون وتتّعظون بهذه الفروقِ الواضحة «وما يستوي الأعمى والبصير والذين آمنوا وعملوا الصالحات ولا المسيء قليلا ما تتذكرون»؛ ففي هذا الموازنةُ بين المؤمنِ والكافر، والمحسنِ والمسيء؛ فكما لا يستوي الأعمى والبصيرُ في الحسّ، لا يستوي المؤمنُ المحسنُ والكافرُ المسيءُ في المآلِ والجزاء؛ فاعلم أنّ المؤمنَ المحسنَ لا يستوي أبدًا مع الكافرِ المسيء؛ فبينهما بونٌ شاسعٌ في الدنيا والآخرة؛ فكن من المؤمنين العاملين الصالحاتِ المبصرين بنورِ الإيمان؛ ولا تكن من المسيئين العُميِ عن الحق؛ فالتفاوتُ بين الفريقين عظيمٌ كالتفاوتِ بين الأعمى والبصير؛ أفمن كان مؤمنًا كمن كان فاسقًا لا يستوون؛ فاختر لنفسك أن تكون من المؤمنين المحسنين البصراء؛ واعمل الصالحاتِ مع الإيمان؛ فبالإيمانِ والعملِ الصالحِ تكون من البصراءِ الفائزين، لا من العُميِ الخاسرين؛ فتذكّر واتّعظ، ولا تكن من الغافلين."}},{"n":59,"reflection":{"text":"«إن الساعة لآتية لا ريب فيها ولكن أكثر الناس لا يؤمنون»: إنّ الساعةَ آتيةٌ لا شكَّ فيها، ولكنّ أكثرَ الناسِ لا يؤمنون؛ ففي هذا تقريرُ إتيانِ الساعةِ وذمُّ عدمِ الإيمانِ بها؛ فأيقن بإتيانِ الساعةِ واستعدّ لها، فالساعةُ آتيةٌ لا محالة، فلا تكن من الغافلين الذين لا يؤمنون بها، بل اعمل لها عملَ الموقنين.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"اليقينُ بإتيانِ الساعةِ والاستعدادُ لها، وتركُ الغفلة."},"action":{"text":"تأمّل تقريرَ الله لإتيانِ الساعة: إنّ الساعةَ، القيامةَ، لآتيةٌ لا ريبَ فيها ولا شك، ولكنّ أكثرَ الناسِ لا يؤمنون بها إيمانًا يحملهم على الاستعدادِ لها «إن الساعة لآتية لا ريب فيها ولكن أكثر الناس لا يؤمنون»؛ ففي هذا تقريرُ إتيانِ الساعةِ يقينًا، وذمُّ من لا يؤمن بها أو يؤمن إيمانًا ضعيفًا لا يستعدّ له؛ فأيقن بإتيانِ الساعةِ يقينًا جازمًا؛ فهي آتيةٌ لا محالة، لا ريبَ فيها ولا شك؛ واستعدّ لها بالإيمانِ والعملِ الصالحِ والتوبة؛ فمن أيقن بالساعةِ استعدّ لها؛ فلا تكن من الغافلين الذين لا يؤمنون بها أو ينسونها؛ اقتربت الساعةُ وانشقّ القمر؛ اقترب للناسِ حسابهم وهم في غفلةٍ معرضون؛ فلا تكن من الغافلين المعرضين؛ بل اعمل للساعةِ عملَ الموقنين بإتيانها؛ فتصوّر أهوالها، واستعدّ لها؛ فمن آمن بالساعةِ حقًّا عمل لها؛ ومن غفل عنها فُوجِئ بها؛ فاجعل إيمانك بالساعةِ حافزًا للعملِ والاستعداد؛ فالساعةُ آتيةٌ قريبة، فاعمل لها قبل أن تفجأك."}},{"n":60,"reflection":{"text":"«وقال ربكم ادعوني أستجب لكم إن الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين»، وقال ربّكم: ادعوني أستجب لكم، إنّ الذين يستكبرون عن عبادتي (دعائي) سيدخلون جهنمَ صاغرين؛ ففي هذا الأمرُ بالدعاءِ ووعدُ الإجابة، وأنّ الدعاءَ عبادة؛ فادعُ الله واثقًا بالإجابة، وأكثر من دعائه، فالدعاءُ عبادةٌ يحبّها الله، ومن تكبّر عن الدعاءِ فقد استكبر عن العبادة، فألحّ في الدعاء.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإكثارُ من الدعاءِ والثقةُ بالإجابة، فالدعاءُ عبادةٌ يحبّها الله."},"action":{"text":"تأمّل هذه الآيةَ العظيمةَ في فضلِ الدعاء: وقال ربّكم ادعوني في حوائجكم كلِّها أستجب لكم؛ إنّ الذين يستكبرون عن عبادتي ودعائي سيدخلون جهنمَ صاغرين ذليلين «وقال ربكم ادعوني أستجب لكم إن الذين يستكبرون عن عبادتي سيدخلون جهنم داخرين»؛ ففي هذا الأمرُ بالدعاءِ ووعدُ الله بالإجابة، وبيانُ أنّ الدعاءَ عبادة، وأنّ تركه استكبار؛ فادعُ الله واثقًا بالإجابة؛ فقد وعد الله الداعيَ بالإجابة؛ ادعوني أستجب لكم؛ وإذا سألك عبادي عنّي فإني قريبٌ أجيب دعوةَ الداعِ إذا دعان؛ فأكثر من دعاءِ الله في كلِّ حوائجك، صغيرها وكبيرها؛ فالدعاءُ مخّ العبادة؛ الدعاءُ هو العبادة؛ فمن دعا الله فقد عبده، ومن ترك دعاءه فقد استكبر عن عبادته؛ ومن استكبر عن دعاءِ الله وعبادته دخل جهنمَ ذليلًا؛ فلا تستكبر عن الدعاء؛ وألحّ على الله في دعائك؛ ولا تستبطئ الإجابة؛ فإنّ الله يحبّ الملحّين في الدعاء؛ فادعه رغبةً ورهبة؛ فاجعل الدعاءَ دأبك في كلِّ أحوالك؛ فبالدعاءِ تُقضى الحوائج، وتُدفَع البلايا، ويُنال رضا الله؛ فمن لزم الدعاءَ فتح الله له أبوابَ الإجابةِ والرحمة."}},{"n":61,"reflection":{"text":"«الله الذي جعل لكم الليل لتسكنوا فيه والنهار مبصرا إن الله لذو فضل على الناس ولكن أكثر الناس لا يشكرون»: الله الذي جعل لكم الليلَ لتسكنوا فيه وتستريحوا، والنهارَ مضيئًا لتبتغوا فضله، إنّ الله لذو فضلٍ على الناس، ولكنّ أكثرهم لا يشكرون؛ ففي هذا تعدادُ نعمِ الليلِ والنهارِ وذمُّ عدمِ الشكر؛ فاشكر الله على نعمةِ الليلِ للسكونِ والنهارِ للمعاش، فمن تأمّل نعمَ الله شكرها، فكن من الشاكرين القليلين، لا من الغافلين الكافرين للنعمة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمِ الله في الليلِ والنهار، والكونُ من الشاكرين القليلين."},"action":{"text":"تأمّل نعمةَ الله في الليلِ والنهار: الله الذي جعل لكم الليلَ مظلمًا ساكنًا لتسكنوا فيه وتستريحوا من عناءِ النهار، وجعل النهارَ مبصرًا مضيئًا لتبتغوا فيه من فضلِ الله وتسعوا لمعاشكم؛ إنّ الله لذو فضلٍ عظيمٍ على الناسِ بهذه النعمِ وغيرها، ولكنّ أكثرَ الناسِ لا يشكرون هذا الفضلَ والإنعام «الله الذي جعل لكم الليل لتسكنوا فيه والنهار مبصرا إن الله لذو فضل على الناس ولكن أكثر الناس لا يشكرون»؛ ففي هذا تعدادُ نعمِ الله في تعاقبِ الليلِ والنهار، وذمُّ من لا يشكر؛ فاشكر الله على نعمةِ الليلِ الذي تسكن فيه وتنام وتستريح، ونعمةِ النهارِ الذي تبصر فيه وتسعى لرزقك؛ فمن تأمّل نعمَ الله عليه، في الليلِ والنهار، والأمنِ والصحّةِ والرزق، شكرها؛ وقليلٌ من عبادي الشكور؛ فكن من الشاكرين القليلين، لا من الغافلين الكافرين للنعمة؛ فالشكرُ قيدُ النعمِ وسببُ المزيد؛ ولئن شكرتم لأزيدنّكم؛ فاعمر قلبك ولسانك وجوارحك بشكرِ الله على نعمه المتوالية؛ فمن شكر النعمةَ حفظها وزادها الله، ومن كفرها عرّضها للزوال؛ فاجعل الشكرَ دأبك في كلِّ نعمة."}},{"n":62,"reflection":{"text":"«ذلكم الله ربكم خالق كل شيء لا إله إلا هو فأنى تؤفكون»: ذلكم الله ربّكم خالقُ كلِّ شيء، لا إله إلا هو، فكيف تُصرَفون عن عبادته؟ ففي هذا تقريرُ التوحيدِ باستحقاقِ الخالقِ للعبادة؛ فوحّد الله خالقَ كلِّ شيء، ولا تُصرَف عن عبادته إلى غيره، فمن خلق كلَّ شيءٍ هو المستحقُّ للعبادةِ وحده، فأخلص له العبادة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله خالقِ كلِّ شيء، وعدمُ الانصرافِ عن عبادته."},"action":{"text":"تأمّل تقريرَ الله للتوحيدِ بعد ذكرِ نعمه: ذلكم الله ربّكم الذي أنعم عليكم بهذه النعم، خالقُ كلِّ شيءٍ لا خالقَ سواه، لا إله إلا هو وحده، فكيف تُصرَفون وتُقلَبون عن عبادته إلى عبادةِ غيره؟ «ذلكم الله ربكم خالق كل شيء لا إله إلا هو فأنى تؤفكون»؛ ففي هذا تقريرُ التوحيدِ بأنّ الخالقَ الرازقَ هو المستحقُّ للعبادة؛ فوحّد الله خالقَ كلِّ شيءٍ ومالكَه ومدبّره؛ فمن خلق كلَّ شيءٍ ورزق وأنعم فهو المستحقُّ للعبادةِ وحده؛ فكيف يُعبَد غيرُ الخالق؟ وكيف يُصرَف العبدُ عن عبادةِ ربه الخالقِ إلى عبادةِ مخلوقٍ عاجز؟ فلا تنصرف عن عبادةِ الله إلى عبادةِ سواه؛ وأخلص له العبادةَ وحده؛ فأفرده بالعبادةِ كما تفرّد بالخلقِ والرزقِ والإنعام؛ فمن أقرّ بأنّ الله خالقُ كلِّ شيءٍ لزمه أن يعبده وحده؛ فالخلقُ دليلُ استحقاقِ العبادة؛ فاعبد الخالقَ، لا المخلوق؛ ووحّد ربك خالقَ كلِّ شيء؛ فهو وحده المستحقُّ للعبادةِ لا إله إلا هو؛ فأخلص له عبادتك ودعاءك وتوكّلك؛ ولا تصرف شيئًا من ذلك لغيره."}},{"n":63,"reflection":{"text":"«كذلك يؤفك الذين كانوا بآيات الله يجحدون»: كذلك يُصرَف عن الحقِّ الذين كانوا بآياتِ الله يجحدون؛ ففي هذا أنّ جحودَ الآياتِ سببُ الانصرافِ عن الحق؛ فاحذر جحودَ آياتِ الله الذي يصرف عن الحق، فآمن بآياتِ الله وأقرّ بها، فمن جحد آياتِ الله صُرِف عن الحق، ومن آمن بها اهتدى.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بآياتِ الله والإقرارُ بها، والحذرُ من جحودها."},"action":{"text":"تأمّل بيانَ الله لسببِ الانصرافِ عن الحق: كذلك، كما صُرِف هؤلاء المشركون عن عبادةِ الله الخالق، يُؤفَك ويُصرَف عن الحقِّ والتوحيدِ كلُّ من كان بآياتِ الله يجحدها وينكرها بعد وضوحها «كذلك يؤفك الذين كانوا بآيات الله يجحدون»؛ ففي هذا أنّ جحودَ آياتِ الله وإنكارها سببُ الانصرافِ عن الحقِّ والحرمانِ من الهداية؛ فالجحودُ عقوبتُه الصرفُ عن الحق؛ فاحذر جحودَ آياتِ الله، القرآنيةِ والكونيةِ، وإنكارها بعد وضوحها؛ فإنّ الجحودَ يصرف صاحبه عن الحقِّ ويعميه عنه؛ سأصرف عن آياتي الذين يتكبّرون في الأرضِ بغيرِ الحق؛ فآمن بآياتِ الله وأقرّ بها وصدّق بها؛ وتأمّلها بعينِ الاعتبارِ والإيمان؛ فمن جحد آياتِ الله صُرِف عن الحقِّ وضلّ، ومن آمن بها اهتدى ورشد؛ فلا تكن من الجاحدين المنكرين لآياتِ الله؛ بل كن من المؤمنين المصدّقين المقرّين بها؛ فبالإيمانِ بآياتِ الله تُنال الهداية، وبجحودها يقع الصرفُ عن الحقِّ والضلال؛ فاجعل قلبك مؤمنًا بآياتِ الله، مقرًّا بها، منتفعًا بها."}},{"n":64,"reflection":{"text":"«الله الذي جعل لكم الأرض قرارا والسماء بناء وصوركم فأحسن صوركم ورزقكم من الطيبات ذلكم الله ربكم فتبارك الله رب العالمين»: الله الذي جعل لكم الأرضَ مستقرًّا والسماءَ بناءً، وصوّركم فأحسن صوركم، ورزقكم من الطيّبات، ذلكم الله ربّكم، فتبارك الله ربُّ العالمين؛ ففي هذا تعدادُ النعمِ الدالّةِ على التوحيد؛ فتأمّل نعمَ الله عليك في الأرضِ والسماءِ وحسنِ صورتك ورزقك، فاشكرها ووحّد المنعم، فمن أنعم عليك بهذه النعمِ يستحقّ العبادةَ والحمد.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في نعمِ الله وشكرُها، وتوحيدُ المنعمِ العظيم."},"action":{"text":"تأمّل نعمَ الله المتعدّدةَ الدالّةَ على توحيده: الله الذي جعل لكم الأرضَ قرارًا ومستقرًّا تعيشون عليها، والسماءَ بناءً محكمًا مرفوعًا فوقكم، وصوّركم في أرحامِ أمهاتكم فأحسن صوركم وأتقنها، ورزقكم من الطيّباتِ من المطاعمِ والمشارب؛ ذلكم الله ربّكم المتّصفُ بهذه النعمِ والأفعال، فتبارك الله وتعالى وكثر خيره، ربُّ العالمين وخالقهم ورازقهم «الله الذي جعل لكم الأرض قرارا والسماء بناء وصوركم فأحسن صوركم ورزقكم من الطيبات ذلكم الله ربكم فتبارك الله رب العالمين»؛ ففي هذا تعدادُ نعمِ الله العظيمةِ الدالّةِ على استحقاقه للعبادةِ وحده؛ فتأمّل نعمَ الله عليك: الأرضَ التي تستقرّ عليها، والسماءَ المبنيّةَ فوقك، وحسنَ صورتك وخلقك، والطيّباتِ التي رزقك؛ فمن أنعم عليك بهذه النعمِ يستحقّ العبادةَ والحمدَ والشكر؛ فاشكر الله على نعمه، ووحّده، وأخلص له العبادة؛ فتأمّل في خلقك وحسنِ صورتك؛ لقد خلقنا الإنسانَ في أحسنِ تقويم؛ فاحمد الله الذي أحسن صورتك ورزقك الطيّبات؛ فتبارك الله ربُّ العالمين؛ فمن تأمّل نعمَ الله شكرها ووحّد المنعمَ؛ فاجعل تأمّلك في نعمِ الله سبيلًا لشكره وتوحيده وحمده."}},{"n":65,"reflection":{"text":"«هو الحي لا إله إلا هو فادعوه مخلصين له الدين الحمد لله رب العالمين»: هو الحيُّ الذي لا يموت، لا إله إلا هو، فادعوه مخلصين له الدين، الحمد لله ربِّ العالمين؛ ففي هذا تقريرُ حياةِ الله الكاملةِ والأمرُ بإخلاصِ الدعاء؛ فادعُ الله الحيَّ القيّومَ مخلصًا له دينك، واحمده، فمن كان حيًّا لا يموت يستحقّ أن يُدعى ويُعبَد، فأخلص له الدعاءَ والعبادة.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"دعاءُ الله الحيِّ مخلصًا له الدين، وحمدُه وتوحيدُه."},"action":{"text":"تأمّل تقريرَ الله لحياته الكاملةِ وتوحيده: هو الحيُّ الذي له الحياةُ الكاملةُ الدائمةُ التي لا يعتريها موتٌ ولا نقص، لا إله إلا هو وحده، فادعوه مخلصين له الطاعةَ والدينَ والعبادة، الحمد لله ربِّ العالمين على نعمه وأفضاله «هو الحي لا إله إلا هو فادعوه مخلصين له الدين الحمد لله رب العالمين»؛ ففي هذا تقريرُ حياةِ الله الكاملةِ التي هي مبدأُ الكمالات، والأمرُ بإخلاصِ الدعاءِ والدينِ له؛ فادعُ الله الحيَّ القيّومَ الذي لا يموت؛ فمن كان حيًّا حياةً كاملةً لا تزول يستحقّ أن يُدعى ويُعبَد ويُتوكَّل عليه؛ ولا تدعُ الأمواتَ والمخلوقاتِ العاجزةَ التي تموت وتفنى؛ فأخلص لله الدعاءَ والعبادةَ والدين؛ فادعوه مخلصين له الدين؛ ولا تشرك به في دعائك ولا عبادتك أحدًا؛ فالدعاءُ عبادةٌ لا تُصرَف إلا لله الحيِّ القيّوم؛ واحمد الله ربَّ العالمين على نعمه؛ فاجعل دعاءك وعبادتك خالصةً لله الحيِّ الذي لا يموت؛ فمن دعا الله مخلصًا استجاب له؛ فأخلص لله دينك ودعاءك، واحمده وحده؛ فهو الحيُّ المستحقُّ للعبادةِ والحمدِ والدعاء."}},{"n":66,"reflection":{"text":"«قل إني نهيت أن أعبد الذين تدعون من دون الله لما جاءني البينات من ربي وأمرت أن أسلم لرب العالمين»: قل إني نُهِيتُ أن أعبد الذين تدعونهم من دونِ الله لمّا جاءتني البيّناتُ من ربي، وأُمِرت أن أستسلم لربِّ العالمين؛ ففي هذا نهيُ النبيِّ عن عبادةِ غيرِ الله وأمرُه بالاستسلامِ له؛ فانبذ عبادةَ كلِّ ما سوى الله، واستسلم لربِّ العالمين، فالتوحيدُ والاستسلامُ لله أمرُه ونهيه، فأخلص العبادةَ لله واستسلم لأمره.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"نبذُ عبادةِ ما سوى الله، والاستسلامُ لربِّ العالمين."},"action":{"text":"تأمّل ما أُمِر النبيُّ ﷺ أن يعلنه: قل إني نُهِيتُ من ربي أن أعبد الذين تدعونهم وتعبدونهم من دونِ الله من الأصنامِ والأوثان، لمّا جاءتني البيّناتُ والحججُ الواضحةُ من ربي على بطلانِ عبادتها؛ وأُمِرت أن أستسلم وأنقاد لربِّ العالمين وحده «قل إني نهيت أن أعبد الذين تدعون من دون الله لما جاءني البينات من ربي وأمرت أن أسلم لرب العالمين»؛ ففي هذا نهيُ النبيِّ عن عبادةِ غيرِ الله، وأمرُه بالاستسلامِ لله وحده؛ فانبذ عبادةَ كلِّ ما سوى الله من الأصنامِ والقبورِ والأولياءِ والهوى؛ فقد قامت البيّناتُ على بطلانِ عبادتها؛ واستسلم لربِّ العالمين وحده بالتوحيدِ والطاعةِ والانقياد؛ فالاستسلامُ لله، وهو الإسلامُ، أن تنقاد لأمره ونهيه بالطاعةِ والتسليم؛ فأخلص العبادةَ لله وحده؛ واستسلم لأمره وحكمه؛ ولا تعبد معه سواه؛ فمن نبذ عبادةَ غيرِ الله واستسلم لله فقد اهتدى؛ فاجعل عبادتك خالصةً لله، واستسلامك لربِّ العالمين؛ فبالتوحيدِ والاستسلامِ لله تكون من المسلمين الموحّدين."}},{"n":67,"reflection":{"text":"«هو الذي خلقكم من تراب ثم من نطفة ثم من علقة ثم يخرجكم طفلا ثم لتبلغوا أشدكم ثم لتكونوا شيوخا ومنكم من يتوفى من قبل ولتبلغوا أجلا مسمى ولعلكم تعقلون»: هو الذي خلقكم أطوارًا: من ترابٍ ثم نطفةٍ ثم علقةٍ ثم طفلًا ثم شبابًا ثم شيوخًا، ومنكم من يموت قبل ذلك، لتبلغوا أجلًا مسمًّى ولعلّكم تعقلون؛ ففي هذا آيةُ خلقِ الإنسانِ أطوارًا على القدرةِ والبعث؛ فتأمّل في أطوارِ خلقك وضعفك، فمن نقلك في هذه الأطوارِ قادرٌ على بعثك، فاعقل واعتبر، ولا تغترّ بقوّتك فمصيرك الضعفُ والموت.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"التأمّلُ في أطوارِ الخلقِ والضعف، والاعتبارُ بها للتوحيدِ والبعث."},"action":{"text":"تأمّل آيةَ الله في أطوارِ خلقِ الإنسان: هو الذي خلقكم، بخلقِ أبيكم آدم، من تراب، ثم خلق نسله من نطفةٍ (منيّ)، ثم من علقةٍ (دمٍ جامد)، ثم يخرجكم من بطونِ أمهاتكم أطفالًا، ثم تنمون لتبلغوا أشدّكم وقوّتكم، ثم لتكونوا شيوخًا ضعفاء، ومنكم من يُتوفّى ويموت قبل ذلك؛ ولتبلغوا أجلًا مسمًّى محدّدًا عند الله، ولعلّكم تعقلون فتعتبرون «هو الذي خلقكم من تراب ثم من نطفة ثم من علقة ثم يخرجكم طفلا ثم لتبلغوا أشدكم ثم لتكونوا شيوخا... ولعلكم تعقلون»؛ ففي هذا آيةُ خلقِ الإنسانِ في أطواره المتعدّدةِ الدالّةِ على قدرةِ الله والبعث؛ فتأمّل في أطوارِ خلقك: من ترابٍ ونطفةٍ إلى طفلٍ فشابٍّ فشيخ؛ وتأمّل ضعفك في مبدئك ومنتهاك؛ فمن نقلك في هذه الأطوارِ من ضعفٍ إلى قوّةٍ إلى ضعف، قادرٌ على أن يبعثك بعد موتك؛ فاعقل واعتبر بأطوارِ خلقك؛ ولا تغترّ بقوّةِ شبابك، فإنّ مصيرك الضعفُ والشيخوخةُ والموت؛ فتذكّر ضعفك ونهايتك، لتتواضع لربك وتعبده؛ فمن تأمّل أطوارَ خلقه عرف قدرةَ خالقه، وأيقن بالبعث، وتواضع لله؛ فاعقل، واعتبر، ووحّد خالقك، واستعدّ للأجلِ المسمّى."}},{"n":68,"reflection":{"text":"«هو الذي يحيي ويميت فإذا قضى أمرا فإنما يقول له كن فيكون»: هو الذي يحيي ويميت، فإذا قضى أمرًا فإنما يقول له كن فيكون؛ ففي هذا تقريرُ تفرّدِ الله بالإحياءِ والإماتةِ ونفوذِ أمره؛ فاعلم أنّ الحياةَ والموتَ بيدِ الله، وأنّ أمره نافذٌ بكلمةِ كن، فسلّم لله في الحياةِ والموتِ والقدر، فمن كان أمره بهذه القدرةِ يستحقّ العبادةَ والتسليم.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"التسليمُ لله المتفرّدِ بالإحياءِ والإماتةِ ونفوذِ الأمر."},"action":{"text":"تأمّل تفرّدَ الله بالإحياءِ والإماتةِ وكمالِ قدرته: هو الذي يحيي الخلقَ من العدمِ ومن الموت، ويميتهم بعد الحياة، لا يشاركه في ذلك أحد؛ فإذا قضى أمرًا وأراد شيئًا فإنما يقول له كن فيكون بلا معالجةٍ ولا تعب، بمجرّدِ إرادته وكلمته «هو الذي يحيي ويميت فإذا قضى أمرا فإنما يقول له كن فيكون»؛ ففي هذا تقريرُ تفرّدِ الله بالإحياءِ والإماتة، وكمالِ قدرتِه ونفوذِ أمره؛ فاعلم أنّ الحياةَ والموتَ بيدِ الله وحده، يحيي من يشاء ويميت من يشاء؛ وأنّ أمره نافذٌ بمجرّدِ كلمةِ «كن»؛ إنما أمره إذا أراد شيئًا أن يقول له كن فيكون؛ فما شاء الله كان، وما لم يشأ لم يكن؛ فسلّم لله في الحياةِ والموتِ والقدر؛ فالله يحيي ويميت بحكمته؛ ولا رادَّ لأمره، ولا معقّبَ لحكمه؛ فمن كانت قدرته بهذا الكمالِ، يحيي ويميت، ويقول للشيءِ كن فيكون، فهو المستحقُّ للعبادةِ والتسليمِ والتوكّل؛ فوحّده، واعبده، وسلّم لأمره وقدره؛ فمن آمن بقدرةِ الله على الإحياءِ والإماتةِ ونفوذِ أمره أيقن بالبعثِ وسلّم لله؛ فاجعل تسليمك لله في أقداره، ويقينك بكمالِ قدرته، وعبادتك خالصةً له."}}]},{"title":"المجادلون وعذابهم، والأمرُ بالصبر، وإرسالُ الرسل، وآياتُ الأنعام، وسنّةُ الله في المكذّبين","range":[69,85],"theme":"التعجّبُ من انصرافِ المجادلين وعذابُ المكذّبين بالكتابِ بالأغلالِ والسلاسلِ والحميمِ والنار وتبكيتُهم بعجزِ آلهتهم وأنّ ذلك بفرحهم بالباطل، والأمرُ بالصبرِ وأنّ الرسلَ كثيرون والآياتِ بإذنِ الله، وتعدادُ نعمةِ الأنعامِ والفلكِ ووضوحِ آياتِ الله، والاعتبارُ بالأممِ الأقوى التي لم يغنِ عنها كسبها إذ فرحوا بعلمِ الدنيا عن علمِ الوحي، وأنّ إيمانهم عند رؤيةِ البأسِ لم ينفعهم سنّةَ الله في عباده","verses":[{"n":69,"reflection":{"text":"«ألم تر إلى الذين يجادلون في آيات الله أنى يصرفون»: ألم تنظر إلى الذين يجادلون في آياتِ الله كيف يُصرَفون عن الحقِّ إلى الباطل؟ ففي هذا التعجّبُ من انصرافِ المجادلين عن الحق؛ فاحذر أن تكون من المجادلين في آياتِ الله المصروفين عن الحق، فاقبل آياتِ الله ولا تجادل فيها بالباطل، فالجدالُ بالباطلِ يصرف عن الحق.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الجدالِ في آياتِ الله، وقبولُها دون معاندة."},"action":{"text":"تأمّل التعجّبَ من حالِ المجادلين: ألم تر، أيها المخاطب، إلى الذين يجادلون في آياتِ الله بالباطلِ لدفعها وردِّها، كيف يُصرَفون عن الحقِّ الواضحِ إلى الباطل، ويُعرِضون عن الهدى مع وضوحه؟ «ألم تر إلى الذين يجادلون في آيات الله أنى يصرفون»؛ ففي هذا التعجّبُ من انصرافِ المجادلين عن الحقِّ مع بيانه؛ فما أعجبَ حالَ من يُعرِض عن الحقِّ الواضحِ ويجادل فيه بالباطل! فاحذر أن تكون من المجادلين في آياتِ الله المصروفين عن الحق؛ فالجدالُ في آياتِ الله بالباطلِ من صفاتِ الكفّارِ والمعاندين؛ فاقبل آياتِ الله بالتصديقِ والإذعان؛ ولا تجادل فيها بالباطلِ والشُّبَه؛ فمن جادل في الحقِّ بالباطلِ صُرِف عنه؛ ومن قبله بتواضعٍ اهتدى؛ فتأمّل آياتِ الله بعينِ الإيمانِ والقبول، لا بعينِ الجدالِ والمعاندة؛ فالجدالُ بالباطلِ يصرف عن الحقِّ ويعمي عنه؛ فلا تكن ممّن يُصرَف عن الحقِّ بجداله؛ بل كن ممّن يهتدي به لقبوله؛ فاجعل موقفك من آياتِ الله القبولَ والإذعان، لا الجدالَ والإعراض."}},{"n":70,"reflection":{"text":"«الذين كذبوا بالكتاب وبما أرسلنا به رسلنا فسوف يعلمون»: الذين كذّبوا بالقرآنِ وبما أرسلنا به رسلنا من الحقّ، فسوف يعلمون عاقبةَ تكذيبهم؛ ففي هذا وعيدُ المكذّبين بالكتابِ والرسل؛ فاحذر التكذيبَ بالكتابِ والرسل، فعاقبتُه وخيمة، فآمن بالقرآنِ وبما جاءت به الرسل، فالمكذّبون سوف يعلمون سوءَ ما اختاروا.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بالكتابِ والرسل، والحذرُ من التكذيبِ بهما."},"action":{"text":"تأمّل وعيدَ الله للمكذّبين: الذين كذّبوا بالكتابِ، القرآنِ، وبما أرسلنا به رسلنا من الكتبِ والشرائعِ والحق، فسوف يعلمون عاقبةَ تكذيبهم حين ينزل بهم العذاب «الذين كذبوا بالكتاب وبما أرسلنا به رسلنا فسوف يعلمون»؛ ففي هذا وعيدٌ شديدٌ للمكذّبين بالكتابِ والرسل؛ فاحذر التكذيبَ بالقرآنِ وبما جاءت به الرسلُ من الحق؛ فعاقبةُ التكذيبِ وخيمةٌ في الدنيا والآخرة؛ فآمن بالقرآنِ وصدّق به؛ وآمن بجميعِ ما جاءت به الرسلُ من الحقِّ والهدى؛ فالمكذّبون سوف يعلمون سوءَ عاقبةِ تكذيبهم حين يعاينون العذاب؛ فبادر بالإيمانِ والتصديقِ قبل أن تعلم الحقيقةَ حين لا ينفع العلم؛ فمن آمن بالكتابِ والرسلِ نجا، ومن كذّب بهما هلك؛ فلا تكن من المكذّبين الذين سوف يعلمون؛ بل كن من المصدّقين المؤمنين؛ فاجعل إيمانك بالقرآنِ وبما جاءت به الرسلُ راسخًا في قلبك؛ فبه النجاةُ والفوز، وبتكذيبه الهلاكُ والخسران."}},{"n":71,"reflection":{"text":"«إذ الأغلال في أعناقهم والسلاسل يسحبون»: حين تكون الأغلالُ في أعناقهم والسلاسلُ يُجَرّون بها؛ ففي هذا تصويرُ عذابِ المكذّبين وذلّهم؛ فاحذر ما يوصلك إلى هذا العذابِ المهين، فاعمل لتنجو منه، فتصوّرُ الأغلالِ والسلاسلِ يبعث على التوبةِ والعمل، فبادر بالطاعةِ قبل هذا العذاب.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ الأغلالِ والسلاسل، والمبادرةُ بالتوبة."},"action":{"text":"تأمّل تصويرَ الله لعذابِ المكذّبين وذلّهم: سوف يعلمون عاقبةَ تكذيبهم حين تكون الأغلالُ في أعناقهم، والسلاسلُ يُجَرّون ويُسحَبون بها في العذاب «إذ الأغلال في أعناقهم والسلاسل يسحبون»؛ ففي هذا تصويرُ عذابِ المكذّبين وذلّهم وهوانهم؛ فتُجعَل الأغلالُ في أعناقهم، ويُسحَبون بالسلاسلِ سحبَ الذليلِ المهان؛ فاحذر ما يوصلك إلى هذا العذابِ المهينِ من التكذيبِ والكفرِ والمعاصي؛ واعمل لتنجو منه بالإيمانِ والتوحيدِ والطاعة؛ فتصوّرُ الأغلالِ في الأعناقِ والسحبِ بالسلاسلِ يبعث القلبَ على التوبةِ والعملِ الصالح؛ فمن تذكّر هذا العذابَ هان عليه تركُ المعاصي؛ فبادر بالطاعةِ والتوبةِ قبل أن تُجعَل الأغلالُ في عنقك وتُسحَب بالسلاسل؛ فاعمل في زمنِ المهلةِ لتنجو من عذابِ الآخرةِ المهين؛ فالسعيدُ من عمل لينجو، والشقيُّ من فرّط فوقع في العذاب؛ فاجعل تصوّرَ هذا العذابِ دافعًا لك إلى الإيمانِ والطاعةِ واجتنابِ التكذيبِ والمعاصي."}},{"n":72,"reflection":{"text":"«في الحميم ثم في النار يسجرون»: في الماءِ الحارِّ يُسحَبون، ثم في النارِ يُحرَقون ويُوقَدون؛ ففي هذا تصاعدُ عذابِ المكذّبين؛ فاحذر النارَ التي يُسجَر فيها المكذّبون، واعمل لتنجو منها، فعذابُ النارِ شديدٌ متصاعد، فاجتنب أسبابه بالإيمانِ والطاعة.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من عذابِ النارِ المتصاعد، واجتنابُ أسبابه."},"action":{"text":"تأمّل تصاعدَ عذابِ المكذّبين: يُسحَبون بالسلاسلِ في الحميمِ، الماءِ الحارِّ الذي بلغ منتهى الحرارة، ثم في النارِ يُسجَرون، أي يُحرَقون ويُوقَد بهم، فيكونون وقودًا لها «في الحميم ثم في النار يسجرون»؛ ففي هذا تصاعدُ عذابِ المكذّبين من الحميمِ إلى النار؛ فاحذر النارَ التي يُسجَر فيها المكذّبون؛ واعمل لتنجو منها بالإيمانِ والتوحيدِ والطاعة؛ فعذابُ النارِ شديدٌ متصاعدٌ لا يُطاق؛ يُسحَبون في الحميمِ ثم يُسجَرون في النار؛ فاجتنب أسبابَ عذابِ النارِ من الكفرِ والتكذيبِ والمعاصي؛ والزم أسبابَ النجاةِ من الإيمانِ والتقوى والطاعة؛ فمن اتّقى الله نجّاه من النار؛ فاتّقوا النارَ التي وقودها الناسُ والحجارة؛ فتذكّر عذابَ النارِ لتجتنب ما يوصل إليه؛ واستعذ بالله من النارِ ومن عذابها؛ فمن خاف النارَ اجتنب أسبابها؛ فبادر بالإيمانِ والطاعةِ والتوبة؛ فبها تنجو من عذابِ النارِ المتصاعد؛ فاجعل خوفَ النارِ حاجزًا لك عن كلِّ ما يوصل إليها."}},{"n":73,"reflection":{"text":"«ثم قيل لهم أين ما كنتم تشركون»: ثم يُقال للمشركين توبيخًا: أين آلهتكم التي كنتم تشركونها مع الله؟ ففي هذا تبكيتُ المشركين بعجزِ آلهتهم؛ فتأمّل عجزَ كلِّ معبودٍ سوى الله يومَ القيامة، فلا تعبد ما يتخلّى عنك يومَ حاجتك، بل وحّد الله الذي لا يتخلّى عن عبده، فالمعبوداتُ الباطلةُ تضلّ عن عابديها يومئذ.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله، وإدراكُ عجزِ المعبوداتِ الباطلةِ يومَ القيامة."},"action":{"text":"تأمّل تبكيتَ الله للمشركين يومَ القيامة: ثم يُقال للمشركين توبيخًا وتقريعًا: أين آلهتكم وأصنامكم التي كنتم تشركونها مع الله وتعبدونها من دونه؟ أين هي الآن لتنفعكم أو تدفع عنكم العذاب؟ «ثم قيل لهم أين ما كنتم تشركون»؛ ففي هذا تبكيتُ المشركين وتقريعهم بعجزِ آلهتهم عن نصرهم؛ فتأمّل عجزَ كلِّ معبودٍ سوى الله يومَ القيامة؛ حيث تتخلّى المعبوداتُ الباطلةُ عن عابديها، ولا تنفعهم شيئًا؛ فلا تعبد ما يتخلّى عنك يومَ حاجتك إليه؛ ولا تتعلّق بمن لا ينفعك يومَ الشدّة؛ بل وحّد الله الذي لا يتخلّى عن عبده المؤمنِ في الدنيا والآخرة؛ فالمعبوداتُ الباطلةُ تضلّ وتغيب عن عابديها يومَ القيامةِ حين يحتاجون إليها؛ ويومَ القيامةِ يكفرون بشرككم؛ فاعبد الله الذي ينفعك في الدارين، ولا يتخلّى عنك؛ ولا تعبد ما يخذلك يومَ حاجتك؛ فمن عبد الله وحده نفعه، ومن عبد غيره خذله معبوده يومَ القيامة؛ فوحّد الله، وأخلص له العبادة؛ فهو وحده الذي ينفع ويضرّ، ولا يتخلّى عن عابده."}},{"n":74,"reflection":{"text":"«من دون الله قالوا ضلوا عنا بل لم نكن ندعو من قبل شيئا كذلك يضل الله الكافرين»: الذين تعبدونهم من دونِ الله، قالوا: غابوا عنّا، بل لم نكن ندعو من قبلُ شيئًا يُذكَر، كذلك يضلّ الله الكافرين؛ ففي هذا تبرّؤُ المشركين من معبوداتهم وإنكارهم إيّاها؛ فاعلم أنّ معبوداتِ الباطلِ تضلّ عن عابديها ويتبرّؤون منها، فلا تعبد ما تتبرّأ منه يومَ القيامة، بل وحّد الله الذي لا تندم على عبادته.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"توحيدُ الله، وتركُ عبادةِ ما يُتبرَّأ منه يومَ القيامة."},"action":{"text":"تأمّل حالَ المشركين حين يُسألون عن معبوداتهم: الذين كانوا يعبدونهم من دونِ الله، قالوا: ضلّوا وغابوا عنّا فلا نراهم ولا ينفعوننا؛ بل تبرّؤوا وأنكروا فقالوا: لم نكن ندعو من قبلُ شيئًا يستحقّ العبادة؛ كذلك، كما أضلّهم عن معبوداتهم، يضلّ الله الكافرين عن الحق «من دون الله قالوا ضلوا عنا بل لم نكن ندعو من قبل شيئا كذلك يضل الله الكافرين»؛ ففي هذا تبرّؤُ المشركين من معبوداتهم يومَ القيامةِ وإنكارهم لها؛ فيتخلّى عنهم معبودهم، ويتبرّؤون منه، وينكرون أنهم عبدوا شيئًا؛ فاعلم أنّ معبوداتِ الباطلِ تضلّ وتغيب عن عابديها يومَ القيامة، ويتبرّأ العابدون منها؛ فلا تعبد ما تتبرّأ منه وتندم على عبادته يومَ القيامة؛ فكلُّ معبودٍ سوى الله سيتخلّى عن عابده ويتبرّأ منه؛ بل وحّد الله الذي لا تندم على عبادته، ولا يتخلّى عنك؛ فمن عبد غيرَ الله ندم وتبرّأ من معبوده حين لا ينفع؛ ومن عبد الله وحده فاز ولم يندم؛ فاجعل عبادتك لله وحده؛ فهو الذي ينفعك ولا يتخلّى عنك؛ فوحّده، وأخلص له، ولا تعبد ما سواه."}},{"n":75,"reflection":{"text":"«ذلكم بما كنتم تفرحون في الأرض بغير الحق وبما كنتم تمرحون»: ذلك العذابُ بسببِ فرحكم في الأرضِ بغيرِ الحقِّ وبطركم وأشركم؛ ففي هذا بيانُ أنّ الفرحَ بالباطلِ والبطرَ سببُ العذاب؛ فاحذر الفرحَ بالباطلِ والبطرَ والأشرَ، فالفرحُ بغيرِ الحقِّ سببُ العذاب، فافرح بطاعةِ الله وفضله، لا بالباطلِ والمعصية.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الفرحِ بالباطلِ والبطر، والفرحُ بفضلِ الله وطاعته."},"action":{"text":"تأمّل بيانَ سببِ عذابِ المشركين: يُقال لهم: ذلكم العذابُ الذي أنتم فيه بسببِ ما كنتم تفرحون به في الأرضِ من الباطلِ والكفرِ والمعاصي فرحَ بطرٍ وأشر، وبما كنتم تمرحون وتتبخترون كِبرًا وخيلاء «ذلكم بما كنتم تفرحون في الأرض بغير الحق وبما كنتم تمرحون»؛ ففي هذا بيانُ أنّ الفرحَ بالباطلِ والبطرَ والمرحَ من أسبابِ العذاب؛ فاحذر الفرحَ بالباطلِ والمعاصي والكفر؛ واحذر البطرَ والأشرَ والمرحَ والخيلاء؛ فإنّ الله لا يحبّ الفرحين البطرين؛ إنّ الله لا يحبّ من كان مختالًا فخورًا؛ ولا تفرح إنّ الله لا يحبّ الفرحين؛ فالفرحُ بغيرِ الحقِّ سببُ العذاب؛ فلا تمشِ في الأرضِ مرحًا؛ بل افرح بطاعةِ الله وفضلِه ورحمته؛ قل بفضلِ الله وبرحمته فبذلك فليفرحوا؛ فالفرحُ المحمودُ هو الفرحُ بفضلِ الله ونعمته وطاعته؛ والفرحُ المذمومُ هو الفرحُ بالباطلِ والمعاصي والدنيا بطرًا؛ فاجعل فرحك بما يقرّبك إلى الله من الطاعةِ والفضل؛ واحذر الفرحَ بالباطلِ والبطرَ الذي يورث العذاب؛ فمن فرح بفضلِ الله شكر، ومن فرح بالباطلِ بطر."}},{"n":76,"reflection":{"text":"«ادخلوا أبواب جهنم خالدين فيها فبئس مثوى المتكبرين»: يُقال لهم: ادخلوا أبوابَ جهنمَ ماكثين فيها أبدًا، فبئس مأوى المتكبّرين؛ ففي هذا خلودُ المتكبّرين في النار؛ فاحذر الكِبرَ عن الحقِّ الذي عاقبتُه الخلودُ في النار، فتواضع للحقِّ واقبله، فالكِبرُ مثواه جهنم، فاطرح الكِبرَ ونجِّ نفسك.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الكِبرِ الموجبِ للخلودِ في النار، والتواضعُ للحق."},"action":{"text":"تأمّل عاقبةَ المتكبّرين: يُقال للمشركين المتكبّرين: ادخلوا أبوابَ جهنمَ، دركاتها وأبوابها، خالدين ماكثين فيها أبدًا لا تخرجون، فبئس مثوى ومأوى المتكبّرين عن الحقِّ والتوحيد «ادخلوا أبواب جهنم خالدين فيها فبئس مثوى المتكبرين»؛ ففي هذا بيانُ خلودِ المتكبّرين في النار، وأنها بئسَ المثوى لهم؛ فاحذر الكِبرَ عن الحقِّ والتوحيدِ الذي عاقبتُه الخلودُ في النار؛ فالكِبرُ أهلك إبليس، وأورد المتكبّرين النار؛ فتواضع للحقِّ واقبله ممّن جاء به؛ ولا تستكبر عن الإيمانِ والطاعةِ والانقيادِ للحق؛ فالكِبرُ بطرُ الحقِّ وغمطُ الناس؛ ولا يدخل الجنّةَ من كان في قلبه مثقالُ ذرّةٍ من كبر؛ فاطرح الكِبرَ والعُجب؛ وتواضع لله وللحقِّ وللخلق؛ فمن تواضع لله رفعه، ومن تكبّر وضعه وأخزاه؛ فنجِّ نفسك من مثوى المتكبّرين بالتواضعِ للحقِّ وقبوله؛ فالتواضعُ سبيلُ الجنّة، والكِبرُ سبيلُ النار؛ فاحذر الكِبرَ، والزم التواضع؛ فبالتواضعِ للحقِّ تنجو من الخلودِ في جهنم."}},{"n":77,"reflection":{"text":"«فاصبر إن وعد الله حق فإما نرينك بعض الذي نعدهم أو نتوفينك فإلينا يرجعون»: فاصبر يا محمدُ إنّ وعدَ الله بنصرك حق، فإما نرينّك بعضَ ما نعدهم من العذاب في الدنيا، أو نتوفّينّك قبل ذلك، فإلينا يُرجَعون فنجازيهم؛ ففي هذا الأمرُ بالصبرِ والثقةِ بوعدِ الله؛ فاصبر على أذى المخالفين واثقًا بوعدِ الله، فسواءٌ رأيت عاقبتهم أم لم ترها، فمرجعهم إلى الله، فاصبر وكِل أمرهم إلى الله.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الصبرُ والثقةُ بوعدِ الله، وتوكيلُ أمرِ المخالفين إليه."},"action":{"text":"تأمّل الأمرَ بالصبرِ والثقةِ بوعدِ الله: فاصبر يا محمدُ على أذى المكذّبين وتكذيبهم، إنّ وعدَ الله بنصرك وإهلاكهم حقٌّ لا يتخلّف؛ فإما نرينّك في حياتك بعضَ الذي نعدهم من العذابِ والنكالِ في الدنيا فتقرّ عينك، أو نتوفّينّك قبل أن نريك ذلك، فإلينا يُرجَعون جميعًا يومَ القيامةِ فنجازيهم بأعمالهم «فاصبر إن وعد الله حق فإما نرينك بعض الذي نعدهم أو نتوفينك فإلينا يرجعون»؛ ففي هذا الأمرُ بالصبرِ والثقةِ بوعدِ الله؛ فاصبر على أذى المخالفين والمكذّبين، واثقًا بوعدِ الله بنصرك؛ فسواءٌ رأيت عاقبةَ المكذّبين في الدنيا أم لم ترها، فمرجعهم إلى الله فيجازيهم؛ فلا يهمّنّك أمرهم؛ بل اصبر، وكِل أمرهم إلى الله؛ فإنّ الله ناصرك ومجازيهم لا محالة؛ فما عليك إلا الصبرُ والبلاغ، وعلى الله الجزاء؛ فاصبر واحتسب، وثق بوعدِ الله؛ فإنّ العاقبةَ للمتّقين؛ فمن صبر ظفر، ومن وثق بوعدِ الله لم يخب؛ فاجعل الصبرَ والثقةَ بوعدِ الله زادك في مواجهةِ المخالفين؛ فإليه مرجع الجميع، وهو يجازي كلًّا بعمله."}},{"n":78,"reflection":{"text":"«ولقد أرسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك وما كان لرسول أن يأتي بآية إلا بإذن الله فإذا جاء أمر الله قضي بالحق وخسر هنالك المبطلون»، ولقد أرسلنا رسلًا قبلك، منهم من قصصنا عليك ومنهم من لم نقصص، وما كان لرسولٍ أن يأتي بآيةٍ إلا بإذنِ الله، فإذا جاء أمرُ الله قُضِي بالحقِّ وخسر المبطلون؛ ففي هذا كثرةُ الرسلِ وأنّ الآياتِ بإذنِ الله؛ فاعلم أنّ الرسلَ كثيرون وأنّ الأمرَ كلَّه بيدِ الله، فآمن بجميعِ الرسل، وسلّم لله في تدبيره، فإذا جاء أمرُه خسر المبطلون.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإيمانُ بجميعِ الرسل، والتسليمُ لله في تدبيره وقضائه."},"action":{"text":"تأمّل بيانَ الله لكثرةِ رسله ونفوذِ أمره: ولقد أرسلنا رسلًا كثيرين من قبلك يا محمد، منهم من قصصنا عليك خبره في القرآن، ومنهم من لم نقصص عليك؛ وما كان لرسولٍ من هؤلاء أن يأتيَ بآيةٍ أو معجزةٍ يقترحها قومه إلا بإذنِ الله ومشيئته، لا بقدرته هو؛ فإذا جاء أمرُ الله بالفصلِ والعذابِ قُضِي بين الرسلِ وأممهم بالحقِّ والعدل، وخسر هنالك المبطلون المكذّبون «ولقد أرسلنا رسلا من قبلك منهم من قصصنا عليك ومنهم من لم نقصص عليك وما كان لرسول أن يأتي بآية إلا بإذن الله فإذا جاء أمر الله قضي بالحق وخسر هنالك المبطلون»؛ ففي هذا بيانُ كثرةِ الرسل، وأنّ الآياتِ والمعجزاتِ بإذنِ الله لا بقدرةِ الرسل؛ فاعلم أنّ رسلَ الله كثيرون، أرسلهم رحمةً بالعباد؛ فآمن بجميعِ الرسل، من ذُكِر منهم ومن لم يُذكَر؛ واعلم أنّ الأمرَ كلَّه بيدِ الله؛ فالآياتُ لا تأتي إلا بإذنه؛ فلا تقترح على الله الآياتِ، ولا تتحكّم في تدبيره؛ بل سلّم لله في تدبيره وقضائه؛ فإذا جاء أمرُ الله قُضِي بالحقِّ وخسر المبطلون؛ فلا تكن من المبطلين المكذّبين الذين يخسرون عند مجيءِ أمرِ الله؛ بل كن من المصدّقين المؤمنين؛ فاجعل إيمانك بالرسلِ جميعًا، وتسليمك لله في أمره وقضائه؛ فالعاقبةُ للمؤمنين، والخسرانُ للمبطلين."}},{"n":79,"reflection":{"text":"«الله الذي جعل لكم الأنعام لتركبوا منها ومنها تأكلون»: الله الذي جعل لكم الأنعامَ لتركبوا منها وتأكلوا؛ ففي هذا تعدادُ نعمةِ الأنعامِ على العباد؛ فتأمّل نعمةَ الله في الأنعامِ التي سخّرها لركوبك وطعامك، واشكرها، فمن سخّر لك الأنعامَ يستحقّ الشكرَ والعبادة، فاشكر المنعمَ ووحّده.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ نعمةِ الأنعامِ المسخّرة، وتوحيدُ المنعمِ بها."},"action":{"text":"تأمّل نعمةَ الله في الأنعام: الله الذي جعل لكم الأنعامَ، الإبلَ والبقرَ والغنم، لتركبوا بعضها (كالإبل) وتحملوا عليها أثقالكم، ومنها تأكلون لحومها وتنتفعون بها «الله الذي جعل لكم الأنعام لتركبوا منها ومنها تأكلون»؛ ففي هذا تعدادُ نعمةِ الأنعامِ التي سخّرها الله للعباد؛ فتأمّل نعمةَ الله في هذه الأنعامِ التي سخّرها لك: تركب بعضها، وتأكل من لحومها، وتنتفع بألبانها وأصوافها؛ فمن الذي خلقها وذلّلها لك وأنت لا تقدر على خلقها ولا تسخيرها؟ إنه الله؛ فاشكر الله على نعمةِ الأنعامِ المسخّرة؛ فمن سخّر لك هذه الأنعامَ لمنافعك يستحقّ الشكرَ والعبادةَ والحمد؛ أولم يروا أنّا خلقنا لهم ممّا عملت أيدينا أنعامًا فهم لها مالكون وذلّلناها لهم فمنها ركوبهم ومنها يأكلون؛ فاشكر المنعمَ ووحّده؛ واستعمل نعمه في طاعته؛ فمن تأمّل نعمَ الله في خلقه شكرها ووحّد المنعم؛ فاجعل تأمّلك في نعمِ الله سبيلًا لشكره وعبادته."}},{"n":80,"reflection":{"text":"«ولكم فيها منافع ولتبلغوا عليها حاجة في صدوركم وعليها وعلى الفلك تحملون»، ولكم في الأنعامِ منافعُ كثيرة، ولتبلغوا عليها حاجةً في نفوسكم (كالأسفار)، وعليها وعلى السفنِ تُحمَلون؛ ففي هذا تمامُ تعدادِ منافعِ الأنعامِ والفلك؛ فتأمّل كثرةَ منافعِ الله عليك في الأنعامِ والفلك، واشكرها، فمن أنعم عليك بهذه المنافعِ يستحقّ الشكرَ، فاشكر الله على تسخيرِ ما تنتفع به.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"شكرُ منافعِ الله في الأنعامِ والفلك، وتوحيدُ المنعم."},"action":{"text":"تأمّل تمامَ منافعِ الأنعامِ والفلك: ولكم في الأنعامِ منافعُ كثيرةٌ متعدّدة، من الألبانِ والأصوافِ والأوبارِ والجلود؛ ولتبلغوا وتقضوا عليها حاجةً في صدوركم ونفوسكم، كالأسفارِ وحملِ الأثقالِ إلى البلادِ البعيدة؛ وعليها، في البرّ، وعلى الفلكِ والسفنِ، في البحر، تُحمَلون وتُنقَلون «ولكم فيها منافع ولتبلغوا عليها حاجة في صدوركم وعليها وعلى الفلك تحملون»؛ ففي هذا تمامُ تعدادِ منافعِ الأنعامِ والفلكِ التي سخّرها الله؛ فتأمّل كثرةَ منافعِ الله عليك في الأنعامِ والفلك: تحمل عليها أثقالك، وتقضي بها حوائجك، وتُنقَل عليها في البرِّ والبحر؛ فمن سخّر لك الأنعامَ والفلكَ لمنافعك ونقلك؟ إنه الله؛ فاشكر الله على هذه المنافعِ الكثيرة؛ فمن أنعم عليك بها يستحقّ الشكرَ والعبادة؛ والذي خلق الأزواجَ كلَّها وجعل لكم من الفلكِ والأنعامِ ما تركبون؛ فاشكر الله على تسخيرِ ما تنتفع به من الأنعامِ والفلك؛ واستعمل هذه النعمَ في طاعته؛ فمن تأمّل نعمَ الله ومنافعها شكرها ووحّد المنعم؛ فاجعل قلبك عامرًا بشكرِ الله على نعمه ومنافعها."}},{"n":81,"reflection":{"text":"«ويريكم آياته فأي آيات الله تنكرون»، ويريكم آياته في الآفاقِ والأنفس، فأيَّ آياتِ الله تنكرون؟ ففي هذا تقريرُ وضوحِ آياتِ الله وأنه لا سبيلَ لإنكارها؛ فتأمّل آياتِ الله الكثيرةَ التي لا تُنكَر، وآمن بها، فآياتُ الله واضحةٌ لا يمكن إنكارها، فاعترف بها وأقرّ، ووحّد من هذه آياته.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الإقرارُ بآياتِ الله الواضحة، والإيمانُ بها وتوحيدُ من هذه آياته."},"action":{"text":"تأمّل تقريرَ الله لوضوحِ آياته: ويريكم الله آياته الكثيرةَ الدالّةَ على وحدانيّته وقدرته وعظمته، في الآفاقِ والأنفسِ والأنعامِ والفلكِ وسائرِ المخلوقات، فأيَّ آياتِ الله تنكرون وتجحدون؟ لا سبيلَ لإنكارِ شيءٍ منها لوضوحها «ويريكم آياته فأي آيات الله تنكرون»؛ ففي هذا تقريرُ وضوحِ آياتِ الله، وأنه لا سبيلَ لإنكارها ولا مجالَ لجحودها؛ فتأمّل آياتِ الله الكثيرةَ الواضحةَ التي لا تُنكَر: في خلقِ السماواتِ والأرض، وفي الأنعامِ والفلك، وفي نفسك وخلقك؛ فأيّها تستطيع أن تنكر؟ فكلُّها ظاهرةٌ بيّنةٌ دالّةٌ على الله؛ فآمن بآياتِ الله كلِّها، وأقرّ بها، ولا تجحد شيئًا منها؛ سنريهم آياتنا في الآفاقِ وفي أنفسهم حتى يتبيّن لهم أنه الحق؛ فآياتُ الله واضحةٌ لا يمكن إنكارها إلا مكابرةً وعنادًا؛ فاعترف بها، وأقرّ بدلالتها؛ ووحّد من هذه آياته الدالّةُ عليه؛ فمن تأمّل آياتِ الله آمن بها ووحّد ربه، ومن جحدها كابر وعاند؛ فلا تكن من الجاحدين المكابرين؛ بل كن من المؤمنين المقرّين بآياتِ الله، الموحّدين لربهم."}},{"n":82,"reflection":{"text":"«أفلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم كانوا أكثر منهم وأشد قوة وآثارا في الأرض فما أغنى عنهم ما كانوا يكسبون»: أفلم يسيروا في الأرضِ فينظروا كيف كانت عاقبةُ الأممِ قبلهم، كانوا أكثرَ منهم وأشدَّ قوّةً وآثارًا، فما أغنى عنهم ما كسبوا؟ ففي هذا الحثُّ على الاعتبارِ بمصارعِ الأمم؛ فاعتبر بعاقبةِ الأممِ الأقوى التي لم يغنِ عنها كسبها، ولا تغترّ بقوّتك ومالك، فالكسبُ والقوّةُ لا يدفعان عذابَ الله.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"الاعتبارُ بمصارعِ الأمم، وعدمُ الاغترارِ بالقوّةِ والمال."},"action":{"text":"تأمّل الحثَّ على الاعتبار: أفلم يسر هؤلاء المكذّبون في الأرضِ فينظروا كيف كانت عاقبةُ الأممِ المكذّبةِ التي كانت قبلهم؟ كانوا أكثرَ منهم عددًا، وأشدَّ منهم قوّةً، وأكثرَ آثارًا في الأرضِ من العمارةِ والبناء؛ فما أغنى عنهم ما كانوا يكسبون من الأموالِ والقوّةِ والآثارِ حين نزل بهم عذابُ الله «أفلم يسيروا في الأرض فينظروا كيف كان عاقبة الذين من قبلهم كانوا أكثر منهم وأشد قوة وآثارا في الأرض فما أغنى عنهم ما كانوا يكسبون»؛ ففي هذا الحثُّ على الاعتبارِ بمصارعِ الأممِ الماضية؛ فاعتبر بعاقبةِ الأممِ التي كانت أكثرَ عددًا وأشدَّ قوّةً وأكثرَ آثارًا، ومع ذلك أهلكها الله بذنوبها، ولم يغنِ عنها كسبها وقوّتها؛ فسيروا في الأرضِ فانظروا كيف كان عاقبةُ المكذّبين؛ ولا تغترّ بقوّتك ومالك وآثارك؛ فإنّ الكسبَ والقوّةَ والآثارَ لا تدفع عذابَ الله عمّن استحقّه؛ فما أغنى عن الأممِ القويّةِ كسبها حين حقّ عليها العذاب؛ فاتّق الله، ولا تغترّ بما جمعت من دنيا؛ واعتبر بمن قبلك؛ فمن اعتبر بغيره سلم، ومن اغترّ بقوّته وكسبه أُخِذ بذنوبه؛ فاجعل من مصارعِ الأممِ عبرةً تحملك على التقوى واجتنابِ الذنوب."}},{"n":83,"reflection":{"text":"«فلما جاءتهم رسلهم بالبينات فرحوا بما عندهم من العلم وحاق بهم ما كانوا به يستهزئون»: فلمّا جاءتهم رسلهم بالبيّناتِ فرحوا بما عندهم من علمِ الدنيا واحتقروا علمَ الرسل، فأحاط بهم العذابُ الذي استهزؤوا به؛ ففي هذا ذمُّ الاغترارِ بالعلمِ الدنيويِّ عن علمِ الوحي؛ فاحذر أن تغترّ بعلمك الدنيويِّ فتردّ علمَ الوحي، فالعلمُ النافعُ ما جاء به الرسل، فلا تحتقر علمَ الوحيِ بعلمِ الدنيا.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"الحذرُ من الاغترارِ بعلمِ الدنيا عن علمِ الوحي، وتعظيمُ الوحي."},"action":{"text":"تأمّل سببَ هلاكِ الأممِ رغمَ علمهم: فلمّا جاءتهم رسلهم بالبيّناتِ والحججِ الواضحة، فرحوا واغترّوا بما عندهم من علمِ الدنيا وصناعاتها ومعارفها، واحتقروا ما جاءت به الرسلُ من علمِ الوحيِ والهدى؛ فأحاط بهم ونزل بهم العذابُ الذي كانوا يستهزئون به ويكذّبون بوقوعه «فلما جاءتهم رسلهم بالبينات فرحوا بما عندهم من العلم وحاق بهم ما كانوا به يستهزئون»؛ ففي هذا ذمُّ الاغترارِ بالعلمِ الدنيويِّ والفرحِ به عن علمِ الوحيِ والهدى؛ فقد أعجبتهم علومهم الدنيويةُ فردّوا بها علمَ الرسل؛ فاحذر أن تغترّ بعلمك الدنيويِّ وذكائك وصناعتك فتردّ علمَ الوحيِ وتستهين به؛ فكم من عالمٍ بأمورِ الدنيا جاهلٍ بأمرِ الآخرة؛ يعلمون ظاهرًا من الحياةِ الدنيا وهم عن الآخرةِ هم غافلون؛ فالعلمُ النافعُ الحقيقيُّ هو ما جاء به الرسلُ من الوحيِ والهدى؛ فلا تحتقر علمَ الوحيِ بعلمِ الدنيا؛ ولا تجعل معارفك الدنيويةَ حاجزًا عن قبولِ الحق؛ بل اجعل علمك الدنيويَّ تابعًا لعلمِ الوحيِ خادمًا له؛ فعظّم علمَ الوحيِ والهدى؛ فمن اغترّ بعلمِ الدنيا عن علمِ الوحي هلك، ومن عظّم علمَ الوحيِ نجا؛ فاجعل الوحيَ إمامك، وعلمك الدنيويَّ خادمًا له."}},{"n":84,"reflection":{"text":"«فلما رأوا بأسنا قالوا آمنا بالله وحده وكفرنا بما كنا به مشركين»: فلمّا رأوا عذابنا قالوا: آمنّا بالله وحده وكفرنا بما كنّا نشرك به؛ ففي هذا إيمانُ المكذّبين عند رؤيةِ العذابِ حيث لا ينفع؛ فاحذر أن تؤخّر الإيمانَ حتى ترى العذاب، فالإيمانُ عند رؤيةِ البأسِ لا ينفع، فبادر بالإيمانِ والتوحيدِ في زمنِ القبول قبل رؤيةِ العذاب.","source":"تفسير ابن كثير","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ قبل رؤيةِ العذاب، فالإيمانُ حينئذٍ لا ينفع."},"action":{"text":"تأمّل حالَ المكذّبين عند نزولِ العذاب: فلمّا رأوا بأسنا وعذابنا نازلًا بهم، قالوا في تلك اللحظة: آمنّا بالله وحده لا شريكَ له، وكفرنا وتبرّأنا بما كنّا به مشركين من الأصنامِ والأنداد «فلما رأوا بأسنا قالوا آمنا بالله وحده وكفرنا بما كنا به مشركين»؛ ففي هذا إيمانُ المكذّبين عند معاينةِ العذابِ حيث لا ينفعهم الإيمان؛ فلمّا عاينوا العذابَ آمنوا وتبرّؤوا من الشرك، ولكن بعد فواتِ الأوان؛ فاحذر أن تؤخّر الإيمانَ والتوبةَ حتى ترى العذابَ أو يحضرك الموت؛ فإنّ الإيمانَ عند رؤيةِ البأسِ ومعاينةِ العذابِ لا ينفع ولا يُقبَل؛ فليس التوبةُ للذين يعملون السيّئاتِ حتى إذا حضر أحدهم الموتُ قال إني تبت الآن؛ فبادر بالإيمانِ والتوحيدِ والتوبةِ في زمنِ القبولِ والمهلة، قبل رؤيةِ العذابِ وحضورِ الموت؛ فمن آمن وتاب في زمنِ القبولِ نفعه، ومن أخّر حتى رأى البأسَ لم ينفعه إيمانه؛ فلا تسوّف بالإيمانِ والتوبة؛ بل بادر بهما الآن؛ فإنّ الأجلَ قد يأتي بغتة، والعذابُ قد ينزل فجأة؛ فآمن ووحّد وتب قبل فواتِ الأوان."}},{"n":85,"reflection":{"text":"«فلم يك ينفعهم إيمانهم لما رأوا بأسنا سنت الله التي قد خلت في عباده وخسر هنالك الكافرون»: فلم ينفعهم إيمانهم لمّا رأوا عذابنا، سنّةَ الله التي مضت في عباده، وخسر هنالك الكافرون؛ ففي هذا تقريرُ سنّةِ الله ألا ينفع الإيمانُ عند رؤيةِ العذاب؛ فاعلم أنّ هذه سنّةٌ ماضيةٌ لا تتبدّل، فبادر بالإيمانِ في زمنِ القبول، فالإيمانُ عند رؤيةِ البأسِ خسارةٌ لا نجاةَ فيها، فاغتنم إيمانك قبل فواتِ الأوان.","source":"تفسير السعدي","grade":"ma'thur"},"names":[],"heart_state":{"text":"المبادرةُ بالإيمانِ في زمنِ القبول، فسنّةُ الله ألا ينفع عند البأس."},"action":{"text":"تأمّل ختامَ السورةِ بتقريرِ سنّةِ الله: فلم يكن ينفعهم إيمانهم لمّا رأوا بأسنا وعاينوا عذابنا؛ فهذه سنّةُ الله وطريقتُه الثابتةُ التي قد خلت ومضت في عباده المكذّبين: ألا يُقبَل الإيمانُ عند معاينةِ العذاب؛ وخسر هنالك الكافرون خسرانًا لا جبرَ له «فلم يك ينفعهم إيمانهم لما رأوا بأسنا سنت الله التي قد خلت في عباده وخسر هنالك الكافرون»؛ ففي هذا تقريرُ سنّةِ الله الثابتةِ ألا ينفع الإيمانُ عند رؤيةِ العذابِ ومعاينةِ البأس؛ فاعلم أنّ هذه سنّةٌ ماضيةٌ في عبادِ الله لا تتبدّل ولا تتحوّل؛ ولن تجد لسنّةِ الله تبديلًا؛ فالإيمانُ عند رؤيةِ البأسِ خسارةٌ لا نجاةَ فيها؛ فقومُ يونسَ وحدهم نفعهم إيمانهم قبل معاينةِ العذابِ التامّ رحمةً خاصّة؛ أمّا من عاين العذابَ فآمن فلا ينفعه؛ فبادر بالإيمانِ والتوحيدِ والتوبةِ في زمنِ القبولِ والمهلة، قبل معاينةِ العذابِ أو حضورِ الموت؛ فاغتنم إيمانك وتوبتك قبل فواتِ الأوان؛ فمن آمن في زمنِ القبولِ نجا، ومن أخّر حتى رأى البأسَ خسر؛ فلا تكن من الخاسرين الذين آمنوا حين لا ينفع الإيمان؛ بل بادر بالإيمانِ الصادقِ والعملِ الصالحِ الآن؛ فالسعيدُ من آمن قبل رؤيةِ البأس، والخاسرُ من أخّر حتى عاين العذاب؛ فبادر بالإيمانِ والتوبةِ في زمنِ الإمهال."}}]}],"coverage":{"covered":85,"total":85}};
